    /// A workspace card never loses its branch.
    ///
    /// The 1.4.158 compact row hid the branch when it duplicated the title,
    /// and this gate used to pin that. 1.4.164's card does not: `cardBody`
    /// draws the branch under the name even when they are the same word —
    /// the live capture in 1-w shows `main` over `main` — and only a folder
    /// project, which has no branch, is a title-only card. The metadata name
    /// stays the title; the branch stays under it, so a rename still cannot
    /// erase it.
    #[test]
    fn a_custom_workspace_name_preserves_its_branch() {
        let window = window_source();
        assert!(
            window.contains("wt-titlebox") && window.contains("wt-branch"),
            "a workspace row has no place for metadata name plus branch"
        );
        // The branch text sits in its own span so the line can elide the NAME
        // and keep the base chip that rides after it; the promise this gate
        // makes is unchanged — the line is hidden for a missing branch and
        // for nothing else.
        assert!(
            window.contains("name.textContent = worktree.branch ?? \"\";")
                && window.contains("branch.hidden = !name.textContent"),
            "the branch line is conditioned on something other than having a \
             branch"
        );
        let css = include_str!("../../../../ui/shell.css");
        let title = block_after_css(css, ".wt-titlebox {");
        assert!(
            title.contains("flex-direction: column"),
            "the name and branch do not stack into Orca's two-line card:\n{title}"
        );
        let topline = block_after_css(css, ".wt-topline {");
        assert!(
            topline.contains("align-items: baseline") && topline.contains("gap: 6px"),
            "the name and its badge do not share Orca's baseline:\n{topline}"
        );
    }

