    /// The sidebar stands in the original's four fixed layers.
    ///
    /// Measured from the source this replicates: the column is
    /// `flex flex-col overflow-hidden` (components/sidebar/index.tsx:110)
    /// holding a fixed nav that ENDS in the palette's search button
    /// (SidebarNav.tsx:305) and STARTS with the setup entry (:109), a fixed
    /// header whose title is the grouping's own name — bare `'Projects'` /
    /// `'Workspaces'`, stamped on `data-sidebar-section-title`
    /// (SidebarHeader.tsx:21,28) — one scrolling list viewport
    /// (VirtualizedWorktreeViewport.tsx:352), and a fixed toolbar whose right
    /// pair is the crosshair and the board toggle wearing `aria-pressed`
    /// (SidebarToolbar.tsx:78-119). The board door used to be a nav row and
    /// the whole column used to scroll.
    #[test]
    fn the_sidebar_wears_its_original_frame() {
        let markup = include_str!("../../../../ui/index.html");
        let aside = markup_between(markup, "<aside class=\"threads\"", "</aside>");
        let at = |needle: &str| {
            aside
                .find(needle)
                .unwrap_or_else(|| panic!("`{needle}` is not in the sidebar column"))
        };
        let nav = at("<nav class=\"nav-rows\"");
        let nav_end = at("</nav>");
        let title = at("id=\"sidebar-title\"");
        let scroll = at("id=\"sidebar-scroll\"");
        let foot = at("<div class=\"sidebar-foot\">");
        assert!(
            nav < nav_end && nav_end < title && title < scroll && scroll < foot,
            "the four layers are out of the original's order"
        );
        for inside_nav in ["id=\"guide-entry\"", "id=\"sidebar-search\""] {
            let found = at(inside_nav);
            assert!(
                nav < found && found < nav_end,
                "`{inside_nav}` does not stand inside the nav layer"
            );
        }
        for inside_scroll in ["id=\"worktrees\"", "id=\"ssh-hosts-stack\""] {
            let found = at(inside_scroll);
            assert!(
                scroll < found && found < foot,
                "`{inside_scroll}` does not ride the one scrolling layer"
            );
        }
        for inside_foot in [
            "id=\"foot-reveal\"",
            "id=\"nav-agents\"",
            "id=\"nav-board\"",
        ] {
            assert!(
                at(inside_foot) > foot,
                "`{inside_foot}` is not on the toolbar"
            );
        }

        let styles = include_str!("../../../../ui/shell.css");
        let column = block_after_css(styles, ".threads {");
        assert!(
            column.contains("overflow: hidden"),
            "the whole column still scrolls:\n{column}"
        );
        let viewport = block_after_css(styles, ".sidebar-scroll {");
        assert!(
            viewport.contains("flex: 1") && viewport.contains("overflow-y: auto"),
            "the list layer is not the one that takes the wheel:\n{viewport}"
        );

        let window = window_source();
        let heading = block_after(window, "function paintSidebarTitle() {");
        assert!(
            heading.contains("\"Projects\" : \"Workspaces\"")
                && heading.contains("dataset.sidebarSectionTitle"),
            "the heading is not the grouping's own bare name:\n{heading}"
        );
        let writer = block_after(window, "function setSidebarView(patch) {");
        assert!(
            writer.contains("paintSidebarTitle()"),
            "a groupBy change leaves the heading behind:\n{writer}"
        );
        let strip = block_after(window, "function renderTabs() {");
        assert!(
            strip.contains("const door = el(\"nav-agents\");")
                && strip.contains("door.setAttribute(\"aria-pressed\", pressed)"),
            "the agent-board door cannot say whether its tab is on stage:\n{strip}"
        );
        assert!(
            window.contains(
                "el(\"nav-board\").setAttribute(\"aria-pressed\", String(workspaceBoardOpen))"
            ),
            "the workspace-board door cannot say whether its sheet is open"
        );

        let tokens = include_str!("../../../../ui/tokens.css");
        assert!(
            tokens.contains("--nav-plane-accent-ink: #f0faf7;")
                && tokens.contains("--nav-plane-accent-ink: #171717;"),
            "the accent-foreground token is missing one of its two treatment modes"
        );
    }

