    #[test]
    fn a_silent_window_death_leaves_its_reason_in_the_black_box() {
        let shipped = shipped_backend();
        let native = include_str!("../../src/native_tray.rs");

        let installing = block_after(shipped, "fn install_window_panic_hook(");
        let recording = block_after(shipped, "fn record_panic(");
        assert!(
            installing.contains("std::panic::take_hook()")
                && installing.contains("std::panic::set_hook")
                && installing.contains("record_panic("),
            "a main-thread panic can still leave without a forced backtrace:\n{installing}"
        );
        assert!(
            recording.contains("std::backtrace::Backtrace::force_capture()")
                && recording.contains("note_window_event("),
            "the panic record no longer forces and writes its backtrace:\n{recording}"
        );
        let setup = block_after(shipped, ".setup(move |app| {");
        assert!(
            setup.contains("install_window_panic_hook(")
                && setup.find("install_window_panic_hook(") < setup.find("build_app_state("),
            "the panic hook is not armed before application state and the event loop"
        );
        assert!(
            block_after(shipped, "fn note_window_event(").contains("file.flush()"),
            "the black box can retain a panic in userspace while the process dies"
        );

        let running = block_after(shipped, "app.run(|handle, event| {");
        for reason in [
            "tauri::RunEvent::ExitRequested",
            "tauri::RunEvent::Exit =>",
            "tauri::WindowEvent::Destroyed",
        ] {
            assert!(
                running.contains(reason),
                "the normal shutdown road does not record `{reason}`"
            );
        }
        assert!(
            native.contains("exit requested: native tray quit")
                && native.find("exit requested: native tray quit") < native.find("app.exit(0)"),
            "the tray quit gesture reaches app.exit without naming its reason"
        );
    }

    /// The change row speaks Orca's whole sentence, and the diff header
    /// quotes the same list — the G1·G2 slice of the SCM parity order.
    ///
    /// Five contracts, each one a way this surface quietly said less than
    /// the original:
    ///
    /// - **The row's doors** (`entry-context-menu.tsx`, `uncommitted-entry-
    ///   row.tsx:117-190): a context menu with view/reveal/both copies, a
    ///   draggable row whose payload is the ABSOLUTE path (a terminal or a
    ///   composer can take it as typed), and a per-row review-note marker —
    ///   the menu reuses the file tree's own keys because the two panels
    ///   name the same verbs, and inventing a second set would let the two
    ///   drift apart one locale at a time.
    /// - **A conflict says which kind in the row body** (`conflictLabel`,
    ///   uncommitted-entry-row.tsx:165-167): `DU` and `UD` need opposite
    ///   work, and a fact you must hover to learn is a fact half-said.
    /// - **View all** (`getSourceControlSectionViewAction` → combined diff
    ///   scoped to the area, section-order.ts:53-73): each section head
    ///   opens the combined surface narrowed to ITS paths — the entries
    ///   filtered by the same grouping the head counts (`scmGroupPaths`),
    ///   each section fetching its own diff as it approaches (G3's lazy
    ///   road). Conflicts keeps no such door: its original head action is
    ///   the conflict REVIEW, and that surface's card already stands.
    /// - **Word-level emphasis** (DiffViewer's Monaco inline marks): the
    ///   changed span inside a paired del/add line, found by common head
    ///   and tail. The `head === 0 && tail === 0` skip is load-bearing —
    ///   a wholly different line washed edge to edge reads as emphasis
    ///   saying nothing.
    /// - **The header quotes the list; the eye keeps its place**
    ///   (DiffViewer's header facts and LRU scroll cache): status letter
    ///   and ± ride the diff head only while the panel's list actually
    ///   holds that path — a committed diff must not wear a working-tree
    ///   claim — and the tally is built by the ONE builder the row uses,
    ///   so the two surfaces cannot learn to disagree. The scroll seat is
    ///   assigned, not listened for, because this painter runs on every
    ///   repaint and stacked listeners would fight over one offset.
    #[test]
    fn the_scm_row_speaks_orcas_sentence_and_the_diff_head_quotes_it() {
        let markup = include_str!("../../../../ui/index.html");
        let window = window_source();
        let styles = include_str!("../../../../ui/shell.css");

        // The row's doors, on the row the panel actually paints.
        let row = block_after(window, "function scmRow(");
        assert!(
            row.contains("row.addEventListener(\"contextmenu\", (event) => {")
                && row.contains("t(\"tree.menu.viewFile\", \"파일 보기\")")
                && row.contains("invoke(\"fs_reveal\", { path: treeAbsolute(entry.path) })")
                && row.contains("run: () => clipboardText.write(treeAbsolute(entry.path)),")
                && row.contains("run: () => clipboardText.write(entry.path),"),
            "the change row lost its context menu, or the menu stopped \
             speaking the file tree's own verbs:\n{row}"
        );
        assert!(
            row.contains("row.draggable = true;")
                && row.contains(
                    "event.dataTransfer.setData(\"text/plain\", treeAbsolute(entry.path));"
                ),
            "the row stopped leaving the panel as its file — the drag \
             payload must be the absolute path, as a terminal would type \
             it:\n{row}"
        );
        // The original's own guard on that drag (uncommitted-entry-row.tsx:
        // 119-122): a conflict whose file is GONE from the working tree —
        // DD, DU — must not leave as a payload nothing can open. UD drags:
        // they deleted it, our side still holds the file.
        assert!(
            row.contains(
                r#"if (entry.conflict && (entry.code === "DD" || entry.code === "DU")) {"#
            ),
            "a conflict-deleted row drags a dead path again:\n{row}"
        );
        // And the Open-in group (entry-context-menu.tsx:116-154), through the
        // FILE door and the workspace menu's own reused words — no second
        // catalog family for the same verbs.
        assert!(
            row.contains("...openInApplications.map((application) => ({")
                && row.contains("invoke(\"open_path_in_application\", {")
                && row.contains("t(\"worktree.customizeApps\", \"앱 사용자화…\")"),
            "the row menu lost its Open-in group or grew its own words:\n{row}"
        );
        assert!(
            row.contains("const said = diffNotes.filter(")
                && row.contains("marker.className = \"scm-notes\";")
                && row.contains("row.querySelector(\".scm-tally\").before(marker);"),
            "a file with review notes no longer says so on its row:\n{row}"
        );
        assert!(
            row.contains("kindLine.className = \"scm-conflict-kind\";")
                && row.contains("kindLine.textContent = entry.conflict;"),
            "a conflicted row stopped printing which KIND of conflict in \
             its body — two letters in a badge do not say whose deletion \
             this was:\n{row}"
        );

        // View all: three doors in the markup, none for conflicts, and the
        // one behind them filters the one combined read by the group's own
        // paths.
        for id in [
            "scm-changed-view-all",
            "scm-staged-view-all",
            "scm-untracked-view-all",
        ] {
            assert_eq!(
                markup.matches(&format!("id=\"{id}\"")).count(),
                1,
                "the section head lost or duplicated its View-all door #{id}"
            );
        }
        assert!(
            !markup.contains("scm-conflicts-view-all"),
            "the conflicts head grew a View-all door — its original action \
             is the conflict review, and that card already stands"
        );
        let grouping = block_after(
            window,
            "function scmGroupPaths(group, entries = scmEntries) {",
        );
        assert!(
            grouping.contains("entry.staged && !entry.conflict")
                && grouping.contains("entry.code === \"??\" && !entry.conflict")
                && grouping.contains("entry.changed && !entry.conflict && entry.code !== \"??\""),
            "the View-all grouping stopped matching what the sections \
             themselves show:\n{grouping}"
        );
        let viewing = block_after(window, "async function openChangesArea(area = null) {");
        assert!(
            viewing.contains("area ? scmGroupPaths(area, entries) : entries")
                && viewing.contains("changesSectionsFromEntries(listed)"),
            "View all stopped narrowing the entries by the section's own \
             grouping:\n{viewing}"
        );

        // Word-level emphasis: paired lines only, both sides marked, and a
        // wholly different line left alone.
        let words = block_after(window, "function diffWordSpans(lines) {");
        assert!(
            words.contains("const pairs = Math.min(adds - dels, at - adds);")
                && words.contains("if (head === 0 && tail === 0) continue;")
                && words.contains("marks.set(dels + pair, [head, before.length - tail]);")
                && words.contains("marks.set(adds + pair, [head, after.length - tail]);"),
            "the word emphasis lost its pairing or its nothing-in-common \
             skip:\n{words}"
        );
        let lines = block_after(
            window,
            "function paintDiffLines(body, path, lines, repaint) {",
        );
        let row = block_after(window, "function diffLineNode(line, marked) {");
        assert!(
            lines.contains("const words = diffWordSpans(lines);")
                && lines.contains("const row = diffLineNode(line, words.get(index));")
                && row.contains("word.className = \"diff-word\";")
                && row
                    .contains("text.append(line.text.slice(0, from), word, line.text.slice(to));"),
            "the shared row painter stopped wearing the word marks — the \
             single view, the combined view and the conversation's inline diff \
             lose them together:\n{lines}\n{row}"
        );
        // The conversation's inline diff draws that same row — the rows its
        // clip shows first, the rest when its door opens them (t-6323) —
        // and the approval card draws the edit it asks about with it.
        let inline = block_after(window, "function toolDiffNode(edits, spoken = \"\") {");
        let cut = block_after(window, "function diffRowsNode(edit, words) {");
        assert!(
            inline.contains("const words = diffWordSpans(edit.lines);")
                && inline.contains("diffRowsNode(edit, words)")
                && cut.contains("diffLineNode(edit.lines[at], words.get(at))"),
            "the inline diff under an edit row grew its own row painter:\n{inline}\n{cut}"
        );
        let approving = block_after(window, "function approvalPanelNode(card, draft) {");
        assert!(
            approving.contains("toolDiffNode(card.approval.edits"),
            "the approval card no longer shows the edit it asks about:\n{approving}"
        );
        for kind in ["add", "del"] {
            assert!(
                styles.contains(&format!(
                    ".diff-line--{kind} .diff-word {{\n  background: color-mix(in srgb, var(--diff-{kind}) 32%, transparent);"
                )),
                "the {kind} word mark stopped riding its own line's \
                 diff token"
            );
        }

        // The header's facts: present only while the panel's list holds the
        // path, tally from the one builder, letter in the decoration ink.
        assert_eq!(
            markup.matches("class=\"diff-head-facts\"").count(),
            1,
            "the diff head lost its facts span"
        );
        let painting = block_after(window, "function paintDiffView(tab) {");
        assert!(
            painting.contains("const entry = scmEntries.find((held) => held.path === tab.path);")
                && painting.contains("facts.hidden = !entry;")
                && painting
                    .contains("paintScmTally(facts.querySelector(\".diff-head-tally\"), entry);")
                && painting.contains("status.dataset.git = gitDecorationOf(entry.code);"),
            "the diff head stopped quoting the panel's own row — or quotes \
             it for a diff the panel is not showing:\n{painting}"
        );
        assert_eq!(
            window.matches("paintScmTally(").count(),
            3,
            "the ± tally grew a second builder — the row and the diff head \
             must read one"
        );

        // The scroll seat: remembered per file, restored on repaint, bounded,
        // and assigned rather than accumulated.
        assert!(
            window.contains("const diffScrollMemory = new Map();")
                && window.contains("const DIFF_SCROLL_MEMORY_CAP = 50;"),
            "the per-file scroll memory lost its seat or its bound"
        );
        assert!(
            painting.contains("body.scrollTop = diffScrollMemory.get(tab.path) ?? 0;")
                && painting.contains("body.onscroll = () => {")
                && painting
                    .contains("diffScrollMemory.delete(diffScrollMemory.keys().next().value);"),
            "a repaint stopped putting the reader back where they were, or \
             the memory stopped letting its oldest seat go:\n{painting}"
        );

        // The two new sentences exist in all four catalogues.
        for key in ["\"sourceControl.viewAll\":", "\"sourceControl.rowNotes\":"] {
            assert_eq!(
                window.matches(key).count(),
                4,
                "{key} is not spoken in all four catalogues"
            );
        }
    }

    /// Many rows can be chosen, and the bar says what they can do — the G4b
    /// slice of the SCM parity order.
    ///
    /// - **A row's name carries its AREA** (`${area}::${path}`, the
    ///   original's own key grammar): the same file staged and edited again
    ///   is two rows, and stage and unstage are two different rows' work.
    /// - **Three gestures** (use-selection.ts `handleSelect`): a plain click
    ///   drops any selection, sets the anchor and opens the file — and when a
    ///   selection was standing, dropping it IS the click's work; ⌘/Ctrl
    ///   toggles one row, moving the anchor only when it adds; Shift takes
    ///   the anchor-to-here range **in visible order**. A Shift click with no
    ///   valid anchor falls back to the plain click rather than measuring a
    ///   range from a row nobody can see (the original's own reason).
    /// - **The visible order is the DOM's**: a folded section builds no rows,
    ///   a filtered-out row is not there, and the section-order preference is
    ///   already applied — so reading the rows is reading the order.
    /// - **Rows that leave take their selection with them**
    ///   (`reconcileSourceControlSelectionState`): staging, filtering and a
    ///   status refresh all remove rows, and a bar counting keys that point
    ///   at nothing is counting nothing.
    /// - **The verbs split by area** (`isStageableStatusEntry` and its
    ///   twin): stage is the working tree's and untracked's, never an
    ///   unresolved conflict's — `git add` there clears the `u` record before
    ///   anyone has reviewed it — and unstage is the staged area's.
    /// - **A finished bulk clears the selection** (the original refreshes,
    ///   then `clearSelection`): the rows just staged moved to another
    ///   section, and the old keys are not where the selection thinks.
    /// - **Escape and an outside pointerdown end it**, the latter in the
    ///   CAPTURE phase so the click that lands elsewhere does not arrive with
    ///   a stale selection still standing.
    #[test]
    fn many_rows_can_be_chosen_and_the_bar_says_what_they_can_do() {
        let markup = include_str!("../../../../ui/index.html");
        let window = window_source();
        let styles = include_str!("../../../../ui/shell.css");

        // The key, and the row that wears it.
        assert!(
            block_after(window, "function scmRowKey(entry, group) {")
                .contains("return `${group}::${entry.path}`;"),
            "the row key stopped carrying its area — one file in two areas \
             would collapse into one selectable row"
        );
        let row = block_after(window, "function scmRow(entry, group) {");
        assert!(
            row.contains("row.dataset.scmKey = scmRowKey(entry, group);")
                && row.contains("actsAsButton(row, (event) => {")
                && row.contains("scmSelectRow(event, row.dataset.scmKey, entry, group);"),
            "the change row no longer answers the selection:\n{row}"
        );

        // The three gestures.
        let choosing = block_after(window, "function scmSelectRow(event, key, entry, group) {");
        assert!(
            choosing.contains("if (from !== -1 && to !== -1) {")
                && choosing.contains(
                    "for (let at = Math.min(from, to); at <= Math.max(from, to); at += 1) {"
                ),
            "Shift stopped taking the anchor-to-here range:\n{choosing}"
        );
        assert!(
            choosing.contains("if (scmSelected.has(key)) {")
                && choosing.contains("scmAnchorKey = key;"),
            "⌘/Ctrl stopped toggling one row:\n{choosing}"
        );
        assert!(
            choosing.contains("const had = scmSelected.size > 0;")
                && choosing.contains("if (!had) void openDiff(entry.path, { preview: true });"),
            "a plain click on a standing selection opens a file instead of \
             ending the selection:\n{choosing}"
        );
        assert!(
            block_after(window, "function scmVisibleKeys() {")
                .contains("#activity-scm .scm-row[data-scm-key]"),
            "the visible order stopped being read off the rows themselves — a \
             folded or filtered row would join a Shift range nobody can see"
        );

        // Rows that leave take their selection with them, on every repaint.
        assert!(
            block_after(window, "function reconcileScmSelection() {")
                .contains("if (!standing.has(key)) scmSelected.delete(key);"),
            "a selection key outlives the row it names"
        );
        let painting = block_after(window, "function paintScm() {");
        assert!(
            painting.contains("reconcileScmSelection();")
                && painting.contains("dressScmSelection();"),
            "the repaint stopped pruning and re-dressing the selection:\n{painting}"
        );

        // The verbs split by area, and a finished bulk lets go.
        assert!(
            block_after(window, "function scmBulkStagePaths() {").contains(
                ".filter((one) => one.group !== \"staged\" && !one.entry.conflict && canStage(one.entry))"
            ),
            "bulk stage would take a staged row, an unresolved conflict, or a \
             submodule the parent index cannot reach"
        );
        // 그리고 그 마지막 갈래는 절 전체 손에도 같은 문장으로 걸려 있어야 한다 —
        // "전체"가 조용히 "하나 빼고 전체"가 되는 것이 행에서 손을 빼는 것보다
        // 나쁘고, 두 도로가 다른 문장을 쓰면 그 날이 온다.
        let sectioning = block_after(window, "function scmSectionPaths(group) {");
        assert!(
            sectioning.contains("&& canStage(entry)"),
            "Stage All takes a submodule whose dirtiness lives inside it, where \
             the parent index cannot reach:\n{sectioning}"
        );
        assert!(
            block_after(window, "function scmBulkUnstagePaths() {")
                .contains(".filter((one) => one.group === \"staged\")"),
            "bulk unstage reaches outside the staged area"
        );
        let running = block_after(window, "async function runScmBulkSelection(paths, verb) {");
        assert!(
            running.contains("if (paths.length === 0 || scmBulkRunning) return;")
                && running.contains("clearScmSelection();"),
            "a bulk verb re-enters, or keeps a selection whose rows have \
             moved to another section:\n{running}"
        );

        // Escape is a RUNG on the window's one keyboard road, not a second
        // listener — this window has exactly one place that decides where a
        // key goes, and it stands before the read-surface rung because a
        // selection is the lighter state: Escape means the thing just made,
        // not the document underneath it.
        let road = block_after(
            window,
            "window.addEventListener(\"keydown\", (event) => {\n  if (hasPrimaryModifier(event)) {",
        );
        let cleared = road.find("clearScmSelection();").unwrap_or_else(|| {
            panic!("Escape stopped clearing the source-control selection:\n{road}")
        });
        let reading = road
            .find("const reading = currentTab();")
            .expect("the read-surface rung");
        assert!(
            cleared < reading,
            "the selection rung fell behind the read-surface rung, so Escape \
             closes the document instead of ending the selection"
        );
        // And the capture-phase outside click.
        assert!(
            window.contains(
                "document.addEventListener(\"pointerdown\", (event) => {\n  if (scmSelected.size === 0) return;"
            ) && window.contains("}, true);"),
            "the outside click no longer ends the selection in the capture \
             phase, so the next surface sees a stale one"
        );

        // The bar itself: count, the two verbs, the clear.
        for id in [
            "id=\"scm-bulk\"",
            "id=\"scm-bulk-count\"",
            "id=\"scm-bulk-stage\"",
            "id=\"scm-bulk-unstage\"",
            "id=\"scm-bulk-clear\"",
        ] {
            assert_eq!(
                markup.matches(id).count(),
                1,
                "the bulk bar lost or duplicated {id}"
            );
        }
        let bar = block_after(window, "function paintScmBulkBar() {");
        assert!(
            bar.contains("bar.hidden = scmSelected.size === 0;")
                && bar.contains("stage.hidden = staging.length === 0;")
                && bar.contains("unstage.hidden = unstaging.length === 0;"),
            "the bar stands with nothing selected, or offers a verb with \
             nothing to do:\n{bar}"
        );
        assert!(
            bar.contains("count.classList.toggle(\"is-busy\", scmBulkRunning);"),
            "the bar's count stopped becoming a spinner while a verb runs"
        );
        assert!(
            block_after_css(styles, ".scm-bulk {").contains("position: sticky;"),
            "the bulk bar stopped floating over the bottom of the list"
        );
    }

    /// The notes a checkout is carrying stand in one place — the G5a slice of
    /// the SCM parity order.
    ///
    /// Notes are born on diff lines, and until now the only way to learn how
    /// many there were and where was to walk the diffs. The shelf
    /// (notes-shelf.tsx, seated between the header and the commit surface —
    /// panel-ready.tsx:91) answers that in one row: grouped by file, each note
    /// wearing its line label and its body, each a door back to the line it
    /// hangs from.
    ///
    /// - **Zero notes, no shelf** — the original's own reason: "notes are
    ///   created from the diff view, so an empty Notes shelf here is pure
    ///   chrome."
    /// - **Grouped by file, ordered by line** (diff-comments-list.tsx's two
    ///   rules), with the file's own name a door and its own sweep.
    /// - **One clear door, two scopes** (`PendingDiffCommentsClear`'s
    ///   `{kind:'all'}` / `{kind:'file'}`): `clear_diff_notes` takes the
    ///   workspace always and a path optionally, so "clear all" can never
    ///   reach past this checkout — and both ask first, because a note is
    ///   something a person wrote.
    /// - **The send hand carries EVERYTHING** from the shelf (the original
    ///   hands the shelf's menu the whole comment list) while a file header's
    ///   hand still carries its own file's.
    /// - **A note opens to its line**: the file's diff, then the card itself
    ///   (`scrollToDiffCommentId`'s job here) or the line it hangs from.
    ///
    /// Two chips the original wears have no producer here and are recorded
    /// rather than faked: the MD/Diff source mark (our notes carry no origin
    /// surface) and `Sent` (our delivery REMOVES delivered notes —
    /// `clear_delivered_diff_notes` — so a sent note is not a state we hold).
    #[test]
    fn the_notes_a_checkout_carries_stand_in_one_place() {
        let markup = include_str!("../../../../ui/index.html");
        let window = window_source();
        let styles = include_str!("../../../../ui/shell.css");
        let house = shipped_backend();
        let (shipped, _) = house.split_once("#[cfg(test)]").unwrap_or((house, ""));

        // The shelf's seat: after the branch context row, before the commit
        // surface — the original's own order.
        let at = |needle: &str| {
            markup
                .find(needle)
                .unwrap_or_else(|| panic!("`{needle}` is gone from ui/index.html"))
        };
        assert!(
            at("id=\"scm-compare\"") < at("id=\"notes-shelf\"")
                && at("id=\"notes-shelf\"") < at("id=\"commit-box\""),
            "the notes shelf left its seat between the header and the commit \
             surface"
        );
        for id in [
            "id=\"notes-shelf-fold\"",
            "id=\"notes-shelf-count\"",
            "id=\"notes-shelf-send\"",
            "id=\"notes-shelf-copy\"",
            "id=\"notes-shelf-more\"",
            "id=\"notes-shelf-list\"",
        ] {
            assert_eq!(
                markup.matches(id).count(),
                1,
                "the notes shelf lost or duplicated {id}"
            );
        }

        let shelf = block_after(window, "function paintNotesShelf() {");
        assert!(
            shelf.contains("shelf.hidden = diffNotes.length === 0;"),
            "an empty shelf stands — chrome for a thing that is not there"
        );
        assert!(
            shelf.contains("const byFile = new Map();")
                && shelf
                    .contains("held.sort((left, right) => left.line_number - right.line_number);"),
            "the shelf stopped grouping by file and ordering by line:\n{shelf}"
        );
        // The list is a face of the note ledger, redrawn wherever it is reread.
        assert!(
            block_after(window, "async function refreshDiffNotes() {")
                .contains("paintNotesShelf();"),
            "re-reading the notes no longer redraws the shelf, so the count \
             and the list can disagree with the ledger"
        );

        // One clear door, two scopes — both asked first.
        let clearing = block_after(shipped, "fn clear_diff_notes(");
        assert!(
            clearing.contains("held.workspace != workspace") && clearing.contains("file_path"),
            "the sweep stopped being scoped to the workspace, or lost its \
             optional file:\n{clearing}"
        );
        assert!(
            house.contains("            delete_diff_note,\n            clear_diff_notes,"),
            "clear_diff_notes is not registered — an unregistered door is a \
             button that does nothing"
        );
        let asking = block_after(window, "async function askClearNotes(filePath = null) {");
        assert!(
            asking.contains("await askConfirm({")
                && asking.contains("danger: true,")
                && asking.contains(
                    "invoke(\"clear_diff_notes\", { workspace: activeWorktreePath, filePath })"
                ),
            "clearing notes stopped asking first, or reaches past this \
             checkout:\n{asking}"
        );

        // The send hand's two scopes.
        let sending = block_after(window, "async function openNoteSend(button, path) {");
        assert!(
            sending.contains("path === null\n    ? diffNotes.slice()"),
            "the shelf's send hand no longer carries every note:\n{sending}"
        );

        // A note is a door back to its line.
        let opening = block_after(window, "async function openNoteAt(note) {");
        assert!(
            opening.contains("await openDiff(note.file_path, { preview: true });")
                && opening.contains(".note-card[data-note=")
                && opening.contains("scrollIntoView({ block: \"center\" })"),
            "opening a note stopped landing on the line it hangs from:\n{opening}"
        );
        assert!(
            block_after(window, "function noteCard(host, note) {")
                .contains("card.dataset.note = note.id;"),
            "the note card lost the name the shelf finds it by"
        );

        // The list's own hover-revealed hands, focus included.
        assert!(
            styles.contains(".notes-row:hover .notes-row-act,\n.notes-row-act:focus-visible {"),
            "the note row's hands stopped appearing for the keyboard as well \
             as the pointer"
        );
    }

    /// The review a checkout wears is the review of the branch it is on.
    ///
    /// `gh pr view` answers about whatever HEAD stands on, so a mark is only
    /// meaningful with its branch beside it. The original scopes its own
    /// snapshot by repo, worktree AND branch — "scoped so a response for a
    /// previous target is ignored" (use-hosted-review-state.ts:13-14) — and
    /// refetches the moment the branch changes rather than at the next beat
    /// ("fetch review immediately on branch change",
    /// use-hosted-review-polling.ts:74).
    ///
    /// What is pinned here is the window half; the Rust half (the answer
    /// carrying its branch, the cache keyed by both, and a branchless
    /// checkout never costing a `gh` process) is driven for real in
    /// `the_board_asks_about_a_checkout_once_and_believes_the_answer_for_a_minute`.
    ///
    /// The load-bearing one is the LAST: every surface reads the review
    /// through `scmReviewNow()`, which gates on the target. One direct read of
    /// `scmReview` anywhere else is a pill — or a hidden create door — wearing
    /// the previous branch's pull request.
    #[test]
    fn the_review_a_checkout_wears_belongs_to_the_branch_it_is_on() {
        let window = window_source();

        // The target is the pair, and no branch means no question.
        let target = block_after(window, "function scmReviewTarget() {");
        assert!(
            target.contains("const branch = scmCompareContext?.head ?? null;")
                && target.contains("`${activeWorktreePath}\\n${branch}`"),
            "the review's target stopped being a checkout AND its branch:\n{target}"
        );
        let asking = block_after(window, "async function refreshScmReview() {");
        assert!(
            asking.contains("const target = scmReviewTarget();")
                && asking.contains("if (!target) {")
                && asking.contains("if (target !== scmReviewTarget()) return;")
                && asking.contains("one.worktree === asked && one.branch === branch"),
            "the review lookup stopped refusing a branchless checkout, or \
             stopped checking that the answer is still the one it asked \
             for:\n{asking}"
        );
        assert!(
            block_after(window, "function scmReviewNow() {")
                .contains("scmReviewAt !== null && scmReviewAt === scmReviewTarget()"),
            "the review is no longer penned inside the target it was measured \
             for"
        );

        // A branch change is not something to notice on the next beat.
        assert!(
            block_after(window, "async function refreshSourceControlCompare() {")
                .contains("if (scmReviewAt !== scmReviewTarget()) void refreshScmReview();"),
            "a new branch keeps the old branch's review until something else \
             happens to ask"
        );

        // Not knowing yet shuts the door — on both surfaces, with one word.
        assert!(
            block_after(window, "function scmPrDoorFace() {")
                .contains("if (scmReviewAsking || (!eligibility && scmEligibilityPending)) {"),
            "the create door stopped standing down while the review lookup is \
             still out"
        );
        assert!(
            block_after(window, "function scmPrimaryDecision() {").contains("if (scmReviewAsking)"),
            "the primary button and the header door disagree about a review \
             nobody has confirmed yet"
        );

        // And nothing reads the raw mark.
        let bare = |line: &str| {
            line.match_indices("scmReview").any(|(at, _)| {
                line[at + "scmReview".len()..]
                    .chars()
                    .next()
                    .is_none_or(|next| !next.is_alphanumeric() && next != '_')
            })
        };
        // Its own lookup and its own gate are where the raw mark lives.
        let penned = block_after(window, "function scmReviewNow() {");
        let elsewhere: Vec<&str> = window
            .lines()
            .filter(|line| bare(line))
            .filter(|line| {
                !asking.contains(*line)
                    && !penned.contains(*line)
                    && !line.starts_with("let scmReview")
            })
            .collect();
        assert!(
            elsewhere.is_empty(),
            "the review mark is read outside its own lookup, so these lines \
             can show a previous branch's pull request:\n{}",
            elsewhere.join("\n")
        );
    }

    /// A forge this window cannot create on still has a door.
    ///
    /// `gh` speaks to GitHub. Until now a GitLab or Bitbucket or Azure DevOps
    /// checkout got a create door that simply was not there, and nothing in
    /// its place. The original keeps a second road for exactly this: the
    /// provider's own "new merge request" page, built from the remote
    /// (`remote-repo.ts` + `manual-review-url.ts`) and seated at the trailing
    /// edge of the branch context row (`ManualReviewLinkButton`,
    /// branch-context-row.tsx:76-96).
    ///
    /// The URL builder itself is driven for real in `remote_repo`'s own
    /// tests — every provider's page shape, and every one of the refusals,
    /// because a link that lands on "There isn't anything to compare" is worse
    /// than no link. What is pinned here is that the window can reach it: the
    /// seat, the one fact it paints from, and the door it leaves through.
    #[test]
    fn the_forge_this_window_cannot_create_on_still_has_a_door() {
        let markup = include_str!("../../../../ui/index.html");
        let window = window_source();

        // The trailing edge of the branch context row's flow — after the
        // compare hands, inside the same line.
        let at = |needle: &str| {
            markup
                .find(needle)
                .unwrap_or_else(|| panic!("`{needle}` is gone from ui/index.html"))
        };
        assert!(
            at("id=\"scm-committed-open\"") < at("id=\"scm-compare-review\"")
                && at("id=\"scm-compare-review\"") < at("id=\"scm-compare-note\""),
            "the review-page link left the trailing edge of the compare row"
        );
        let link = block_after(markup, "id=\"scm-compare-review\"");
        assert!(
            link.contains("#i-external"),
            "the link out stopped looking like one:\n{link}"
        );

        // It paints from the ladder's answer and nothing else, so a checkout
        // whose link cannot be built shows no hand at all.
        let painting = block_after(window, "function paintManualReviewLink() {");
        assert!(
            painting.contains("const url = scmEligibility?.manual_url ?? null;")
                && painting.contains("link.hidden = !url;"),
            "the review-page link is no longer a function of the one fact that \
             can build it:\n{painting}"
        );

        // The window hands the URL back to Rust rather than opening it, so the
        // scheme check cannot be skipped by a caller who forgot.
        assert!(
            window.contains("el(\"scm-compare-review\").addEventListener(\"click\", () => {")
                && block_after(window, "el(\"scm-compare-review\").addEventListener")
                    .contains("openExternal(url)"),
            "the review-page link opens without passing the backend's guard"
        );

        // The upstream's NAME is half the link — which branch is actually on
        // the remote — so the ladder is asked with it, and asked again when it
        // moves.
        let asked = block_after(window, "async function refreshHostedReviewEligibility() {");
        assert!(
            asked.contains("upstreamName: upstreamState?.upstream ?? null,"),
            "the ladder is asked without the upstream it would build the link \
             from:\n{asked}"
        );
        assert!(
            block_after(window, "function scmEligibilitySignature() {")
                .contains("upstreamState?.upstream ?? null,"),
            "publishing a branch no longer re-asks, so its review page link \
             would never appear"
        );
    }

    /// The title bar offers the command the settings name.
    ///
    /// Orca's `▷ 명령` sits at the right of that row. Ours is the same thing
    /// this product already has a setting for: open a terminal running it.
    #[test]
    fn the_title_bar_offers_the_command() {
        let markup = include_str!("../../../../ui/index.html");
        let bar = markup_between(markup, "<header class=\"titlebar\"", "</header>");

        assert!(
            bar.contains("id=\"run-command\""),
            "the title bar has no way to run the configured command:\n{bar}"
        );
    }

    /// Both ends of the save contract move together.
    ///
    /// `write_text_file` grew a `version` argument, and a window that does not
    /// send it would have every save refused — or, worse, silently accepted if
    /// somebody later made the argument optional to quieten that. The read has
    /// to be unwrapped on the window side too: its answer is an object now, and
    /// dropping it straight into the field puts `[object Object]` in the file.
    #[test]
    fn the_save_contract_is_the_same_on_both_ends() {
        let window = strip_comments(window_source());
        assert!(
            window.contains("invoke(\"write_text_file\", {")
                && window.contains("version: tab.version"),
            "the window saves without saying which version it read"
        );
        assert!(
            window.contains("read_text_file") && window.contains(".version"),
            "the window drops the version the read hands it"
        );
        assert!(
            window.contains("file_version"),
            "nothing asks whether the file moved while the tab sat there"
        );
    }

    /// Unsaved typing is never thrown away by a close.
    ///
    /// Every other close in this window is reversible — a terminal can be
    /// opened again, a tab is on the reopen stack, a lane is in the ledger.
    /// Edits that were never written are the one thing that is gone, so this
    /// is the one close that asks first.
    #[test]
    fn an_unsaved_file_is_not_closed_without_asking() {
        let window = window_source();
        let closing = block_after(window, "function closeTab(id) {");
        assert!(
            closing.contains("letGoOf(tab)"),
            "closing a document does not go through the door that asks about \
             unsaved typing:\n{closing}"
        );
        let door = block_after(window, "async function letGoOf(tab) {");
        assert!(
            door.contains("if (isDirty(tab)) {") && door.contains("askAboutLosing(tab)"),
            "a file with unsaved edits is let go of without a word:\n{door}"
        );
        // Changing the checkout under a document is the same question as
        // closing it, and it is asked BEFORE anything moves — an answer
        // offered after the root changed would be answered about a file the
        // window is no longer looking at.
        for name in [
            "async function activateWorktree(",
            "async function switchProject(path) {",
        ] {
            let body = block_after(window, name);
            assert!(
                body.contains("if (!(await letGoOfDocuments())) return"),
                "`{name}` moves the checkout out from under the open \
                 documents without asking:\n{body}"
            );
        }

        // And re-opening one does not quietly re-read over the draft: the
        // tree, quick open and the history arrows all land in `openFile`, and
        // a click that means "go there" must not mean "discard that".
        let opening = block_after(window, "async function openFile(path, opts = {}) {");
        assert!(
            opening.contains("if (isDirty(held)) {"),
            "opening a file that is already open with edits re-reads over \
             them:\n{opening}"
        );

        // Saving moves the comparison baseline to the exact draft that write
        // owned. If typing continued during I/O, the newer draft stays dirty.
        let saving = block_after(window, "async function saveFile(tab) {");
        assert!(
            saving.contains("const draft = tab.draft;")
                && saving.contains("tab.text = draft;")
                && saving.contains("tab.saved = tab.draft === draft;"),
            "a save does not move the mark it is measured against:\n{saving}"
        );
    }

    /// ⌘F searches the file, and searches the source of it.
    ///
    /// A rendered preview has no offsets to select into, so finding in one
    /// would either search text the person cannot point at or quietly do
    /// nothing. It switches to the source instead — the thing the matches are
    /// actually in.
    #[test]
    fn finding_in_a_file_searches_what_can_be_pointed_at() {
        let window = window_source();
        let opening = block_after(window, "function openFind() {");
        assert!(
            opening.contains("tab.raw = true;"),
            "finding in a preview searches something with nowhere to put a \
             selection:\n{opening}"
        );

        let running = block_after(window, "function runFind(tab, step) {");
        assert!(
            running.contains("selection: { anchor: at.from, head: at.to }"),
            "a match is counted but never shown:\n{running}"
        );
        assert!(
            running.contains("scrollIntoView: true"),
            "a match below the fold is selected where nobody can see it. The \
             textarea needed the line worked out and the scroll set by hand; \
             the editor is asked, in the same transaction that selects:\n{running}"
        );

        // The bar is markup that the second leaf gets as a clone, and a clone
        // carries no listeners — so it is wired where leaves are made. Which
        // surface owes which wiring is the view registry's to say, so this
        // asks for both halves: the hook that runs, and the file view naming
        // the find bar as the thing it hangs.
        let hosting = block_after(window, "function docHost(group, kind) {");
        assert!(
            hosting.contains("DOC_VIEWS[kind]?.wire?.(host)"),
            "a freshly built view is never handed to its own wiring:\n{hosting}"
        );
        let registry = block_after(window, "const DOC_VIEWS = {");
        assert!(
            registry
                .lines()
                .any(|line| line.trim_start().starts_with("file:")
                    && line.contains("wire: wireFind")),
            "the find bar in a split leaf has no working controls:\n{registry}"
        );
    }

    /// The document painters ask for classes the markup actually has.
    ///
    /// These functions reach into markup that lives in `ui/index.html`, and
    /// the three document views share one header — so its parts are addressed
    /// by class while their ids stay distinct. `paintDiffView` asked for
    /// `.diff-view-path`, which is the *id*: the query found nothing and the
    /// assignment threw on every repaint of a diff. Nothing caught it,
    /// because a class selector that matches nothing is not a syntax error.
    #[test]
    fn the_document_painters_ask_for_classes_that_exist() {
        let window = window_source();
        let markup = include_str!("../../../../ui/index.html");
        let painters = [
            "function paintFileView(tab) {",
            "function paintImageView(tab) {",
            "function paintDiffView(tab) {",
            "function paintEditor(view, tab) {",
            "function paintSaveNote(tab) {",
            "async function saveFile(tab) {",
            "function openFind() {",
            "function runFind(tab, step) {",
            "function wireFind(view) {",
        ];
        for name in painters {
            let body = block_after(window, name);
            // Only the queries against `view` — the markup host. A row these
            // functions built themselves carries whatever classes they just
            // gave it, and asking ui/index.html about those would be asking
            // the wrong file.
            for hit in body.split("view.querySelector(\".").skip(1) {
                let class = hit.split('"').next().unwrap_or_default();
                assert!(
                    markup.contains(&format!("class=\"{class}\""))
                        || markup.contains(&format!("class=\"{class} "))
                        || markup.contains(&format!(" {class}\""))
                        || markup.contains(&format!(" {class} ")),
                    "`{name}` asks for `.{class}`, which no element in \
                     ui/index.html carries — the query answers null and the \
                     line after it throws"
                );
            }
        }
    }

    /// The editor is CodeMirror 6, vendored, and Monaco is nowhere near it.
    ///
    /// Measured off `.re-scratch/asar-1.4.164` before choosing: Orca bundles
    /// Monaco 0.55.1 — 15 MB of `min/vs` on disk, 24.1 MB of editor payload in
    /// its renderer, +22.2 MB of main-thread heap for one editor, and five
    /// worker kinds including an 11.35 MB TypeScript 5.9.3 isolate that starts
    /// for every `.ts` tab. What it switches ON of that: syntax highlighting,
    /// find and replace, folding, multi-cursor, diff, external-change
    /// detection. What it leaves OFF: `MonacoLspClient` is bundled and never
    /// constructed (`new MonacoLspClient(` appears zero times in any version),
    /// all three diagnostic channels are disabled
    /// (`noSemanticValidation`/`noSuggestionDiagnostics`/`noSyntaxValidation`
    /// all true), `setExtraLibs` is never called, `defineTheme` is never
    /// called, and the minimap defaults off.
    ///
    /// So the whole of the working surface is reproduced by one 1.38 MB IIFE
    /// with no worker and no `blob:` URL — which is the entire performance
    /// argument of this product expressed in one file, and why the CSP below
    /// did not have to move.
    #[test]
    fn the_editor_is_vendored_codemirror_and_not_monaco() {
        let markup = include_str!("../../../../ui/index.html");
        let window = window_source();
        let styles = include_str!("../../../../ui/shell.css");
        let tokens = include_str!("../../../../ui/tokens.css");

        // The vendor file is loaded, and it is loaded BEFORE the window —
        // `defer` preserves document order, which is what lets `paintEditor`
        // read `window.CM6` without a loader or a readiness check.
        assert!(
            markup.contains("<script defer src=\"./vendor/cm6.js\"></script>"),
            "ui/index.html does not load the vendored editor, so `window.CM6` \
             is undefined the first time a file is opened"
        );
        let vendor_at = markup
            .find("./vendor/cm6.js")
            .expect("the vendor script tag was just asserted");
        let first = crate::ui_source::WINDOW_PARTS
            .first()
            .map(|(name, _)| format!("./{name}"))
            .expect("the window has at least one part");
        let window_at = markup
            .find(&first)
            .expect("ui/index.html has always loaded the window");
        assert!(
            vendor_at < window_at,
            "the editor is loaded after the window that uses it — with two \
             `defer` scripts the order in the markup IS the execution order"
        );

        // Monaco is not here, on any road.
        //
        // Not the WORD: this repository's comments cite Orca's Monaco
        // internals by file and line on every second page, and a ban on
        // writing "Monaco" would be a ban on explaining why it is not here.
        // What is banned is LOADING it — an asset path, a module id, an
        // environment hook, or a call into its API.
        for (name, body) in std::iter::once(("ui/index.html", markup))
            .chain(
                crate::ui_source::WINDOW_PARTS
                    .iter()
                    .map(|(name, body)| (*name, *body)),
            )
            .chain(std::iter::once(("ui/shell.css", styles)))
        {
            for smell in [
                "monaco-editor",
                "@monaco-editor",
                "MonacoEnvironment",
                "monaco.editor",
                "vs/editor",
                "min/vs",
                ".monaco-editor",
            ] {
                assert!(
                    !body.contains(smell),
                    "{name} reaches for Monaco (`{smell}`) — 15 MB on disk, \
                     +22 MB of heap and a TypeScript worker per tab is the \
                     cost that was measured and declined"
                );
            }
        }
        // And nothing else is loaded either: two scripts, in this order, both
        // of them ours. A third `<script src>` is how a CDN editor arrives.
        let sources: Vec<String> = markup
            .match_indices("<script defer src=\"")
            .map(|(at, opens)| {
                markup[at + opens.len()..]
                    .split('"')
                    .next()
                    .unwrap_or_default()
                    .to_string()
            })
            .collect();
        let mut expected = vec!["./vendor/cm6.js".to_string()];
        expected.extend(
            crate::ui_source::WINDOW_PARTS
                .iter()
                .map(|(name, _)| format!("./{name}")),
        );
        assert_eq!(
            sources, expected,
            "ui/index.html loads something other than the vendored editor and \
             this window's own files, or loads them in the wrong order"
        );

        // The highlight ramp is OURS. Orca calls `defineTheme` zero times and
        // picks between Monaco's stock themes with a boolean, then paints its
        // chrome to match; a white-label that does the same has Visual Studio
        // Code showing through the middle of it.
        // Again the string LITERAL, not the word — the comment above
        // `editorHighlightStyle` names Orca's two stock themes to say what we
        // are not doing, and that sentence is the point of the block.
        assert!(
            !window.contains("\"vs-dark\"") && !window.contains("'vs-dark'"),
            "the editor is themed with a stock editor theme instead of this \
             window's tokens"
        );
        let ramp = block_after(window, "function editorHighlightStyle() {");
        for role in [
            "--syntax-keyword",
            "--syntax-string",
            "--syntax-number",
            "--syntax-comment",
            "--syntax-function",
            "--syntax-type",
            "--syntax-variable",
            "--syntax-constant",
            "--syntax-invalid",
        ] {
            assert!(
                ramp.contains(&format!("var({role})")),
                "the highlight style does not read `{role}` — a colour it \
                 writes instead is a colour the treatment switch cannot \
                 reach:\n{ramp}"
            );
            // Both treatments, because a ramp declared once is a ramp that is
            // wrong in one of them.
            assert_eq!(
                tokens.matches(&format!("{role}:")).count(),
                2,
                "`{role}` is not declared in both the dark block and the \
                 light one"
            );
        }
        // The editor's furniture, in the same currency.
        let furniture = block_after(window, "function editorThemeExtension() {");
        for role in [
            "--editor-surface",
            "--editor-cursor",
            "--editor-selection",
            "--editor-line-band",
            "--editor-gutter-ink",
        ] {
            assert!(
                furniture.contains(&format!("var({role})")),
                "the editor theme does not read `{role}`:\n{furniture}"
            );
        }
        // And the search pair is the window's existing one, not a second
        // pair meaning the same thing in a different yellow.
        assert!(
            furniture.contains("var(--markdown-search-match)")
                && furniture.contains("var(--markdown-search-match-active)"),
            "the editor invented its own search colours beside the ones this \
             window already uses for a hit:\n{furniture}"
        );

        // No worker and no `blob:` in the vendored file — the two things that
        // would have forced `default-src 'self'` open.
        let vendored = include_str!("../../../../ui/vendor/cm6.js");
        for smell in ["new Worker(", "blob:", "importScripts("] {
            assert!(
                !vendored.contains(smell),
                "ui/vendor/cm6.js contains `{smell}`, which the content \
                 security policy in tauri.conf.json does not admit"
            );
        }
        // The licence travels with it, naming what it covers.
        let licence = include_str!("../../../../ui/vendor/cm6-LICENSE");
        assert!(
            licence.contains("MIT License") && licence.contains("@codemirror/state@"),
            "ui/vendor/cm6-LICENSE does not carry the MIT notice and the list \
             of packages it covers"
        );
        // And it can be made again. A vendored binary nobody can regenerate is
        // a binary nobody can update.
        let recipe = include_str!("../../../../ui/vendor/build-cm6.mjs");
        assert!(
            recipe.contains("node ui/vendor/build-cm6.mjs")
                && recipe.contains("--format=iife")
                && recipe.contains("\"@codemirror/state\": \""),
            "ui/vendor/build-cm6.mjs no longer says how to rebuild the file it \
             produces, or no longer pins what goes into it"
        );
    }

    /// The policy admits exactly what the window actually loads.
    ///
    /// Every emulator frame is a `blob:` object URL sat on an `<img>`
    /// (`receiveEmulatorFrame` — jpeg per frame, and a data: URI per frame
    /// would be a base64 copy and an allocation the pump pays thirty times a
    /// second). And the plugin bindings reach the backend over `ipc:` on this
    /// platform and `http://ipc.localhost` on the others. The shipped policy
    /// refused both — every mirror frame died in the console as an img-src
    /// violation and the pane stayed black while the stream ran
    /// (live report 2026-08-24), and `plugin:notification` could not even ask
    /// whether it was allowed to speak. A directive that names what the code
    /// does is the fix; `default-src` stays `'self'`, because nothing else
    /// earned an opening.
    #[test]
    fn the_policy_admits_what_the_window_loads() {
        let conf = include_str!("../../tauri.conf.json");
        let csp = conf
            .lines()
            .find(|line| line.contains("\"csp\""))
            .expect("tauri.conf.json declares a csp");
        for (directive, holds) in [
            // The mirror's frames — one object URL per jpeg.
            ("img-src", "blob:"),
            // Plugin IPC, in this platform's spelling…
            ("connect-src", "ipc:"),
            // …and in the spelling Windows and Linux use, so the counterpart
            // does not wait for someone to hit the same black pane there.
            ("connect-src", "http://ipc.localhost"),
        ] {
            let clause = csp
                .split(';')
                .find(|clause| clause.contains(directive))
                .unwrap_or_else(|| panic!("the csp has no `{directive}` directive"));
            assert!(
                clause.contains(holds),
                "the csp's `{directive}` does not admit `{holds}`, which the \
                 window loads: {clause}"
            );
        }
        // The opening is scoped. Everything not named still falls to 'self'.
        assert!(
            csp.contains("default-src 'self'"),
            "the csp's default-src drifted off 'self': {csp}"
        );
    }

    /// A file that a person actually has is a file this window opens.
    ///
    /// The cap was 512 KiB, chosen for a `<textarea>` with a hand-drawn gutter
    /// beside it. `ui/shell.js` is over a megabyte — the window could not open
    /// the file it is written in. Orca's text read path is a 10 MB-class
    /// ceiling, so a syntax-highlighting editor under the old cap would have
    /// moved the complaint rather than answered it.
    ///
    /// All three roads, because a read that admits four megabytes and a save
    /// that refuses them is a file you can open and cannot put back.
    #[test]
    fn the_size_cap_admits_the_files_people_have() {
        let backend = shipped_backend();
        for name in [
            "fn read_text_at(target: &Path) -> Result<TextFile, String> {",
            "fn write_text_at(target: &Path, text: &str, version: &str) -> Result<String, String> {",
            "fn recreate_text_at(target: &Path, text: &str) -> Result<String, String> {",
        ] {
            let body = block_after(backend, name);
            assert!(
                body.contains("MAX_VIEW_BYTES") && body.contains("4 * 1024 * 1024"),
                "`{name}` no longer caps at four megabytes:\n{body}"
            );
            assert!(
                body.contains("파일이 너무 큽니다"),
                "`{name}` refuses an oversized file without saying so:\n{body}"
            );
        }
    }

    /// The editor's document is the tab's draft, and the leaf's editor is
    /// destroyed with the leaf.
    ///
    /// Two invariants that used to be free and are not any more. The textarea
    /// WAS the draft — `input.value` and `tab.draft` could not disagree, and
    /// there was nothing to tear down. A document model can hold text the tab
    /// does not know about, and an `EditorView` left in a removed element
    /// keeps its DOM listeners and its measure loop alive.
    #[test]
    fn the_editor_stays_the_same_one_fact_and_is_torn_down_with_its_leaf() {
        let window = window_source();

        // Typing lands in the draft, which is what `isDirty` compares and what
        // ⌘S writes. Everything else about the mark follows from that.
        let typed = block_after(window, "function editorTyped(tab, typed) {");
        assert!(
            typed.contains("tab.draft = typed;") && typed.contains("tab.saved = false;"),
            "a keystroke no longer reaches the draft the dirty mark is \
             measured against:\n{typed}"
        );
        assert!(
            typed.contains("if (was !== isDirty(tab) || glanced) renderTabs();"),
            "the strip is rebuilt per character, or never:\n{typed}"
        );

        // A document change that merely MADE the document equal to the draft
        // is not typing. Without this guard, seating a tab or landing a
        // re-read would clear the note on the save that just wrote it.
        let update = block_after(window, "function onEditorUpdate(update) {");
        assert!(
            update.contains("if (typed !== owner.draft) editorTyped(owner, typed);"),
            "the editor reports its own re-seat as somebody's typing:\n{update}"
        );
        assert!(
            update.contains("owner.cmText = owner.draft;"),
            "nothing records that the document and the draft now agree, so \
             `paintEditor` cannot tell an outside change from a keystroke:\n{update}"
        );

        // The other direction: the draft moved without the editor, so the
        // document is brought to it — as a transaction, which keeps the undo
        // stack and maps the selection.
        let painting = block_after(window, "function paintEditor(view, tab) {");
        assert!(
            painting.contains("if (tab.cmText !== tab.draft) {")
                && painting.contains("insert: tab.draft"),
            "a re-read or a restored draft never reaches the document the \
             person is looking at:\n{painting}"
        );
        // A tab that leaves parks its state, so coming back keeps the undo
        // stack — the one thing the textarea lost on every switch.
        assert!(
            painting.contains("leaving.cmState = held.editor.state;")
                && painting.contains("held.editor.setState(parked ?? editorStateFor(tab));"),
            "switching tabs throws away the document state instead of parking \
             it on the tab it belongs to:\n{painting}"
        );

        // Teardown, where the leaf folds.
        let folding = block_after(window, "function collapseStageGroup(group) {");
        assert!(
            folding.contains("dropEditorView(group);"),
            "a folded leaf leaves its editor behind, listeners and measure \
             loop included:\n{folding}"
        );
        let dropping = block_after(window, "function dropEditorView(group) {");
        assert!(
            dropping.contains("held.editor.destroy();")
                && dropping.contains("editorViews.delete(group);"),
            "the editor is forgotten without being destroyed:\n{dropping}"
        );
        // The second leaf's surface is a deep clone of the first leaf's LIVE
        // one, so it would arrive carrying a copy of a mounted editor's DOM.
        let hosting = block_after(window, "function docHost(group, kind) {");
        assert!(
            hosting.contains("host.querySelector(\".file-edit\")?.replaceChildren();"),
            "a split leaf is built from a clone that still contains the other \
             leaf's editor as dead markup:\n{hosting}"
        );
    }

    /// The find bar replaces as well as finds, and one sweep is one undo.
    ///
    /// It could not before, and the reason was honest: a replace-all across a
    /// `<textarea>` is one `value` assignment, which discards the undo stack
    /// and drops the caret at the end. Under a document model it is a
    /// transaction. Orca's find is Monaco's and has all three abilities; this
    /// is the gap closing.
    #[test]
    fn the_find_bar_replaces_and_one_sweep_is_one_undo() {
        let window = window_source();
        let markup = include_str!("../../../../ui/index.html");

        for class in [
            "file-find-swap",
            "file-find-swap-one",
            "file-find-swap-all",
            "file-find-case",
        ] {
            assert!(
                markup.contains(&format!("class=\"{class}\"")),
                "ui/index.html has no `.{class}` for the find bar to drive"
            );
        }

        let replacing = block_after(window, "function runReplace(tab, all) {");
        assert!(
            replacing.contains("if (all) window.CM6.replaceAll(editor);"),
            "replace-all is not the editor's own one-transaction sweep — a \
             loop leaves one undo step per match and the person is still \
             pressing ⌘Z when they give up:\n{replacing}"
        );
        assert!(
            replacing.contains("else window.CM6.replaceNext(editor);"),
            "replacing one match is not wired:\n{replacing}"
        );
        assert!(
            replacing.contains("setSearchQuery.of(query)"),
            "a replace runs against whatever query was last set rather than \
             what the bar currently says:\n{replacing}"
        );

        // The case toggle changes what the search MEANS, so it re-runs from
        // the caret: the old index points into a list that no longer exists.
        let wiring = block_after(window, "function wireFind(view) {");
        assert!(
            wiring.contains("tab.findCase = tab.findCase !== true;")
                && wiring.contains("runFind(tab, 0);"),
            "the case toggle either does not flip or does not re-run the \
             search it just redefined:\n{wiring}"
        );
        let query = block_after(window, "function findQuery(view, tab) {");
        assert!(
            query.contains("caseSensitive: tab.findCase === true"),
            "the query ignores the case toggle beside it:\n{query}"
        );
    }

    /// The tree prints a letter a person can read, not git's raw code.
    ///
    /// Measured side by side against Orca 1.4.164 on this repository: its
    /// explorer marks an untracked file `U` and a modified one `M` — one
    /// letter each. Ours printed porcelain straight through, so an untracked
    /// file said `??`: correct, and legible only to somebody who already
    /// knows the format.
    #[test]
    fn the_tree_marks_a_file_with_one_letter() {
        let window = window_source();
        let letter = block_after(window, "function badgeLetter(code) {");
        assert!(
            letter.contains("return \"U\";"),
            "an untracked file is still marked with git's own `??`:\n{letter}"
        );
        assert!(
            letter.contains("if (code === \"\" || code === \"!!\") return \"\";"),
            "an ignored row gets a letter, which would compete with the ones \
             that mean something:\n{letter}"
        );

        let tree = block_after(window, "async function loadTree(container, path) {");
        assert!(
            tree.contains("badgeLetter(code)"),
            "the tree still writes the raw code into the badge:\n{tree}"
        );
    }

    /// Every tab says what kind of thing it holds.
    ///
    /// Orca's tabs carry a glyph (measured on 1.4.164: its `Terminal 1` tab
    /// wears a terminal one). A strip of bare words is what reads as a
    /// wireframe — the same finding that put glyphs on the sidebar rows.
    #[test]
    fn a_tab_says_what_kind_of_thing_it_holds() {
        let window = window_source();
        let glyphs = block_after(window, "const TAB_GLYPH = {");
        // Every kind a tab can be. A kind with no glyph falls back, and a
        // fallback that is silently wrong is worse than no glyph at all.
        for kind in ["term", "lane", "file", "image", "diff"] {
            assert!(
                glyphs.contains(&format!("{kind}:")),
                "a `{kind}` tab has no glyph of its own:\n{glyphs}"
            );
        }
        let painting = block_after(window, "function buildTabNode(tab, group) {");
        assert!(
            painting.contains("fileTypeIcon(tab.path) : (TAB_GLYPH[tab.kind]"),
            "the strip does not draw the glyph — a file tab wears the file's \
             own face (Orca's EditorPanel calls getFileTypeIcon) and every \
             other kind wears its TAB_GLYPH:\n{painting}"
        );

        let markup = include_str!("../../../../ui/index.html");
        assert!(
            markup.contains("id=\"i-image\""),
            "the image glyph the tree and the strip both name is not in the \
             sprite, so both draw an empty box"
        );
    }

    /// The project catalog is built from where the window IS.
    ///
    /// `open_project` moves this window by writing `active_root`;
    /// `project_root` stays on whatever the process booted with. Building
    /// from the latter once dropped the project you had just left — the one
    /// row you most need — and kept the one you are standing in. The lesson
    /// was first held on `recent_projects`, a dead twin of this rule the
    /// window never called; that command left on 2026-08-09 and the gate
    /// moved to the door the sidebar actually opens.
    #[test]
    fn the_project_catalog_is_built_from_where_the_window_is() {
        let backend = shipped_backend();
        let listing = block_after(backend, "fn project_catalog(");
        assert!(
            listing.contains("let here = state.active();"),
            "the catalog is built from the root this process booted on, \
             not the one it is looking at:\n{listing}"
        );
    }

    /// No dialog can grow past the window it is in.
    ///
    /// Measured in a 720px-tall window: the settings panel is 740px and opens
    /// 86px down, so it ran 106px past the bottom — and `overflow: hidden`
    /// meant the rows down there were not merely off-screen but unreachable.
    /// A dialog that cannot show its last control has a control that does not
    /// exist.
    #[test]
    fn a_dialog_cannot_grow_past_the_window() {
        let styles = include_str!("../../../../ui/shell.css");
        for surface in [".qo {", ".permission {"] {
            let rule = block_after_css(styles, surface);
            assert!(
                rule.contains("max-height: 100%;"),
                "`{surface}` is not bounded by the window:\n{rule}"
            );
            assert!(
                rule.contains("overflow: hidden auto;"),
                "`{surface}` clips what does not fit instead of scrolling \
                 it:\n{rule}"
            );
        }
        // `max-height: 100%` resolves against the grid area, so the scrim's
        // padding is what makes that smaller than the window.
        let scrim = block_after_css(styles, ".scrim {");
        assert!(
            scrim.contains("padding: 4vh;"),
            "the scrim has no padding, so `max-height: 100%` is the whole \
             window and a dialog can still reach the edges:\n{scrim}"
        );
    }

    /// A field is the height of the control inside it.
    ///
    /// The search glyph is centred on `.field` with `top: 50%`. `.field` was a
    /// block wrapping an inline-block input that carried a 12px bottom margin,
    /// so the box was 12px taller than the control — and the glyph sat 6px
    /// below the centre of the field it belongs to. Measured before: field mid
    /// 125.5, glyph mid 131.5. After: both 125.5.
    #[test]
    fn a_field_is_the_height_of_the_control_in_it() {
        let styles = include_str!("../../../../ui/shell.css");
        let field = block_after_css(styles, ".field {");
        assert!(
            field.contains("display: flex;"),
            "`.field` is a block again, so the input's line box grows it past \
             the control and the glyph centres on the wrong box:\n{field}"
        );
        let search = block_after_css(styles, ".panel-search {");
        assert!(
            search.contains("margin: 0;"),
            "the control carries a margin again, which is height the field \
             centres its glyph against:\n{search}"
        );

        // The same class of mistake one level down: an inline SVG sits on the
        // text baseline and reserves a descender's worth of space under it.
        let icon = block_after_css(styles, ".icon {");
        assert!(
            icon.contains("display: block;"),
            "the icons are inline, so every one of them outside a flex row \
             sits below the centre of what it marks:\n{icon}"
        );
    }

    /// A worktree whose agent is blocked does not look calm — and one holding
    /// a live shell does not look empty.
    ///
    /// Orca's row indicator is a five-state machine with a stated precedence:
    /// `permission > working > active > inactive`, with `done` composed in
    /// from the agent summaries (`getWorktreeStatus`,
    /// worktree-status-BKo1bx-D.js:404; `StatusIndicator`,
    /// StatusIndicator-CZxjnMbl.js:1764 draws spinner / amber question mark /
    /// emerald dot / neutral dot). Two of its judgments were missing here.
    ///
    /// The first was the worst-wins rule, which is why the rank is pinned: a
    /// calm lane beside a blocked one must not speak for the row.
    ///
    /// The second was the reported one. `active` in Orca is raised by a LIVE
    /// PTY TAB, before any agent is attributed to the checkout — ours folded
    /// only the lane registry, so a workspace where somebody had opened a
    /// plain terminal and was working in it said "활성 세션 없음" over a grey
    /// dot. That is the whole of the report, and the fold below is where it is
    /// answered.
    #[test]
    fn a_worktree_holding_a_blocked_lane_says_so() {
        let window = window_source();
        // One line, so `block_after` — which runs to the next line that is
        // exactly `}` — would otherwise sweep in the table below it and find
        // `exited:` there.
        let rank = block_after(window, "const WORKTREE_STATE_RANK = ")
            .lines()
            .next()
            .unwrap_or_default();
        // Orca's precedence, read bottom-up: nothing here, a shell standing by,
        // work that finished, work happening, a person wanted.
        for (state, above) in [
            ("active", "empty"),
            ("idle", "active"),
            ("streaming", "idle"),
            ("waiting", "streaming"),
            ("blocked", "waiting"),
        ] {
            let outranks = rank
                .find(&format!("{state}:"))
                .zip(rank.find(&format!("{above}:")))
                .map(|(later, earlier)| later > earlier)
                .unwrap_or(false);
            assert!(
                outranks,
                "`{state}` does not outrank `{above}`, so a calm lane can \
                 speak for a checkout that is blocked:\n{rank}"
            );
        }
        assert!(
            !rank.contains("exited:"),
            "a lane that has ended still speaks for the checkout it ended \
             in:\n{rank}"
        );

        // The fold itself: one pure function, so the precedence is decided in
        // one place and every surface reads the same answer.
        let fold = block_after(
            window,
            "function foldWorktreeState(laneState, agentStates, live) {",
        );
        assert!(
            fold.contains("for (const said of agentStates) raise(HOOK_STATE_CLASS[said]")
                && fold.contains("if (live) raise(\"active\");"),
            "the dot no longer folds the agents and the live shell into the \
             lane state, so a terminal with nobody in it reads as empty:\n{fold}"
        );
        // A floor, not an override — `raise` only ever moves the state UP, so a
        // plain shell beside an agent that is asking cannot calm the row down.
        assert!(
            !fold.contains("if (live) return") && !fold.contains("= \"active\";"),
            "a live shell overwrites what an agent is doing rather than \
             raising the floor under it:\n{fold}"
        );
        // And our six fold onto Orca's five, with the two "a person is wanted"
        // spellings landing on one mark. Eight lines and no more: this table
        // ends on `};`, which `block_after` does not read as a closing line, so
        // it would otherwise run on into the rest of the file and answer about
        // something else.
        let indicator = block_after(window, "const WORKTREE_INDICATOR = {")
            .lines()
            .take(8)
            .collect::<Vec<_>>()
            .join("\n");
        for (ours, orcas) in [
            ("empty", "inactive"),
            ("active", "active"),
            ("idle", "done"),
            ("streaming", "working"),
            ("waiting", "permission"),
            ("blocked", "permission"),
        ] {
            assert!(
                indicator.contains(&format!("{ours}: \"{orcas}\"")),
                "`{ours}` no longer draws Orca's `{orcas}`:\n{indicator}"
            );
        }

        let styles = include_str!("../../../../ui/shell.css");
        // The state rides the DOT: `.wt-row.is-active` is already taken by
        // "the checkout the window is standing in", and Orca's `active` means
        // something else.
        assert!(
            styles.contains(".wt-dot.is-permission::before")
                && styles.contains("content: \"?\";")
                && styles.contains("color: var(--signal-wait);"),
            "the row draws no amber question mark for a lane that needs a person"
        );
        assert!(
            styles.contains(".wt-dot.is-working::before")
                && styles.contains(".wt-dot.wt-spin-0::before")
                && styles.contains(".wt-dot.wt-spin-11::before"),
            "a working agent does not produce Orca's spinner"
        );
        assert!(
            styles.contains(".wt-dot.is-done::before")
                && styles.contains(".wt-dot.is-active::before"),
            "a finished agent and a live shell no longer share Orca's one green"
        );
        // 각도는 창이 쓴다 — CSS 키프레임 회전은 분할+글라스 무대의 합성
        // 정지에서 프레젠트가 멎었다("프로그레스는 안움직임", Image #8·#27).
        // 도는 것이 없는 프레임에 루프는 스스로 잠들고, working을 입히는
        // 손이 깨운다. Orca도 이 표시는 모션 줄이기와 무관하게 돌린다 —
        // 장식이 아니라 지금 일하고 있다는 말이라서.
        let spinning = block_after(window, "function spinWorktreeDots(now) {");
        assert!(
            spinning.contains("if (turning.length === 0) return;")
                && spinning.contains("requestAnimationFrame(spinWorktreeDots)"),
            "the JS spinner lost its sleep-when-idle loop:\n{spinning}"
        );
        // 쓰는 것은 단계를 넘어갈 때뿐이다. 프레임마다 쓰면 120Hz 창에서 점
        // 하나가 초당 120번의 무효화이고(2026-08-30 프리징 아래 WebContent
        // 샘플은 paint 가 몸통이었다), 정지를 뚫는 데는 열두 단계의
        // 프레젠트로 충분하다.
        assert!(
            spinning.contains("if (step !== worktreeSpinStep) {")
                && spinning.contains("dot.className = `wt-dot is-working wt-spin-${step}`"),
            "the JS spinner creates an inline angle again, or writes a class every frame:\n{spinning}"
        );
        let waking = block_after(window, "function wakeWorktreeSpin() {");
        assert!(
            waking.contains("worktreeSpinStep = -1;"),
            "a spinner that wakes on the step it slept on makes a new dot wait for its first angle:\n{waking}"
        );
        let dressing = block_after(window, "function dressWorktreeDot(row, state) {");
        assert!(
            dressing.contains(r#"if (indicator === "working") wakeWorktreeSpin();"#),
            "nothing wakes the spinner when a workspace starts working:\n{dressing}"
        );
    }

    /// The dot moves without the sidebar being rebuilt around it.
    ///
    /// The state of a workspace is the most volatile fact in that list — it
    /// moves on every turn of every agent. It used to sit inside
    /// `worktreeListShape`, which meant every one of those turns rebuilt every
    /// project header, every row and every listener under them; the guard that
    /// 1-eo added to stop exactly that was being defeated by the one fact most
    /// likely to change.
    ///
    /// So it leaves the shape and joins the in-place road beside
    /// `paintWorktreeActive`. What STAYS in the shape is the lane COUNT, which
    /// is structural — a lane appearing hangs a row under the node and
    /// uncovers the twist.
    #[test]
    fn a_workspace_dot_repaints_without_rebuilding_the_list() {
        let window = window_source();

        let shape = block_after(window, "function worktreeListShape(held) {");
        assert!(
            shape.contains("(held.get(worktree.path) ?? []).length"),
            "the shape guard cannot see a session appearing, so the row it \
             hangs under never arrives:\n{shape}"
        );
        assert!(
            !shape.contains("aggregate?.state")
                && !shape.contains("agentRowSignature")
                && !shape.contains("foldWorktreeState"),
            "the shape guard counts a workspace's STATE as its shape, so every \
             turn of every agent rebuilds the sidebar:\n{shape}"
        );
        // The state is out; the COUNTER that says the frozen reading was
        // re-taken is in. Without it a settle that reordered the list draws
        // nothing, because the shape it would build reads identical.
        assert!(
            shape.contains("activityGeneration"),
            "the shape guard cannot see the activity reading being re-taken, \
             so a settle reorders nothing:\n{shape}"
        );
        let freezing = block_after(window, "function noteWorkspaceActivity() {");
        assert!(
            freezing.contains("if (!activityOrdersTheList()) return;")
                && freezing.contains("WORKSPACE_ACTIVITY_SETTLE_MS"),
            "the activity reading is re-taken even when nothing orders by it, \
             or without waiting for the list to settle:\n{freezing}"
        );

        let painting = block_after(window, "function paintWorktreeDots() {");
        assert!(
            painting.contains("worktreeList.querySelectorAll(\".wt-row[data-worktree-path]\")")
                && painting.contains("dressWorktreeDot("),
            "the dots are no longer corrected in place on rows that already \
             exist:\n{painting}"
        );
        assert!(
            !painting.contains("invoke(") && !painting.contains("replaceChildren"),
            "repainting a dot fetches something, or rebuilds the rows it is \
             meant to leave standing:\n{painting}"
        );
        // One door for both roads: the row the rebuild builds and the row a
        // beat later corrects must not be able to wear two different dots.
        let dressing = block_after(window, "function dressWorktreeDot(row, state) {");
        assert!(
            dressing.contains("WORKTREE_INDICATOR[state]")
                && dressing.contains("worktreeStateLabel(state)"),
            "the dot's mark and its words no longer come off one state:\n{dressing}"
        );
        assert!(
            !window.contains("row.classList.add(`is-${state}`)"),
            "the lane vocabulary is still written onto the row as well, so two \
             class families say one fact"
        );
        // And the beat that draws the agent rows draws the dot above them —
        // a card reading 작업 중 under a quiet dot is the same disagreement
        // from the other side.
        let flushing = block_after(window, "function flushAgentPaint() {");
        assert!(
            flushing.contains("paintWorktreeDots();")
                && flushing.contains("paintWorktreeAgents();"),
            "an agent's news reaches the rows in a card but not the dot on the \
             row above them:\n{flushing}"
        );

        // The elder twin on this road, and the bug it shipped: it wrote
        // `aria-current` while the BUILDER wrote `is-active`, and
        // `.wt-row.is-active` is what paints the fill, the border and the
        // shadow. So the moment the shape guard started skipping the rebuild,
        // every workspace a person visited kept its highlight — two projects'
        // main rows lit at once, then three. An in-place painter has to write
        // everything its builder writes.
        let marking = block_after(window, "function paintWorktreeActive() {");
        assert!(
            marking.contains("row.classList.toggle(\"is-active\", here);")
                && marking.contains("aria-current"),
            "the in-place mark moves only one of the pair the builder writes, \
             so a workspace keeps its highlight after the window has left \
             it:\n{marking}"
        );
        let activation = block_after(window, "async function activateWorktree(");
        assert!(
            activation.contains("const previousActiveWorktreePath = activeWorktreePath;")
                && activation.contains("activeWorktreePath = path;")
                && activation.contains("paintWorktreeActive();")
                && activation.contains("activeWorktreePath = previousActiveWorktreePath;"),
            "workspace navigation leaves the old active card painted during the switch, or cannot roll it back:\n{activation}"
        );
        let refreshing = block_after(window, "async function refreshWorktrees() {");
        assert!(
            refreshing.contains("const generation = ++worktreeRefreshGeneration;")
                && refreshing
                    .matches("generation !== worktreeRefreshGeneration")
                    .count()
                    >= 2,
            "an older catalog response can paint over a newer workspace activation:\n{refreshing}"
        );
        // One style source: the class paints, `aria-current` is the same fact
        // said to a screen reader. Two of them is how they come to disagree.
        let styles = include_str!("../../../../ui/shell.css");
        assert!(
            !styles.contains(".wt-row[aria-current"),
            "the workspace row is painted off both the class and the aria \
             attribute, so the two can disagree about which row is current"
        );
    }

    /// Middle-clicking a tab closes it.
    ///
    /// Orca's strip does it (`onAuxClick` checking `event.button === 1`,
    /// unsaved-close-queue-DB-LbON-.js:2540-2605) and so does every strip a
    /// person has used. Routed through `closeTab` rather than `dropTab`, so a
    /// document with unsaved typing is still asked about and a terminal still
    /// ends its process.
    #[test]
    fn middle_clicking_a_tab_closes_it() {
        let window = window_source();
        let painting = block_after(window, "function buildTabNode(tab, group) {");
        assert!(
            painting.contains("\"auxclick\"") && painting.contains("event.button !== 1"),
            "the strip does not answer the middle button:\n{painting}"
        );
        assert!(
            painting.contains("closeTab(id)"),
            "middle-click takes a shortcut around the close path, which is \
             where unsaved work is asked about and a shell is ended:\n{painting}"
        );
    }

    /// A surface with no tab is off the screen.
    ///
    /// The root of two reports. `updateStage` decided what to hide by walking
    /// `tabs`, so a surface whose tab had been taken off the strip was never
    /// reached and simply stayed visible: a terminal nobody could type into,
    /// and a file left covering the terminal that replaced it. A tab is how a
    /// surface is reached; it is not what makes one exist.
    ///
    /// The intent is unchanged since; what a terminal's surface IS has moved.
    /// A terminal tab used to be one shell and its screen was the surface.
    /// Now the tab holds a tree of panes and the surface is the tab's pane
    /// host — so this asks for `paneHosts`, and asking for `termViews` here
    /// would hide a screen out from under the split still drawing it.
    #[test]
    fn a_surface_with_no_tab_is_hidden() {
        let window = window_source();
        let staging = block_after(window, "function updateStage() {");
        assert!(
            staging.contains("const surfaces = new Set([stageView.host]);"),
            "the stage decides what to hide from something other than the \
             surfaces it owns:\n{staging}"
        );
        assert!(
            staging.contains("paneHosts.values()"),
            "a terminal tab's pane host is not among the surfaces the stage \
             hides, so a split can be left on screen with no tab:\n{staging}"
        );
        // The document surfaces, DERIVED rather than listed.
        //
        // This assertion used to be the literal string
        // `"fileView", "diffView", "imageView"`, and it was the wrong shape
        // twice over: it broke when a fourth surface was legitimately added, and
        // it would have passed with a fourth surface missing — which is what
        // happened. The board was built, was never in that list, and stayed on
        // screen after its tab went. So the list is now one name and this checks
        // that every kind `docHost` builds a view for is in it.
        assert!(
            staging.contains("for (const kind of DOC_KINDS)"),
            "the stage hides a hand-written list of document surfaces again, \
             which is how the next one gets left out:\n{staging}"
        );
        // And the list itself is DERIVED from the registry rather than typed
        // beside it. `worker` is why: the surface was built, was painted, and
        // was not in the hand-written list, so the hide/show pass never picked
        // it up — a page that opened and stayed invisible through three
        // separate reports.
        assert!(
            window.contains("const DOC_KINDS = Object.keys(DOC_VIEWS);"),
            "DOC_KINDS is written out by hand again instead of being the \
             registry's own keys, which is how a surface gets left out of it"
        );
        let registry = block_after(window, "const DOC_VIEWS = {");
        let kinds: Vec<&str> = registry
            .lines()
            .filter_map(|line| {
                let (name, rest) = line.trim().split_once(':')?;
                rest.trim_start().starts_with('{').then_some(name)
            })
            .collect();
        assert!(
            kinds.len() >= 12,
            "the stage's view registry stopped parsing: found {kinds:?}"
        );

        // A kind the stage PAINTS but does not know to show is the same bug
        // wearing the other face, so the painter is not allowed to keep its
        // own list of kinds beside this one — it dispatches through the
        // registry, and then the two cannot disagree.
        let painting = block_after(window, "function paintDoc(tab) {");
        assert!(
            painting.contains("DOC_VIEWS[tab.kind]?.paint?.(tab)"),
            "paintDoc no longer dispatches through the view registry:\n{painting}"
        );
        assert!(
            !painting.contains("tab.kind === \""),
            "paintDoc names kinds by hand again, which lets the painter's list \
             drift from the stage's:\n{painting}"
        );

        // Every stage surface in the markup needs a view built and hidden.
        //
        // A stage surface is a `class="file-view"` section: that shared class is
        // what makes a document surface one, and it is what tells these four from
        // the full-screen overlays (`auto-view`, `task-view`, `settings-view`),
        // which are not on the stage and are not hidden by it. Surfaces this
        // window BUILDS are not in the markup at all — they are covered by the
        // registry checks above, which is the hole `worker` fell through when
        // the markup was the only thing consulted.
        let markup = include_str!("../../../../ui/index.html");
        let wanted: Vec<&str> = markup
            .match_indices(r#"class="file-view" id=""#)
            .filter_map(|(at, opened)| {
                let rest = &markup[at + opened.len()..];
                rest.split_once("-view\"").map(|(name, _)| name)
            })
            .collect();
        assert!(
            wanted.len() >= 4,
            "the stage's view templates stopped parsing: found {wanted:?}"
        );
        for kind in wanted {
            assert!(
                kinds.contains(&kind),
                "`{kind}-view` exists in the markup and `{kind}` is not in \
                 DOC_VIEWS, so the stage will never hide it: {kinds:?}"
            );
        }

        // A builder the registry names must exist, or the surface it stands
        // for is a template that comes back undefined at load.
        for line in registry.lines() {
            let Some((_, rest)) = line.split_once("build: ") else {
                continue;
            };
            let built = rest.split([',', ' ', '}']).next().unwrap_or_default();
            assert!(
                window.contains(&format!("function {built}(")),
                "DOC_VIEWS names `{built}` and ui/shell.js declares no such \
                 builder"
            );
        }
        assert!(
            !staging.contains("for (const tab of tabs) {"),
            "the hide pass walks the tabs again, which is exactly the bug:\n{staging}"
        );
    }

    /// Changing the worktree does not orphan a running terminal.
    ///
    /// The reported bug: clicking a worktree row took every non-lane tab off
    /// the strip with `dropTab`, which is bookkeeping and nothing else. A
    /// terminal tab left that way kept its shell running with no tab naming
    /// it, and `updateStage` only walks `tabs` — so its screen was never
    /// hidden either. What the person saw was the terminal's tab vanish and a
    /// terminal stay on the stage that nothing was listening to: visible,
    /// unreachable, and impossible to close.
    ///
    /// The fix is not to close them harder. A terminal was started in a
    /// checkout of this project and is still running in it, so a click in the
    /// sidebar must not end somebody's shell.
    #[test]
    fn changing_the_worktree_leaves_the_terminals_running() {
        let window = window_source();
        let reload = block_after(window, "async function reloadFileSurfaces() {");
        assert!(
            !reload.contains("dropTab("),
            "the checkout switch takes tabs off the strip itself again — the \
             terminals it reaches this way keep their processes and their \
             screens:\n{reload}"
        );

        // Only documents are let go of, and `isDocument` is what says which
        // those are. A terminal reaching that list is the whole bug.
        let documents = block_after(window, "function isDocument(tab) {");
        assert!(
            !documents.contains("\"term\"") && !documents.contains("\"lane\""),
            "a terminal or a lane counts as a document, so the checkout \
             switch will take it:\n{documents}"
        );

        let pane_tabs = block_after(window, "function paneTabs(group) {");
        assert!(
            pane_tabs.contains("tab.worktree === activeWorktreePath"),
            "the tab strip still mixes terminals from every workspace:\n{pane_tabs}"
        );
        // The fact lives in the one builder every terminal-tab road uses —
        // ⌘T, an agent launch, a quick command — which is exactly why there
        // is one builder.
        let mounting = block_after(window, "function mountTermTab(term");
        assert!(
            mounting.contains("worktree: activeWorktreePath"),
            "a terminal tab does not remember the cwd workspace that owns it:\n{mounting}"
        );
        let restoring = block_after(
            window,
            "async function restoreActiveWorktreeTab({ firstTerminal = true } = {}) {",
        );
        assert!(
            restoring.contains("activeTabByWorktree.get(activeWorktreePath)")
                && restoring.contains("await openTermTab()"),
            "workspace activation neither restores its PTY nor opens one in the new cwd:\n{restoring}"
        );
        let activation = block_after(window, "async function activateWorktree(");
        assert!(
            activation.contains("restoreActiveWorktreeTab({ firstTerminal })"),
            "the backend root changes without changing the visible terminal:\n{activation}"
        );
        // And it is awaited BESIDE the two panel reads rather than in front of
        // them. They were a chain — terminal, then files, then the project
        // column — four round trips deep before the thing that was clicked
        // moved, with the last three answering questions none of the others
        // had asked. All any of them needs is `activeWorktreePath`.
        assert!(
            activation.contains("await Promise.allSettled([")
                && activation.contains("reloadFileSurfaces()")
                && activation.contains("refreshWorktrees()"),
            "a workspace switch waits on its three reads one after another:\n{activation}"
        );
        let boot = block_after(window, "async function boot() {");
        let catalog = boot.find("await refreshWorktrees()");
        // Whatever this workspace opens with — its stored tabs or the plain
        // first terminal — is downstream of knowing WHICH workspace it is.
        let terminal = boot.find("await restoreActiveWorktreeTab()");
        assert!(
            catalog.is_some() && terminal.is_some() && catalog < terminal,
            "the first terminal can be created before its workspace is known:\n{boot}"
        );

        // And the PROJECT switch now rides the same rule, one level up: it
        // neither drops the leaving project's tabs nor their screens, and it
        // seats the arriving project through the same restore. Orca's switch
        // is a pointer write (`setActiveRepo`, repos.ts:3960) over state that
        // is all keyed by worktree (`tabsByWorktree`, repos.ts:3755-3770);
        // this used to be the one road that killed, and it is how "새로운
        // 프로젝트를 열면 기존에 돌고 있던 claude가 꺼짐" was reported.
        let switching = block_after(window, "async function switchProject(path) {");
        assert!(
            !switching.contains("dropTab(") && !switching.contains("dropTermView("),
            "a project switch takes the leaving project's terminals down \
             again — their shells and agents die with them:\n{switching}"
        );
        assert!(
            switching.contains("await restoreActiveWorktreeTab()"),
            "a project switch no longer seats the arriving project's own \
             surviving tabs:\n{switching}"
        );
    }

    /// A repository's folder opens with its row — asked for by name.
    ///
    /// Orca's slot never consults the fold (`getRepoLucideIcon` ends in
    /// `?? Folder`) and an earlier cut matched that measurement. The person
    /// then asked for the state twice, by name ("프로젝트 아이콘 닫혀있을때랑
    /// 열렸을때 아이콘 표시 변경해주고") — a white label answers to its owner
    /// before its original. This is the recorded deviation, so the next
    /// fidelity sweep does not quietly fold it back.
    #[test]
    fn the_repository_mark_carries_the_fold_state_by_request() {
        let window = window_source();
        let header = block_after(window, "function makeProjectHeader(project) {");

        assert!(
            header.contains(r#"icon(folded ? "folder" : "folder-open")"#),
            "the repository's mark stopped following the fold the person \
             asked for:\n{header}"
        );
        // The chevron still carries the fold too — the pair the file tree
        // draws, not a swap of one for the other.
        assert!(
            header.contains("icon(\"chevron\", !folded)"),
            "the chevron no longer draws the fold beside the folder:\n{header}"
        );
    }

    /// The `+` drops a palette, not a terminal.
    ///
    /// Orca's `+` opens `TabBarCreateEntry` — a searchable menu whose rows
    /// are the new-tab verbs and the installed agents as INTERACTIVE
    /// launches (unsaved-close-queue-BHrI4TA0.js:1655). Asked for by name
    /// ("+ 버튼 위에 터미널이 열리는게 아니고 이런식으로 열림 확인해"), and
    /// the straight terminal stays one empty Enter away.
    #[test]
    fn the_plus_button_drops_a_palette_not_a_terminal() {
        let window = window_source();
        let adding = block_after(window, "function addTabButton(pane, group) {");
        assert!(
            adding.contains("openTabCreate(add, road)") && !adding.contains("openTermTab()"),
            "the + opens a terminal outright again:\n{adding}"
        );
        let painting = block_after(window, "async function paintTabCreate() {");
        assert!(
            painting.contains("openTermTab({ door: \"terminal\" });")
                && painting.contains("launchPaletteAgent(row)")
                && painting.contains("installedAgents()"),
            "the palette lost its terminal row or its agent launches:\n{painting}"
        );
        let launching = block_after(window, "async function launchPaletteAgent(row) {");
        assert!(
            launching.contains("launchAgentTab({"),
            "a palette agent no longer takes the interactive launch road:\n{launching}"
        );
        // 차림 두 벌 — 돋보기가 이끄는 검색 줄, 그리고 빈 결과의 문장
        // (Orca TabBarCreateEntry의 EntryStatusRow).
        assert!(
            window.contains(r#"tcSearch.innerHTML = icon("search");"#)
                && painting.contains(r#"none.className = "tc-none";"#),
            "the palette lost its magnifier or its empty-query sentence"
        );
    }

    /// Orca의 RichMarkdownToolbar를 소스 편집기 위에 — 버튼·줄·칸막이는
    /// 원본 그대로, 동작은 마크다운 텍스트 변환으로(우리 마크다운 면은
    /// 소스를 편집한다). 지피는 자리: 마크다운의 원본 면에서만 서고, todo
    /// 무늬가 ul보다 먼저 판정되고(`- [ ]`는 글머리로도 읽힌다), 버튼의
    /// mousedown이 캐럿을 지키고, ⌘B 화음이 마크다운 문서에만 산다.
    #[test]
    fn the_markdown_toolbar_writes_the_source_with_orcas_buttons() {
        let window = window_source();
        let markup = include_str!("../../../../ui/index.html");
        assert!(
            markup.contains(r#"<div class="md-toolbar" role="toolbar""#),
            "the toolbar host left the file view's template"
        );
        for glyph in [
            "i-pilcrow",
            "i-heading-1",
            "i-list-todo",
            "i-quote",
            "i-link",
        ] {
            assert!(
                markup.contains(&format!("id=\"{glyph}\"")),
                "the {glyph} drawing left the sprite"
            );
        }
        let painting = block_after(window, "function paintMdToolbar(view, tab, showing) {");
        assert!(
            painting.contains(r#"tab.mode === "markdown" && showing === "source""#),
            "the toolbar no longer keeps to markdown's editing face:\n{painting}"
        );
        assert!(
            painting.contains("host.onmousedown = (event) => event.preventDefault();"),
            "a button press steals the caret again:\n{painting}"
        );
        let marks = block_after(window, "const MD_BLOCK_MARKS = {");
        let todo = marks.find("todo:").expect("the todo mark left the table");
        let bullet = marks.find("ul:").expect("the ul mark left the table");
        assert!(
            todo < bullet,
            "todo must be asked before ul — `- [ ]` reads as a bullet too"
        );
        let extending = block_after(window, "function editorExtensions(tab) {");
        assert!(
            extending.contains(r#"tab.mode === "markdown""#) && extending.contains("Mod-b"),
            "the ⌘B chord stopped being markdown-only:\n{extending}"
        );
    }

