    /// The rich Jira card (t-105): attachments and the browser button ride
    /// existing doors, never new ones. The ZeroCode-browser button lowers the
    /// task view first — the native pane sits above the DOM, so a browser
    /// opened under a page still covering the stage was hidden by
    /// `browserCovered()` the moment it was born ("깜박이고 열리지 않음") —
    /// then walks `openBrowserTab` at the seat the + palette last chose
    /// (`lastBrowserPlacement`); a preview becomes an `<img>` only as a
    /// renderer-checked `data:` image under the named byte limit; and the one
    /// context command materializes the manifest, so worktree creation and
    /// orchestration read the same context.
    #[test]
    fn the_jira_card_ships_attachments_through_the_existing_doors() {
        let window = window_source();
        let open_app = block_after(window, "el(\"jira-item-open-app\").addEventListener(");
        assert!(
            open_app.contains(
                "openBrowserTab(at.url, { beside: lastBrowserPlacement() === \"split\" })"
            ),
            "the card's browser button left the one existing browser road:\n{open_app}"
        );
        let lowered = open_app
            .find("setTaskOpen(false);")
            .expect("the card's browser button no longer lowers the task view first");
        let opened = open_app
            .find("openBrowserTab(at.url,")
            .expect("the card's browser button no longer opens a browser");
        assert!(
            lowered < opened,
            "the browser is opened under a task view still covering the stage:\n{open_app}"
        );
        let preview_ask = block_after(window, "function jiraAttachmentPreviewOf(");
        assert!(
            preview_ask.contains("invoke(\"jira_attachment_preview\""),
            "{preview_ask}"
        );
        let paint = block_after(window, "function paintJiraAttachments(");
        assert!(
            paint.contains("uri.startsWith(\"data:image/\")"),
            "the renderer no longer checks that a preview is a data: image:\n{paint}"
        );

        let source = strip_rust_comments(shipped_backend());
        let shipped = source.split("mod tests {").next().expect("a module body");
        let preview = block_after(shipped, "async fn jira_attachment_preview(");
        assert!(
            preview.contains("jira_attachments::PREVIEW_LIMIT_BYTES")
                && preview.contains("image_data_uri"),
            "the preview command lost its named byte limit or its magic-byte \
             sniff:\n{preview}"
        );
        let context = block_after(shipped, "async fn jira_agent_context(");
        assert!(
            context.contains("jira_attachment_notes(")
                && context.contains("agent_context(&detail, &comments, &notes)"),
            "the one context command no longer carries the attachment \
             manifest:\n{context}"
        );
        // The materializer spends the named limits and rebuilds the download
        // address from the id — never the response-supplied `content` URL.
        let materialize = block_after(shipped, "async fn materialize_jira_attachment(");
        assert!(
            materialize.contains("jira_attachments::FILE_LIMIT_BYTES")
                && materialize.contains("attachment_content_url"),
            "{materialize}"
        );
        assert!(
            !materialize.contains("content_url:") && !materialize.contains(".content_url"),
            "the materializer follows the response-supplied content URL:\n{materialize}"
        );
    }

    /// A connect that cannot be a connection is refused before the network,
    /// not after it.
    ///
    /// All three are answered without a socket, which is why they can be
    /// tested at all: an address with no scheme is not a site, plaintext HTTP
    /// cannot protect a credential, and an empty token is not a credential.
    /// Sending any of them would spend a round trip — and HTTP would disclose
    /// the secret — to be told the same thing in worse words.
    #[test]
    fn jira_connect_rejects_unknown_auth_type_before_other_behavior() {
        assert!(
            zerocode_core::jira::SiteKind::try_from_auth_type("cluod").is_err(),
            "an authType typo was guessed as Cloud"
        );
        let connecting = block_after(shipped_backend(), "async fn jira_connect(");
        let auth_at = connecting
            .find("SiteKind::try_from_auth_type(&auth_type)")
            .expect("jira_connect stopped validating authType exactly");
        let origin_at = connecting
            .find("jira_store::https_origin(&site_url)")
            .expect("jira_connect stopped validating its origin");
        let token_at = connecting
            .find("api_token.is_empty()")
            .expect("jira_connect stopped validating its credential");
        let request_at = connecting
            .find("jira_call(JiraCall {")
            .expect("jira_connect stopped proving the credential");
        assert!(
            auth_at < origin_at && auth_at < token_at && auth_at < request_at,
            "an unknown authType can reach URL, credential, or network behavior:\n{connecting}"
        );
        assert!(
            !connecting.contains("SiteKind::from_auth_type(&auth_type)"),
            "jira_connect still guesses unknown request auth types:\n{connecting}"
        );
        assert!(
            connecting.contains("if api_token.is_empty()")
                && connecting.contains(".connect_commit(site, &api_token)")
                && !connecting.contains("api_token.trim()"),
            "jira_connect changes credential bytes between probe and persistence:\n{connecting}"
        );
    }

    #[test]
    fn authenticated_jira_error_bodies_never_become_product_text() {
        let source = strip_rust_comments(shipped_backend());
        let door = block_after(&source, "async fn jira_call(");
        let failure_path = block_after(&source, "async fn jira_failure_from_response(");
        assert!(
            door.contains("jira_failure_from_response(answer, status)")
                && failure_path
                    .contains("read_jira_response_text(answer, JIRA_ERROR_BODY_LIMIT_BYTES)")
                && failure_path.contains("failure_for_status_redacted(status, &raw)"),
            "the Jira failure path is not bounded and redacted:\n{door}\n{failure_path}"
        );
        assert!(
            !failure_path.contains("message: raw")
                && !failure_path.contains("error.to_string()")
                && !failure_path.contains("call.token")
                && !failure_path.contains("call.email")
                && !door.contains("redact_jira_error"),
            "a Jira response body can still reach an IPC error string:\n{door}"
        );

        // These are deliberately different encodings of a body-controlled
        // canary. The classifier may inspect these bytes but its product
        // sentence is constructed without them.
        for hostile in [
            "credential-canary-7f12",
            "credential%2Dcanary%2D7f12",
            r"credential\u002dcanary\u002d7f12",
            "Y3JlZGVudGlhbC1jYW5hcnktN2YxMg==",
        ] {
            let local = zerocode_core::jira::failure_for_status_redacted(
                400,
                &format!("Error in the JQL Query: Expecting {hostile}"),
            )
            .message;
            assert!(
                !local.contains(hostile),
                "authenticated upstream text crossed the Jira boundary: {local}"
            );
        }
    }

