    /// The compact navbar geometry and controls are the values measured from
    /// Orca 1.4.164, not proportions guessed from a screenshot.
    #[test]
    fn the_left_nav_uses_orcas_measured_compact_contract() {
        let styles = include_str!("../../../../ui/shell.css");
        for (selector, contracts) in [
            (".panel-add {", &["width: 24px", "height: 24px"][..]),
            (
                ".proj-row {",
                &["min-height: 28px", "font-size: var(--text-sm)"][..],
            ),
            // The workspace row is 1.4.164's CARD (`cardBody`, WorktreeCard):
            // `rounded-lg ml-1`, and a border DRAWN at rest, transparent, so
            // becoming active never shifts the row. `border: 0` and the 28px
            // floor were the 1.4.158 compact row this gate used to pin.
            //
            // `rounded-lg` is **10px**, and this pinned 8. The radius scale had
            // no `md` rung at all, so `lg` was being spelled with the value
            // below it; the scale gained one and the card went back to the rung
            // its own class names.
            (
                ".wt-row {",
                &[
                    "border: 1px solid transparent",
                    "border-radius: var(--radius)",
                    "margin-left: 4px",
                ][..],
            ),
            // A shortcut is the same kind of thing as a repository or a
            // workspace — a place in this column you can go — and it was a
            // step shorter than both, which is a third rhythm in one list.
            (".nav-row {", &["min-height: 28px"][..]),
        ] {
            let body = block_after_css(styles, selector);
            for contract in contracts {
                assert!(
                    body.contains(contract),
                    "`{selector}` drifted from measured `{contract}`:\n{body}"
                );
            }
        }
        // The shortcut's glyph is quieter than its label, and the stroke says
        // which row you are on.
        //
        // Measured on `SidebarNav` (`App-BaqTRjaA.js:8758-8763`): the label is
        // `text-worktree-sidebar-foreground/60`, the icon `/30` — half the
        // label's presence — and `strokeWidth` goes 1.75 → 2.25 on the active
        // row. Ours drew word and mark at one weight, so neither said which
        // was the name. This is the detail behind "디테일이 떨어짐".
        let nav_glyph = block_after_css(styles, ".nav-row .icon {");
        assert!(
            nav_glyph.contains("var(--ink-glyph)") && nav_glyph.contains("stroke-width: 1.75"),
            "the shortcut's glyph carries its label's full weight:\n{nav_glyph}"
        );
        // And every treatment answers for its own number. The alphas were
        // asserted here first, which is exactly how the light treatment shipped
        // a 1.93:1 icon: `/50` of a mid-grey over a near-white panel is not the
        // same step as `/50` of a light one over a dark panel.
        let tokens = include_str!("../../../../ui/tokens.css");
        for treatment in [":root {", ":root[data-theme=\"light\"] {"] {
            let block = block_after(tokens, treatment);
            for role in ["--ink-glyph:", "--ink-label:"] {
                assert!(
                    block.contains(role),
                    "`{treatment}` never says what `{role}` is, so it inherits \
                     a step measured against a different surface"
                );
            }
        }
        let nav_here = block_after_css(styles, ".nav-row[aria-current=\"page\"] .icon {");
        assert!(
            nav_here.contains("stroke-width: 2.25"),
            "the row you are on does not thicken its mark:\n{nav_here}"
        );
        assert!(
            block_after_css(styles, ".nav-row {").contains("letter-spacing: -0.025em"),
            "the shortcut row dropped Orca's `tracking-tight`"
        );
        // And the section label sits a step under the rows it labels:
        // `text-muted-foreground/80 select-none` (`App-BaqTRjaA.js:8078`).
        let section_label = block_after_css(styles, ".panel-title {");
        assert!(
            section_label.contains("var(--ink-label)")
                && section_label.contains("user-select: none"),
            "the section label is as loud as its contents, or is text somebody \
             can drag-select:\n{section_label}"
        );

        // A workspace with a shell alive in it and no agent yet is marked
        // ready — Orca's `active`, raised by the live PTY tab alone. It used
        // to be `.wt-row.is-active.is-empty`, which asked the wrong question:
        // `is-active` on the row means "the one the window is standing in", so
        // the mark followed the cursor rather than the shell.
        let live_shell = block_after_css(styles, ".wt-dot.is-done::before,");
        assert!(
            live_shell.contains("background: var(--signal-ready)"),
            "a workspace with a live shell is not marked ready:\n{live_shell}"
        );

        let window = window_source();
        let refresh = block_after(window, "async function refreshWorktrees() {");
        assert!(
            refresh.contains("await invoke(\"project_catalog\")")
                && refresh.contains("for (const project of projects)"),
            "the sidebar does not consume one stable repository/worktree catalog:\n{refresh}"
        );
        let search = block_after(window, "el(\"sidebar-search\").addEventListener(\"click\"");
        assert!(
            search.contains("togglePalette(\"worktree\")")
                && search.contains("el(\"nav-tasks\").disabled"),
            "the sidebar search is not the finder's door, or forgot the \
             nothing-to-browse refusal the chord already draws:\n{search}"
        );
        let options = block_after(window, "el(\"project-collapse\").addEventListener");
        assert!(
            options.contains("모든 프로젝트 접기") && !options.contains("활성 워크스페이스 표시"),
            "the workspace display menu lost its collapse row, or still \
             carries the reveal row whose twin moved to the toolbar's \
             crosshair:\n{options}"
        );
        assert!(
            window
                .contains("el(\"foot-reveal\").addEventListener(\"click\", revealActiveWorktree)"),
            "the toolbar's crosshair does not reveal the active workspace"
        );
    }

    /// Every navigable row in the left column starts its glyph on one rail.
    ///
    /// The column had four left edges — a section label at 0, a shortcut at
    /// 4px, a workspace at 6px and a repository at 10px, inside a panel that
    /// padded itself by another 16 — so nothing in it lined up with anything
    /// else. No measurement gate could see it, because each of the four
    /// numbers was defensible on its own and only the set was wrong.
    ///
    /// Naming the rail is what makes the rule checkable: a row consumes
    /// `--nav-inset` and `--nav-gutter` instead of writing a number, and a
    /// child list indents by `--nav-indent`, which is derived from the glyph
    /// column it has to clear rather than guessed at each level.
    #[test]
    fn the_left_column_shares_one_glyph_rail() {
        let styles = include_str!("../../../../ui/shell.css");

        for selector in [".nav-row {", ".proj-row {"] {
            let body = block_after_css(styles, selector);
            assert!(
                body.contains("var(--nav-inset)"),
                "`{selector}` sets its own left edge instead of the column's \
                 rail:\n{body}"
            );
        }

        // Every row in the column shares one glyph gutter, the CARD included:
        // the gutter is the space between a mark and the word it belongs to,
        // and that is the same distance whatever the row is.
        for selector in [".nav-row {", ".proj-row {", ".wt-row {"] {
            let body = block_after_css(styles, selector);
            assert!(
                body.contains("gap: var(--nav-gutter)"),
                "`{selector}` sets its own glyph gutter, so its label lands \
                 at a measure of its own:\n{body}"
            );
        }

        // The workspace CARD is the one exception to the rail, and it is
        // Orca's exception rather than ours. A card is not a row: its left
        // edge is the edge of a surface, and Orca gives it `ml-1` and no left
        // padding at all, putting every pixel of depth into an inline
        // `paddingLeft` of `depth * 18`
        // (`getWorktreeCardContentIndent`, WorktreeCard-D1AQ61B3.js:4603).
        // Reading `--nav-inset` here — which is what this gate used to demand
        // — added a level of indent Orca never has, and it is why the column's
        // names started further in than its own section titles.
        //
        // So what is held is the thing that actually matters: the card must
        // not invent a left number. Its horizontal placement is the margin
        // above plus `--nav-indent` on the child list, and nothing else.
        let card = block_after_css(styles, ".wt-row {");
        assert!(
            card.contains("margin-left: 4px"),
            "the workspace card lost Orca's `ml-1`, which is the whole of its \
             left offset now:\n{card}"
        );
        assert!(
            card.contains("padding: 5px 6px 6px 0"),
            "the workspace card is padding its own left edge again, which \
             indents it past the rail every other row starts on:\n{card}"
        );

        // The label above those rows is on the rail too, or the landmark and
        // the things it labels begin at two different places.
        let title = block_after_css(styles, ".panel-title {");
        // One inset FURTHER in than the rows — Orca's `px-2` container plus
        // the title's own `pl-2` (`App-BaqTRjaA.js:8074`). Derived from the
        // rail rather than typed, so the landmark cannot drift away from what
        // it labels.
        assert!(
            title.contains("padding-inline-start: var(--nav-title-inset)")
                && title.contains("min-height: var(--head-height)"),
            "the section label is off the rail or off Orca's measured h-8:\n{title}"
        );

        // The report at the end of a folded repository is a row as well.
        let hidden = block_after_css(styles, ".wt-hidden {");
        assert!(
            hidden.contains("padding-inline: var(--nav-inset)"),
            "the folded-repository report hangs off the rail:\n{hidden}"
        );

        for (selector, level) in [
            (".proj-children {", "workspaces under a repository"),
            (".wt-children:not(:empty) {", "agents under a workspace"),
        ] {
            let body = block_after_css(styles, selector);
            assert!(
                body.contains("var(--nav-indent)"),
                "the indent for {level} is a number rather than the glyph \
                 column it clears:\n{body}"
            );
        }

        // Declared once each. Both were declared twice — the file column's
        // copies came later and silently won for the whole window, which is
        // how a `letter-spacing` and an `align-items` written in the thread
        // column's blocks were never once drawn.
        for selector in [".panel-title {", ".panel-head {"] {
            assert_eq!(
                styles.matches(&format!("\n{selector}")).count(),
                1,
                "`{selector}` is declared more than once again, so what this \
                 file says about it is not what the window draws"
            );
        }
    }

    /// Hover, selection and "you are here" survive the light treatment.
    ///
    /// `--surface-raised` is #262626 over a #171717 panel and #f5f5f5 over a
    /// #fafafa one (1-g) — a step you can see in dark and a 2% step you cannot
    /// in light. Every state painted with it therefore went blank the moment
    /// the light palette became reachable, including the active workspace,
    /// which is the one fact the left column exists to tell you. Mixed out of
    /// `--ink-mist` instead, one declaration darkens a light panel and
    /// lightens a dark one and the steps stay apart in both.
    #[test]
    fn the_light_treatment_marks_the_row_you_are_on() {
        let tokens = include_str!("../../../../ui/tokens.css");
        let root = block_after(tokens, ":root {");
        for role in ["--row-hover:", "--row-selected:", "--row-active:"] {
            assert!(
                root.contains(role),
                "the row-state ladder is missing `{role}`"
            );
        }
        assert!(
            root.contains("--ink-disabled:"),
            "there is no disabled ink, so a disabled control is back to fading \
             toward whatever is behind it — which on a light panel is nothing"
        );

        let styles = include_str!("../../../../ui/shell.css");
        // A state is never a surface. `.md-code` and a table head genuinely
        // ARE surfaces, so this names the rules that carry state instead of
        // banning the token.
        for state in [
            ".nav-row:hover,\n.nav-row:focus-visible {",
            ".wt-node.is-active {",
            ".wt-node.is-selected:not(.is-active) {",
            ".foot-icon:hover,\n.foot-icon:focus-visible {",
            ".activity-tab.is-active {",
            ".segment-btn.is-active {",
        ] {
            let body = block_after_css(styles, state);
            assert!(
                !body.contains("var(--surface-raised)"),
                "`{state}` paints a state with a surface, which the light \
                 treatment has no step to show it with:\n{body}"
            );
        }

        // The shortcut whose surface is open says so, where assistive tech
        // reads it and not only where the eye does.
        assert!(
            styles.contains(".nav-row[aria-current=\"page\"] {"),
            "the left column's shortcuts have no `you are here` state"
        );
        let window = window_source();
        let painted = block_after(window, "function paintNavCurrent() {");
        assert!(
            painted.contains("aria-current")
                // 작업 now opens the Task screen (`the_tasks_row_opens_the_task_screen`),
                // not the worktree finder `⌘J` also reaches — so its `you are
                // here` mark tracks the Task scrim, the surface it actually
                // opens, not a palette mode it shares with an unrelated chord.
                && painted.contains("!taskView.hidden")
                && painted.contains("settingsSection"),
            "nothing tracks which shortcut's surface is on screen:\n{painted}"
        );

        // And the one place light is REORDERED rather than inverted: Orca's
        // light panel sits below the stage where its dark panel sits above it,
        // so a control painted with the stage colour is recessed in one
        // treatment and a hole punched through the column in the other.
        assert!(
            styles.contains(":root[data-theme=\"light\"] .panel-search {"),
            "the sidebar field is painted with the stage colour in light too, \
             where that makes it brighter than the panel holding it"
        );
    }

    /// The `default` badge reads on every row it rides.
    ///
    /// Two eras of the same contract. First it pinned its ink to `--ink-mist`
    /// at a one-off 9px and measured 3.4:1 on the active row — the fix then
    /// was `color: inherit`. Now it wears the original's own chip recipe
    /// (worktree-card-header.tsx:222): the plane's ink at 70% over ink 6%,
    /// inside ink 20%, a 16px `rounded` chip — and that recipe was measured
    /// before it replaced the inherit era: 5.9:1 on the light active wash,
    /// 6.3:1 resting light, 6.0:1 on the dark active wash, 8.3:1 resting
    /// dark. Ink-family mixes, never a panel mark (`--edge-rule` measured
    /// 1.1-1.2:1 here and stays banned), and never a bare 9px.
    #[test]
    fn the_default_badge_reads_on_every_row_it_rides() {
        let styles = include_str!("../../../../ui/shell.css");
        let badge = block_after_css(styles, ".wt-default {");

        for owed in [
            "color: color-mix(in srgb, var(--nav-plane-ink) 70%, transparent)",
            "background: color-mix(in srgb, var(--nav-plane-ink) 6%, transparent)",
            "color-mix(in srgb, var(--nav-plane-ink) 20%, transparent)",
            "height: 16px",
        ] {
            assert!(
                badge.contains(owed),
                "the badge lost the original's own recipe (`{owed}`):\n{badge}"
            );
        }
        assert!(
            !badge.contains("var(--edge-rule)"),
            "the badge outlines itself with the seam role, which measured \
             1.1-1.2:1 on every row in both treatments:\n{badge}"
        );
        assert!(
            badge.contains("font-size: var(--text-3xs)") && !badge.contains("font-size: 9px"),
            "the badge is sized off the type scale, which has no 9px:\n{badge}"
        );
    }

    /// The workspace card wears a restrained active wash.
    ///
    /// Orca established the two-treatment structure. Hover uses a quiet dark
    /// content-surface wash or 4% light ink, and neither composites under the
    /// active or selected card.
    /// Active: a translucent ink wash — 7% dark, 8% light — never the solid
    /// accent, under the 12%-into-rule border (dark) or the rule at 40%
    /// (light). Multi-selected keeps the stronger 70/35/30 selection recipe.
    /// Deleting: the card fades and greys and a pill floats
    /// over it; the destructive quick action exists only while Option/Alt is
    /// held, is cleared when focus leaves, and the main worktree never grows
    /// one.
    #[test]
    fn the_workspace_card_wears_the_titanium_active_wash() {
        let styles = include_str!("../../../../ui/shell.css");
        let hover = block_after_css(styles, ".wt-row:hover:not(.is-active):not(.is-selected) {");
        assert!(
            hover.contains("color-mix(in srgb, var(--surface-raised) 40%, transparent)"),
            "the dark hover is not the original's 40% of the darker accent:\n{hover}"
        );
        assert!(
            styles.contains(
                ":root[data-theme=\"light\"] .wt-row:hover:not(.is-active):not(.is-selected) {"
            ),
            "the light hover has no recipe of its own, which is the mode the \
             original writes a special case for"
        );
        let active = block_after_css(styles, ".wt-node.is-active {");
        assert!(
            active.contains("color-mix(in srgb, var(--nav-plane-ink) 7%, transparent)")
                && active.contains(
                    "color-mix(in srgb, var(--nav-plane-ink) 12%, var(--nav-plane-rule))"
                )
                && active.contains("inset 0 1px 0 color-mix(in srgb, var(--nav-plane-ink) 4%"),
            "the dark active card is off the titanium 7/12/inset recipe:\n{active}"
        );
        let light_active =
            block_after_css(styles, ":root[data-theme=\"light\"] .wt-node.is-active {");
        assert!(
            light_active.contains("color-mix(in srgb, var(--nav-plane-ink) 8%, transparent)")
                && light_active
                    .contains("color-mix(in srgb, var(--nav-plane-rule) 40%, transparent)")
                && light_active.contains("0 1px 2px color-mix(in srgb, var(--nav-plane-ink) 4%"),
            "the light active card is off the original's 8/40/4 recipe:\n{light_active}"
        );
        let selected = block_after_css(styles, ".wt-node.is-selected:not(.is-active) {");
        assert!(
            selected.contains("color-mix(in srgb, var(--nav-plane-accent) 70%, transparent)")
                && selected.contains("color-mix(in srgb, var(--nav-plane-ring) 35%, transparent)")
                && selected.contains("color-mix(in srgb, var(--nav-plane-ring) 30%, transparent)"),
            "the multi-selected card is off the original's 70/35/30 recipe:\n{selected}"
        );
        let deleting = block_after_css(styles, ".wt-row.is-deleting {");
        assert!(
            deleting.contains("opacity: 0.5") && deleting.contains("grayscale(1)"),
            "a deleting card does not fade and grey:\n{deleting}"
        );

        let window = window_source();
        assert!(
            window.contains("window.addEventListener(\"blur\", () => setDeleteModifier(false))")
                && window.contains(
                    "document.addEventListener(\"visibilitychange\", () => setDeleteModifier(false))"
                ),
            "stale key state after focus loss would leave destructive \
             affordances visible — the original's own reason for these two"
        );
        let builder = block_after(window, "function makeWorktreeNode(worktree, held) {");
        assert!(
            builder.contains("if (!worktree.is_main) {")
                && builder.contains("requestWorktreeRemoval(worktree)"),
            "the quick delete grew on the main worktree, or walks a second \
             removal door:\n{builder}"
        );
        assert!(
            builder.contains("if (sidebarGroupBy !== \"repo\") {"),
            "the repo chip stands where the grouping already names the \
             repository — the original's hideRepoBadge rule:\n{builder}"
        );
    }

    /// A folded repository costs no DOM.
    ///
    /// Orca's list never creates the children of a collapsed node: it pushes
    /// the header and only then asks `if (!isCollapsed)` (`buildRows`,
    /// index-ftls8Hg_.js:108091). Ours built every workspace and every agent
    /// under it and *then* set `hidden` — nodes this window allocates, styles,
    /// holds and throws away on the next refresh without ever drawing them, on
    /// a path that reruns every time a lane changes state. Since V4b the same
    /// rule is spelled as an EMPTY WINDOW: the fold decides the section's
    /// members before any row exists, and virtualization narrows what a shown
    /// section builds further to the viewport ± overscan.
    #[test]
    fn a_collapsed_repository_builds_no_rows() {
        let window = window_source();
        let painting = block_after(window, "async function refreshWorktrees() {");

        assert!(
            painting.contains("windowedWorktreeList(children.hidden ? [] : shown, held)"),
            "a collapsed repository builds rows again — the fold no longer \
             empties its window:\n{painting}"
        );

        // The eye and the keyboard count one list, so the rows that are not
        // built have to be the rows `visibleWorktrees` already leaves out —
        // and BOTH now go through the display filter, not just the paint. The
        // fold releases its rows only in the grouped view: the flat list has
        // no headers to fold, so there `closedProjects` must not hide chords.
        assert!(
            painting.contains("sidebarGroupBy === \"none\" || !closedProjects.has(project.path)"),
            "the digit chords count a list the sidebar no longer draws:\n{painting}"
        );
        // One definition, walked by both the builder and the shape guard —
        // a reorder only one of them saw is a list that does not repaint when
        // the order changes.
        assert!(
            painting.contains("const listed = listedProjects();"),
            "the 표시 menu's repository filter no longer feeds the visible \
             list, so a hidden project still answers ⌘1…9:\n{painting}"
        );
        let choosing = block_after(window, "function listedProjects() {");
        assert!(
            choosing.contains("!sidebarHiddenProjects.has(project.path)"),
            "the one definition of which repositories are listed stopped \
             reading the 표시 menu's checkboxes:\n{choosing}"
        );
        assert!(
            painting.contains("    const shown = shownWorktrees(project);"),
            "the paint loop reads the catalog directly again, so the hide \
             filter and the digit chords disagree about the list:\n{painting}"
        );
    }

    /// No two of the sidebar's controls lead to the same place.
    ///
    /// 자동화, 단축키 and the gear all called `setSettingsOpen(true)`: three
    /// names, three glyphs, one destination — the top of one dialog. A control
    /// that only looks the part is worse than a missing one, and that holds
    /// when the thing it opens is real but is already reachable beside it.
    #[test]
    fn every_left_nav_row_goes_somewhere_of_its_own() {
        let window = strip_comments(window_source());
        let markup = include_str!("../../../../ui/index.html");

        let mut destinations: Vec<&str> = Vec::new();
        for control in ["nav-automations", "foot-settings", "foot-keys"] {
            let wired = window
                .find(&format!("el(\"{control}\").addEventListener"))
                .unwrap_or_else(|| panic!("`{control}` is no longer wired to anything"));
            let opens = window[wired..]
                .find("setSettingsOpen(")
                .map(|to| wired + to)
                .unwrap_or_else(|| panic!("`{control}` no longer opens settings"));
            let end = window[opens..]
                .find(')')
                .map_or(window.len(), |to| opens + to);
            destinations.push(&window[opens..end]);
        }
        for (one, other) in [(0, 1), (0, 2), (1, 2)] {
            assert_ne!(
                destinations[one], destinations[other],
                "two of the sidebar's controls open the same thing: {destinations:?}"
            );
        }

        // A section a control names has to exist, or it opens a dialog and
        // scrolls to nothing — the same dead control wearing a new argument.
        for section in ["terminal-command", "settings-keys"] {
            assert!(
                markup.contains(&format!("id=\"{section}\"")),
                "a control opens settings at `{section}`, which the dialog \
                 does not contain"
            );
        }

        // And the mark follows the section, not the dialog. All three of these
        // raise the same scrim, so a `you are here` that only asks whether
        // settings is open puts the mark on 자동화 when somebody pressed the
        // gear — a row claiming to be the destination nobody chose.
        let painted = block_after(&window, "function paintNavCurrent() {");
        assert!(
            painted.contains("settingsSection"),
            "the `you are here` mark asks whether settings is open rather than \
             which section was opened:\n{painted}"
        );

        // A title must not claim a chord nothing binds. `mod+,` belongs to
        // `app.settings` alone, so only the gear may say ⌘, — the other two
        // opened a different section and advertised a key that does not go
        // there.
        let bound = block_after(&window, "const ACTIONS = [");
        assert_eq!(
            bound.matches("chord: \"mod+,\"").count(),
            1,
            "more than one action claims ⌘,, so the titles cannot say which \
             one it reaches:\n{bound}"
        );
        for key in ["view.automationsTitle", "app.shortcutsTitle"] {
            for line in window.lines().filter(|line| line.contains(key)) {
                assert!(
                    !line.contains('⌘'),
                    "`{key}` advertises a chord that reaches a different \
                     destination: {line}"
                );
            }
        }
        for control in ["id=\"nav-automations\"", "id=\"foot-keys\""] {
            let line = markup
                .lines()
                .find(|line| line.contains(control))
                .unwrap_or_else(|| panic!("`{control}` is gone from the markup"));
            assert!(
                !line.contains('⌘'),
                "`{control}` still advertises a chord that opens a different \
                 section: {line}"
            );
        }
    }

    /// A repository's own menu acts on that repository.
    ///
    /// It offered `프로젝트 설정`, which called a wrapper that took the
    /// project's path and threw it away to open the window's global settings.
    /// A label naming a thing the action does not touch is the same defect as
    /// a dead control: the person aims at one repository and something else
    /// answers.
    #[test]
    fn a_project_menu_acts_on_the_project_it_was_opened_on() {
        let window = window_source();
        assert!(
            !window.contains("openProjectSettings"),
            "the wrapper that swallowed a repository's path is back"
        );
        let menu = block_after(window, "function projectMenuAt(x, y, path = null) {");
        assert!(
            menu.contains("openWorktreeFormForProject(path)"),
            "the repository menu offers nothing that acts on that \
             repository:\n{menu}"
        );
        assert!(
            !menu.contains("프로젝트 설정"),
            "the menu still labels the window's global settings as this \
             repository's:\n{menu}"
        );
    }

    /// The active checkout and the repository that owns it are one fact.
    ///
    /// They were two mutexes, and every git command took them one after the
    /// other — so a workspace switch landing between the two reads would pair
    /// a new root with the previous repository's orchestrator and run git in a
    /// checkout that repository has never heard of. One lock, and one snapshot
    /// per command.
    #[test]
    fn the_active_checkout_and_its_repository_are_one_fact() {
        let backend = shipped_backend();
        let state = block_after(backend, "struct ShellRuntime {");

        assert!(
            !state.contains("orchestrator: Mutex<"),
            "the repository is held in a lock of its own again, so it can be \
             read a moment apart from the checkout it owns:\n{state}"
        );
        assert!(
            state.contains("active: Mutex<ActiveContext>"),
            "the checkout and its repository are not one value:\n{state}"
        );
        assert!(
            backend.contains("struct ActiveContext {"),
            "the value that pairs a checkout with its repository is gone"
        );

        // `create_worktree` is deliberately absent: its repository can be a
        // project the person named rather than the active one, and the root it
        // reads is only used to mark which entry is active.
        for command in [
            "fn scm_status(",
            "fn stage_path(",
            "fn unstage_path(",
            "async fn commit_staged(",
            "fn file_diff(",
            "fn list_worktrees(",
            "fn project_catalog(",
        ] {
            let body = block_after(backend, command);
            assert_eq!(
                body.matches("state.active()").count(),
                1,
                "`{command}` does not take exactly one snapshot of the active \
                 context:\n{body}"
            );
            assert!(
                !body.contains("state.orchestrator()") && !body.contains("state.active_root()"),
                "`{command}` still reads the repository and the checkout \
                 separately:\n{body}"
            );
        }

        // Project settings need the same guarantee. A checkout is the legacy
        // migration source while its repository root is the durable key; if a
        // switch lands between two reads, one project's edit can be filed
        // under another project's key.
        for command in [
            "fn project_scripts(",
            "fn default_tabs(",
            "fn set_project_script_policy(",
            "fn set_project_script_setting(",
        ] {
            let body = block_after(backend, command);
            assert_eq!(
                body.matches("state.active_project_context()").count(),
                1,
                "`{command}` does not take exactly one project context \
                 snapshot:\n{body}"
            );
            assert!(
                !body.contains("state.active_root()")
                    && !body.contains("state.active_project_root()")
                    && !body.contains("project_scripts(state)"),
                "`{command}` can read a second active context:\n{body}"
            );
        }

        let project_snapshot = block_after(backend, "fn active_project_context(&self)");
        assert_eq!(
            project_snapshot.matches("self.active()").count(),
            1,
            "the project-context helper does not derive both paths from one \
             active snapshot:\n{project_snapshot}"
        );
    }

    /// The markdown preview builds nodes and never parses HTML.
    ///
    /// A file viewer that renders a document's HTML is a file viewer that
    /// runs whatever a repository happens to contain. The whole preview path
    /// puts text through `textContent` and elements through
    /// `createElement`, so a `<script>` in a README shows up as the
    /// characters somebody typed.
    #[test]
    fn the_markdown_preview_never_parses_what_it_is_shown() {
        let window = window_source();
        for name in [
            "function paintInline(into, text) {",
            "function paintMarkdown(body, text) {",
            "function paintTable(body, text, tabbed) {",
        ] {
            let body = block_after(window, name);
            assert!(
                !body.contains("innerHTML"),
                "`{name}` puts a document's own text through the HTML \
                 parser:\n{body}"
            );
        }
        // A link that leaves the project is drawn as text. An `<a href>` in a
        // webview navigates the window away from the application, which is
        // not a thing a viewer should be able to do to you.
        let link = block_after(window, "function mdLink(label, href, line = undefined) {");
        assert!(
            !link.contains("\"a\""),
            "a markdown link is an anchor, which would navigate the app \
             away from itself:\n{link}"
        );
    }

    /// A scheduled run is recorded before its prompt is delivered.
    ///
    /// The run is spent the moment the agent is started, not when the prompt
    /// lands. Recording it afterwards — or only on success — means a delivery
    /// that times out leaves `last_run_at` untouched, the next sweep finds the
    /// job still due, and it starts a second shell. A job whose agent is slow
    /// to wake would stack one every minute until somebody noticed.
    ///
    /// And the sweep runs once a MINUTE, not once a round. The schedule has
    /// minute resolution; asking at the display rate would read the
    /// automations file sixty times a second to learn nothing.
    #[test]
    fn a_scheduled_run_is_spent_when_it_starts_not_when_it_lands() {
        let backend = shipped_backend();
        let starting = block_after(backend, "fn start_automation(");
        let record = starting
            .find("let _ = remember_run(")
            .expect("a run is no longer recorded at all");
        let deliver = starting
            .find("deliveries().insert(")
            .expect("a run no longer posts its prompt");
        assert!(
            deliver < record,
            "the run is recorded before the prompt is even posted, which is \
             fine; what must not happen is recording it conditionally on the \
             delivery — check this function by hand"
        );
        assert!(
            !starting.contains("if delivered") && !starting.contains(".is_ok()"),
            "the run is recorded conditionally, so a slow agent stacks a \
             shell every sweep:\n{starting}"
        );

        let remembering = block_after(backend, "fn remember_run(");
        assert!(
            remembering.contains("held.last_run_at = Some(at.epoch_minutes);")
                && remembering.contains("write_automation_runs(local_data_root, &history)")
                && remembering.contains("write_automations(config_root, &rows)"),
            "the run no longer durably consumes its occurrence:\n{remembering}"
        );
        let ticking = block_after(backend, "fn tick_automations(");
        assert!(
            ticking.contains("occurrence_recorded(&history, &automation.id, at)"),
            "the ledger cannot fence a consumed occurrence when the schedule stamp fails"
        );

        let looping = block_after(backend, "fn pump_loop(app: &AppHandle) {");
        assert!(
            looping.contains("swept != Some(minute.epoch_minutes)"),
            "the schedule is consulted every round rather than every minute:\n{looping}"
        );
    }

    /// An automation whose mode says so gets its own checkout — and the run
    /// happens IN it.
    ///
    /// Orca's automation-born workspaces (`automationProvenance.kind ===
    /// "created-by-automation"`, worktree-activation-3qRw45tK.js:1560-1562;
    /// headless provisioning main:190146). The three decisions the gate pins:
    ///
    /// - `NewPerRun` cuts the worktree BEFORE the spawn, and the pty's cwd is
    ///   the cut path — a run that lands in the stored workspace has quietly
    ///   become `Existing` with extra steps.
    /// - The base is handed to git verbatim and git validates it: a branch
    ///   that stopped existing since the job was written refuses tonight, out
    ///   loud, instead of running the job somewhere it did not mean.
    /// - The made checkout is ANNOUNCED — in the started event and the
    ///   run-now answer — because a workspace born at 9am with nobody watching
    ///   is otherwise a directory the sidebar has never heard of.
    #[test]
    fn an_automations_run_gets_its_own_checkout() {
        let backend = shipped_backend();
        let (shipped, _) = backend.split_once("#[cfg(test)]").unwrap_or((backend, ""));
        let window = window_source();

        let starting = block_after(shipped, "fn start_automation(");
        assert!(
            starting.contains("zerocode_core::WorkspaceMode::NewPerRun =>"),
            "start_automation no longer branches on the workspace mode:\n{starting}"
        );
        assert!(
            starting.contains(".create_from(&task, automation.base_branch.as_deref())"),
            "the fresh checkout is not cut from the job's named base:\n{starting}"
        );
        // The cut decides the cwd: the match that produces `root` must come
        // before the spawn that uses it, and the spawn reads `root`.
        let cutting = starting
            .find("match automation.workspace_mode {")
            .expect("no mode branch");
        let spawning = starting
            .find(
                r#"PtyLane::spawn(
        &program,
        &args,
        Some(&root),"#,
            )
            .expect("the spawn stopped using the resolved root");
        assert!(
            cutting < spawning,
            "the worktree is cut after the shell has already spawned \
             elsewhere:\n{starting}"
        );
        // And the NewPerRun arm's ROOT is the cut path — the exact production,
        // because a mutation that cuts, announces, and then spawns in the
        // stored workspace passes every order check while running the job in
        // the wrong place. (That mutation was tried, and this line is what
        // catches it.)
        assert!(
            starting.contains("(path.clone(), Some(path), Some(orchestrator))"),
            "the fresh checkout is cut and announced but the run stays in the \
             stored workspace:\n{starting}"
        );
        // And the made path travels out.
        assert!(
            starting.contains("worktree: made.map(|path| path.display().to_string())"),
            "the made checkout is announced nowhere:\n{starting}"
        );

        // The window tells the sidebar on both roads a run starts by.
        let heard = block_after(window, r#"listen("automation:started""#);
        assert!(
            heard.contains("if (event.payload?.worktree) void refreshWorktrees();"),
            "a scheduled run's new workspace never reaches the sidebar:\n{heard}"
        );

        // The form's base field is serialised as absence when empty — HEAD is
        // the default, not a magic word in the record.
        let saving = block_after(window, "async function saveAutomation(");
        assert!(
            saving.contains(r#"base_branch: el("auto-base").value.trim() || null,"#)
                && saving.contains(r#"workspace_mode: el("auto-mode").value,"#),
            "the form no longer carries the mode and base into the record:\n{saving}"
        );
    }

    /// The form can SET reuse, grace, and the precheck timeout — not only
    /// carry whatever a draft was born with.
    ///
    /// The backend has honoured all three since `save_automation` normalised
    /// `reuse_session` (main:5026) and `start_automation` read
    /// `precheck_timeout_seconds` (main:5096) and the sweep read
    /// `missed_run_grace_minutes` (automation.rs `next_after`). But the form
    /// had no controls, so `saveAutomation`'s `...autoDraft` spread froze them
    /// at a new job's defaults — false / 60 / 60 — with no way to change them.
    /// That is the exact shape Orca's own form gives them
    /// (AutomationsPage: `reuseSession`, `precheckTimeoutSeconds`,
    /// `missedRunGraceMinutes`), reuse coupled to the one mode that keeps a
    /// checkout to reuse.
    ///
    /// The pins are contiguous blocks at the object/function indentation, not
    /// scattered substrings: a mutation that drops any one line — or reverts
    /// to the passthrough — breaks the block, and the id counts catch a stray
    /// or missing wiring that a `contains` alone would sail past.
    #[test]
    fn the_automation_form_can_set_reuse_grace_and_precheck_timeout() {
        let window = window_source();
        let markup = include_str!("../../../../ui/index.html");

        // Built from the form, as a contiguous block. Reuse is gated on the
        // mode whose runs can reuse anything — a field the backend would
        // ignore is a promise the form must not make.
        let saving = block_after(window, "async function saveAutomation(");
        assert!(
            saving.contains(concat!(
                r#"    reuse_session: el("auto-mode").value === "existing" && el("auto-reuse").checked,"#,
                "\n",
                r#"    precheck_timeout_seconds: Number(el("auto-precheck-timeout").value),"#,
                "\n",
                r#"    missed_run_grace_minutes: Number(el("auto-grace").value),"#,
                "\n",
            )),
            "saveAutomation no longer reads reuse/timeout/grace from the form — \
             the three fields are frozen at their draft defaults again:\n{saving}"
        );

        // Editing a saved job shows what it stored, so a change is a change
        // FROM the current value, not a silent reset to the defaults.
        let editing = block_after(window, "function editAutomation(");
        assert!(
            editing.contains("  el(\"auto-reuse\").checked = autoDraft.reuse_session;\n"),
            "editing a saved job no longer shows its stored reuse choice:\n{editing}"
        );
        assert!(
            editing.contains(concat!(
                r#"  el("auto-precheck-timeout").value = String(autoDraft.precheck_timeout_seconds);"#,
                "\n",
                r#"  el("auto-grace").value = String(autoDraft.missed_run_grace_minutes);"#,
                "\n",
            )),
            "editing a saved job no longer shows its stored timeout/grace:\n{editing}"
        );

        // The reuse toggle appears only for the mode that reads it.
        let moding = block_after(window, "function paintAutoMode() {");
        assert!(
            moding.contains("el(\"auto-reuse-field\").hidden = mode !== \"existing\";"),
            "the reuse toggle is shown for a mode whose runs cannot reuse \
             anything:\n{moding}"
        );

        // The timeout disables itself when there is no precheck to time.
        let timing = block_after(window, "function paintPrecheckTimeout() {");
        assert!(
            timing.contains(
                "el(\"auto-precheck-timeout\").disabled = el(\"auto-precheck\").value.trim() === \"\";"
            ),
            "the timeout no longer disables itself when there is no precheck \
             to time:\n{timing}"
        );

        // Each control is wired exactly where it belongs and nowhere spurious:
        // grace and reuse in save + edit (2), the timeout also in its own
        // enable/disable painter (3). Counted over the window, so the gate's
        // own string literals here do not inflate the tally.
        assert_eq!(
            window.matches(r#"el("auto-grace")"#).count(),
            2,
            "auto-grace is wired in the wrong number of places"
        );
        assert_eq!(
            window.matches(r#"el("auto-precheck-timeout")"#).count(),
            3,
            "auto-precheck-timeout is wired in the wrong number of places"
        );
        assert_eq!(
            window.matches(r#"el("auto-reuse")"#).count(),
            2,
            "auto-reuse is wired in the wrong number of places"
        );

        // The controls exist in the form, with the exact value contract the
        // backend reads: seconds for the timeout, minutes for the grace, as
        // contiguous option blocks so dropping or renumbering one is caught.
        assert!(
            markup.contains(r#"<input type="checkbox" id="auto-reuse" />"#)
                && markup.contains(r#"id="auto-reuse-field""#),
            "the reuse checkbox, or the id paintAutoMode hides it by, is gone \
             from the form"
        );
        assert!(
            markup.contains(concat!(
                r#"                <option value="30">30초</option>"#,
                "\n",
                r#"                <option value="60">1분</option>"#,
                "\n",
                r#"                <option value="120">2분</option>"#,
                "\n",
                r#"                <option value="300">5분</option>"#,
                "\n",
                r#"                <option value="600">10분</option>"#,
                "\n",
            )),
            "the precheck-timeout values no longer match the backend's seconds"
        );
        assert!(
            markup.contains(concat!(
                r#"                <option value="0">유예 없음</option>"#,
                "\n",
                r#"                <option value="30">30분</option>"#,
                "\n",
                r#"                <option value="60">1시간</option>"#,
                "\n",
                r#"                <option value="180">3시간</option>"#,
                "\n",
                r#"                <option value="720">12시간</option>"#,
                "\n",
                r#"                <option value="1440">24시간</option>"#,
                "\n",
                r#"                <option value="2880">48시간</option>"#,
                "\n",
            )),
            "the grace values no longer match the backend's minutes"
        );

        // The labels carry their keys, and the keys have entries to find.
        for key in ["auto.reuse", "auto.grace", "auto.precheckTimeout"] {
            assert!(
                markup.contains(&format!("data-i18n=\"{key}\"")),
                "the {key} label lost its translation key"
            );
            assert!(
                window.contains(&format!("\"{key}\": \"")),
                "the {key} label has no catalog entry"
            );
        }
    }

    /// An agent that never reported a hook is still SEEN while its shell runs.
    ///
    /// `pane_agents` used to default an unreported pane to "idle" — the one
    /// bucket the board hides unless 「대기 중도 보기」 is on. A vendor with no
    /// hook integration therefore ran invisibly, which is the exact situation
    /// the board exists to show ("에이전트들이 표시가 안되는데 실제 지금
    /// 돌고잇는거"). The default now asks the pty registry: a live shell we
    /// launched as an agent is working; only a dead one may rest.
    #[test]
    fn an_unreported_live_agent_is_working_not_hidden() {
        let backend = shipped_backend();
        let (shipped, _) = backend.split_once("#[cfg(test)]").unwrap_or((backend, ""));
        let listing = block_after(shipped, "fn pane_agents(");
        assert!(
            listing.contains(concat!(
                "                    .unwrap_or_else(|| {\n",
                "                        if living.contains(term) {\n",
                "                            \"working\"\n",
                "                        } else {\n",
                "                            \"idle\"\n",
                "                        }\n",
                "                        .to_string()\n",
                "                    }),\n",
            )),
            "an unreported agent no longer defaults on liveness — a hookless \
             vendor runs invisibly again:\n{listing}"
        );
        // The liveness set is read before the `agent_terms` guard is taken, so
        // the two locks never overlap.
        let living = listing
            .find("state.terminals().terms()")
            .expect("the liveness set is no longer collected from the registry");
        let terms = listing
            .find(".agent_terms()")
            .expect("pane_agents no longer walks agent_terms");
        assert!(
            living < terms,
            "the liveness set is collected while agent_terms is already \
             locked:\n{listing}"
        );
    }

    /// Picking the active project while the board covers the stage brings the
    /// terminal back.
    ///
    /// The same-worktree branch of `activateWorktree` asked only whether a
    /// PAGE covered the stage (작업/자동화/설정). The board covers it as a
    /// TAB, so the pick fell through to "already here" and nothing moved —
    /// "프로젝트 클릭시 터미널이 보여야하는데 지금 보드에서 옮겨지지도 않음".
    /// The branch now sees the board and hands back the workspace's own
    /// terminal — never the board itself, which is why the fallback is a
    /// fresh terminal rather than `restoreActiveWorktreeTab`, whose remembered
    /// tab could BE the board.
    #[test]
    fn a_project_click_brings_the_terminal_back_over_the_board() {
        let window = window_source();
        let moving = block_after(window, "async function activateWorktree(");
        assert!(
            moving.contains("    const staged = tabs.find((held) => held.id === activeTabId);\n")
                && moving.contains("    const boarded = staged?.kind === \"board\";\n"),
            "the same-worktree branch no longer reads what is staged:\n{moving}"
        );
        // A removal re-roots the backend before this function hears about it,
        // so the click can arrive with the active tab gone or foreign — that
        // stage is covered by nothing and still owes the click its terminal.
        assert!(
            moving.contains(
                "    const stranded = staged === undefined || (!boarded && staged.worktree !== path);\n"
            ) && moving.contains("    if (covered || boarded || stranded) {\n")
                && moving.contains("      if (boarded || stranded) {\n"),
            "a stage stranded by a removal reads as \"already fine\" again:\n{moving}"
        );
        assert!(
            moving.contains(concat!(
                "        const owned = tabs.filter(\n",
                "          (held) => held.worktree === path && held.kind !== \"board\",\n",
                "        );\n",
            )),
            "the way back can hand the board tab right back:\n{moving}"
        );
        assert!(
            moving.contains(concat!(
                "        if (back) setActiveTab(back.id);\n",
                "        else await openTermTab();\n",
            )),
            "the board no longer yields to the workspace's terminal:\n{moving}"
        );

        // And the removal flows sweep their dead tabs — the ghost the
        // stranded branch exists to catch must also stop being made. Term
        // shells are ended, not just dropped: a process whose ground was
        // deleted with nothing on screen addressing it is a leak.
        let removing = block_after(window, "async function removeWorktree(");
        assert!(
            removing.contains("await finishWorktreeRemoval(worktree);"),
            "the confirmed removal bypasses the one cleanup owner:\n{removing}"
        );
        let finishing = block_after(window, "async function finishWorktreeRemoval(worktree) {");
        assert!(
            finishing.contains("dropWorktreeSurfaces(path);"),
            "a removed worktree leaves its tabs behind again:\n{finishing}"
        );
        let sweeping = block_after(window, "function dropWorktreeSurfaces(path) {");
        assert!(
            sweeping.contains(concat!(
                "  for (const held of tabs.filter((one) => one.worktree === path)) {\n",
                "    if (held.kind === \"term\") {\n",
                "      for (const term of paneLeaves(held.layout)) {\n",
                "        invoke(\"close_term\", { term }).catch(() => {});\n",
                "        dropTermView(term);\n",
                "      }\n",
                "    }\n",
                "    dropTab(held.id);\n",
                "  }\n",
            )),
            "the one sweep no longer ends the shells it drops:\n{sweeping}"
        );
        assert!(
            finishing.contains("projectOfWorktree(held.path)?.path === home,"),
            "the landing after a removal stopped being this project's own \
             main:\n{finishing}"
        );
        let unlisting = block_after(window, "async function removeProjectFromList(");
        assert!(
            unlisting
                .contains("for (const held of tabs.filter((held) => gone.has(held.worktree))) {"),
            "a removed project leaves every worktree's tabs behind again:\n{unlisting}"
        );
    }

    /// Half-built jamo never reach the pty — unassembled.
    ///
    /// The sink sees text the IME never composed: the platform's input
    /// context attaches a beat after focus (and after an input-source
    /// switch), so a word's first keys can land as bare compatibility jamo.
    /// Forwarding them typed ㄴㅇㅏㅇㅣ one half-letter at a time
    /// ("터미널에서 한글이 ㄴ ㅇ ㅏ ㅇ ㅣ이런식으로 나옴"); the drop that
    /// replaced it ate the first letter of the first word instead ("첫
    /// 글자가 씹히는거같은데"). Both lose, so neither ships: bare jamo now
    /// walk the window's own 2-set automaton (`foldHangul`, 1-fi) and reach
    /// the pty as the finished syllables the IME would have made. This gate
    /// holds that boundary in three places.
    #[test]
    fn half_built_jamo_never_reach_the_pty() {
        let window = window_source();
        // The drain recognizes bare jamo — one spelling, `HANGUL_JAMO` —
        // and hands them to the rescue, never to `drainKeySink`.
        let draining = block_after(window, r#"keySink.addEventListener("input", () => {"#);
        assert!(
            draining.contains("if (HANGUL_JAMO.test(keySink.value)) {")
                && draining.contains("holdRescue(raw);"),
            "bare jamo no longer walk the rescue automaton:\n{draining}"
        );
        // The rescue commits through the same one door all typed text uses.
        let flushing = block_after(window, "function flushRescue() {");
        assert!(
            flushing.contains("routeText(text)"),
            "the rescue types around `routeText`:\n{flushing}"
        );
        // And the seam with the arriving IME does not flush half a word
        // ahead of it — that is how 로 landed as "ㄹ" then "ㅗ" ("한글이
        // 한번씩 ㄹ ㅗ 이런식으로 씹혀"). Composition start HOLDS what the
        // rescue has, before it marks the composition open, and the drain
        // joins the held head to what the IME commits.
        let seam = block_after(
            window,
            r#"keySink.addEventListener("compositionstart", () => {"#,
        );
        assert!(
            !seam.contains("flushRescue()"),
            "the seam went back to flushing half a word ahead of the IME:\n{seam}"
        );
        let held = seam.find("wordJamos.push(...rescueJamos);");
        let opened = seam.find("composing = true;");
        assert!(
            held.is_some_and(|at| opened.is_some_and(|open| at < open)),
            "the rescue's half-word no longer opens the word run before the \
             composition is marked open:\n{seam}"
        );
        // The run rebuilds the WORD: commits are decomposed back to jamo and
        // refolded behind the stolen head, because the black box proved the
        // IME runs one jamo short for the whole word (문자 → 무ㄴ자,
        // window-errors.log 2026-08-18) — a one-syllable join cannot repair
        // that.
        let draining = block_after(window, "function drainKeySink() {");
        assert!(
            draining.contains("wordJamos.push(...decomposeHangul(text));"),
            "the drain no longer feeds commits back through the automaton:\n{draining}"
        );
        // A composition that ENDS with only half a letter in it is not
        // finished text either, and the drain used to type it at the pty like
        // any syllable — five of them walked into a shell in one evening
        // (window-errors.log 2026-09-22, t-5835). It waits for the key that
        // caused it instead, and there is exactly one holder and one release.
        assert!(
            draining.contains("holdHalfLetter(joined);"),
            "the drain types half a letter straight at the pty again:\n{draining}"
        );
        let escort = block_after(window, "function escortHalfLetter() {");
        assert!(
            escort.contains("routeText(text)") && escort.contains("reportStrayJamo("),
            "the held half letter leaves by a door the husk is not watching:\n{escort}"
        );
        // Released on every road the person's next act can arrive on, so
        // nothing they type can overtake the half letter they typed first.
        for road in [
            r#"keySink.addEventListener("keydown", (event) => {"#,
            r#"keySink.addEventListener("compositionstart", () => {"#,
            r#"keySink.addEventListener("input", () => {"#,
        ] {
            let body = block_after(window, road);
            assert!(
                body.contains("escortHalfLetter()"),
                "a half letter can be overtaken on `{road}`:\n{body}"
            );
        }
    }

    /// Typing in a diff is saved by the save that already exists.
    ///
    /// Orca's `readOnly: !editable` / `originalEditable: false` pair, and the
    /// one rule that keeps them from becoming a second file surface: the
    /// modified side of a side-by-side diff IS the working file, so it is
    /// dirty in the sense a file tab is dirty and written by the write a file
    /// tab is written by. A second save path would be a second optimistic
    /// lock, a second `create_if_missing`, and every bug in the first one
    /// found again a year later.
    #[test]
    fn a_diff_that_is_typed_in_saves_through_the_one_save() {
        let window = window_source();
        // ONE write in the whole window. This is the gate: a diff-shaped copy
        // of `saveFile` would show up here and nowhere else.
        assert_eq!(
            window.matches("invoke(\"write_text_file\"").count(),
            1,
            "the window has grown a second way to write a file"
        );
        let saving = block_after(window, "async function saveFile(tab) {");
        assert!(
            saving.contains("if (tab?.kind !== \"file\" && tab?.kind !== \"diff\") return false;"),
            "the one save no longer takes the diff surface"
        );
        // Read-only is a fact about the stamp, not a flag somebody sets. No
        // stamp, nothing to hand back to the version check, nothing to write.
        assert!(
            saving.contains("if (tab.kind === \"diff\" && tab.version == null) return false;"),
            "a diff with no version stamp can now be saved"
        );
        // The dirty comparison is one sentence for both kinds — the strip's
        // mark, the close guard and ⌘S all read it.
        assert!(
            block_after(window, "function isDirty(tab) {")
                .contains("(tab?.kind === \"file\" || tab?.kind === \"diff\") &&"),
            "typing in a diff no longer counts as work only this window holds"
        );
        // And the editable side is decided by that same stamp where the
        // editor is built, rather than by a second opinion.
        assert!(
            block_after(window, "function paintDiffMerge(view, tab) {")
                .contains("const editable = Boolean(tab.version);"),
            "the merge view decides what is editable some other way"
        );
    }

    /// The shape a diff opens in is the person's, and it is remembered.
    ///
    /// Orca's `renderSideBySide` is a toggle, not a computed value, and it
    /// rides in the boot report rather than being fetched when the first diff
    /// opens: a diff that paints inline and re-lays itself into two columns a
    /// frame later has mounted two editors to show one file.
    #[test]
    fn the_side_by_side_toggle_is_remembered_and_arrives_with_the_first_frame() {
        let backend = shipped_backend();
        let (shipped, _) = backend.split_once("#[cfg(test)]").unwrap_or((backend, ""));
        assert!(
            shipped.contains("            set_diff_side_by_side,"),
            "the toggle is not on the command list, so saving it fails at runtime"
        );
        // ON unless this machine has said otherwise. The default belongs to
        // the typed document now; neither the boot report nor the renderer
        // gets a second defaulting rule.
        assert!(
            block_after(shipped, "impl Default for SettingsDocument {")
                .contains("diff_side_by_side: true,"),
            "a machine that has never been asked no longer opens diffs side by side"
        );

        let window = window_source();
        assert_canonical_setting_round_trip(
            backend,
            window,
            "set_diff_side_by_side",
            "setting_key::DIFF_SIDE_BY_SIDE",
            "settings.diff_side_by_side = on;",
            "function setDiffSideBySide(on) {",
            "diff_side_by_side",
            "diffSideBySide = snapshot.diff_side_by_side !== false;",
        );
        let setting = block_after(window, "function setDiffSideBySide(on) {");
        // Every open diff, not the one that was clicked: the setting belongs
        // to the person, so a second leaf must not keep the shape they just
        // moved away from.
        assert!(
            setting.contains(
                "for (const held of tabs) if (held.kind === \"diff\") paintDiffView(held);"
            ),
            "the toggle repaints only the diff it was clicked on"
        );
        // The rows are what a review note hangs from, and they are still the
        // inline shape rather than a second merge view — 1-eh kept that
        // surface deliberately.
        assert!(
            block_after(window, "function paintDiffView(tab) {")
                .contains("const beside = diffSideBySide && diffMergeable(tab);"),
            "the diff no longer chooses its shape from the toggle and the pair"
        );
    }

    /// The panel that commits can also push, pull and publish — with the
    /// button saying which one it will do.
    ///
    /// Orca's own argv and action table (1-dp): `--set-upstream origin HEAD`
    /// is what makes publish and push one button; `--left-right` counts the
    /// LEFT side first and the left side is the upstream, which is BEHIND —
    /// swapping the two reads makes a button that offers a push when a pull
    /// is due. The diverged case runs pull then push, the only order in
    /// which the push can fast-forward.
    #[test]
    fn the_sync_button_pushes_pulls_and_publishes_by_standing() {
        let backend = shipped_backend();
        let (shipped, _) = backend.split_once("#[cfg(test)]").unwrap_or((backend, ""));
        let window = window_source();
        let markup = include_str!("../../../../ui/index.html");

        for command in [
            "\n            upstream_status,\n",
            "\n            scm_push,\n",
            "\n            scm_pull,\n",
        ] {
            assert!(
                shipped.contains(command),
                "a sync command fell out of the window's registration:{command}"
            );
        }
        let standing = block_after(shipped, "fn upstream_status(");
        assert!(
            standing.contains(concat!(
                "    let mut split = counts.split_whitespace();\n",
                "    let behind = split.next().and_then(|n| n.parse().ok()).unwrap_or(0);\n",
                "    let ahead = split.next().and_then(|n| n.parse().ok()).unwrap_or(0);\n",
            )),
            "left-right's left side stopped being read as behind:\n{standing}"
        );
        assert!(
            standing.contains(r#"&["rev-list", "--left-right", "--count", "@{upstream}...HEAD"]"#),
            "the standing no longer comes from one left-right count:\n{standing}"
        );
        let pushing = block_after(shipped, "fn scm_push(");
        assert!(
            pushing.contains(r#"args.extend_from_slice(&["--set-upstream", "origin", "HEAD"]);"#),
            "the push lost Orca's own argv — publish and push stop being one \
             button:\n{pushing}"
        );
        let pulling = block_after(shipped, "fn scm_pull(");
        assert!(
            pulling.contains(r#"&["pull", "--ff-only"]"#) && pulling.contains(r#"&["pull"]"#),
            "the pull stopped being git's own bare pull with Orca's one \
             fast-forward mode (`gitFastForward` = the same pull carrying \
             `--ff-only`):\n{pulling}"
        );

        // The window's half: one decision function every surface reads, and
        // the compound sync that fetches before it judges.
        let deciding = block_after(window, "function scmPrimaryAction(status) {");
        assert!(
            deciding.contains(concat!(
                "  if (upstream === null) return \"publish\";\n",
                "  if (ahead > 0 && behind > 0) return shouldForcePushWithLease(status) ",
                "? \"force_push\" : \"sync\";\n",
                "  if (behind > 0) return \"pull\";\n",
                "  if (ahead > 0) return \"push\";\n",
            )),
            "the standing no longer resolves to one action:\n{deciding}"
        );
        let acting = block_after(window, "async function runScmAction(action) {");
        assert!(
            acting.contains(concat!(
                "  await invoke(\"scm_pull\");\n",
                "  upstreamState = await invoke(\"upstream_status\");\n",
            )),
            "the diverged case no longer pulls before it pushes:\n{acting}"
        );
        let saying = block_after(window, "function scmActionLabel(action, status) {");
        for state in [
            "sourceControl.publish",
            "sourceControl.sync",
            "sourceControl.pull",
            "sourceControl.push",
            "sourceControl.forcePush",
            "sourceControl.upToDate",
        ] {
            assert!(
                saying.contains(state),
                "the button lost its {state} state:\n{saying}"
            );
        }
        // The standing no longer has a row of its own: it is the remote half
        // of ONE primary button under the message box, Orca's commit area
        // (`resolveSourceControlPrimaryActionDecision` + the `[Primary][∨]`
        // pair the live panel measures at 286+28px).
        assert!(
            markup.contains(r#"<button class="btn btn--primary scm-primary" id="scm-primary""#)
                && markup.contains(
                    r#"<button class="btn btn--primary scm-primary-more" id="scm-primary-more""#
                ),
            "the primary action pair is gone from the commit box"
        );
        let table = block_after(window, "function scmPrimaryDecision() {");
        assert!(
            table.contains("const standing = scmPrimaryAction(upstreamState);"),
            "the primary button stopped reading the standing through the one \
             decision function:\n{table}"
        );
    }

    /// The section heads' bulk hands, the row's discard, and the status cap —
    /// Orca's measured argv end to end, with the panel's only destructive
    /// verbs standing behind one confirmation dialog.
    ///
    /// The argv are `discardChanges`/`cleanUntrackedPaths`'s own (out/main/
    /// index.js of 1.4.180): `restore --worktree --source=HEAD` — the
    /// `--source` spelled out because a bare `restore` reads from the INDEX,
    /// and a staged-then-edited file would "discard" to a half nobody was
    /// shown — and `clean -ffdx`, which cannot touch a tracked file at all.
    /// The cap is `DEFAULT_GIT_STATUS_LIMIT = 1e3` judged in Rust, so the
    /// banner's sentence quotes the number this side actually cut at.
    #[test]
    fn the_bulk_hands_speak_gits_own_verbs_and_only_through_the_dialog() {
        let backend = shipped_backend();
        let (shipped, _) = backend.split_once("#[cfg(test)]").unwrap_or((backend, ""));
        let verbs = include_str!("../../../zerocode-orchestrator/src/lib.rs");
        let window = window_source();
        let markup = include_str!("../../../../ui/index.html");

        for command in [
            "\n            stage_paths,\n",
            "\n            unstage_paths,\n",
            "\n            discard_paths,\n",
            "\n            delete_untracked,\n",
        ] {
            assert!(
                shipped.contains(command),
                "a bulk command fell out of the window's registration:{command}"
            );
        }
        assert!(
            verbs.contains(r#"&["restore", "--worktree", "--source=HEAD", "--"]"#),
            "the discard stopped restoring from HEAD — a staged-then-edited \
             file now \"discards\" to its staged half"
        );
        assert!(
            verbs.contains(r#"&["clean", "-ffdx", "--"]"#),
            "the untracked delete lost Orca's clean argv"
        );

        // The cap is the backend's judgement, quoted — never re-decided or
        // hardcoded in the window.
        assert!(
            shipped.contains("const SCM_STATUS_LIMIT: usize = 1_000;"),
            "the status cap lost its one named constant"
        );
        let status = block_after(shipped, "fn scm_status(");
        assert!(
            status.contains("changed.truncate(SCM_STATUS_LIMIT)")
                && status.contains(
                    "let capped = !uncapped.unwrap_or(false) && total > SCM_STATUS_LIMIT;"
                ),
            "the cap stopped being judged per answer with an uncapped \
             retry:\n{status}"
        );
        assert!(
            markup.contains(r#"<div class="scm-capped" id="scm-capped" role="status" hidden>"#),
            "the capped banner is gone from the panel"
        );

        // Every destructive invoke lives inside the dialog's confirm — the
        // hands and the heads open the dialog, never the verb.
        let confirming = block_after(
            window,
            r#"el("scm-discard-go").addEventListener("click", () => {"#,
        );
        for verb in ["invoke(\"discard_paths\"", "invoke(\"delete_untracked\""] {
            assert_eq!(
                window.matches(verb).count(),
                confirming.matches(verb).count(),
                "{verb} is invoked outside the confirmation dialog"
            );
            assert!(
                confirming.matches(verb).count() > 0,
                "the dialog's confirm no longer runs {verb}:\n{confirming}"
            );
        }
        // The staged discard-all walks unstage THEN discard, splitting by
        // what git now says — Orca's `runDiscardAllForArea("staged")` order.
        assert!(
            confirming.contains(r#"await invoke("unstage_paths", { paths: ask.paths });"#)
                && confirming.contains(r#"const after = await invoke("scm_status", {});"#),
            "the staged discard no longer unstages first and re-reads the \
             split:\n{confirming}"
        );
        // The row's hands ask before they act.
        let row = block_after(window, "function scmRow(");
        assert!(
            row.contains(r#"openScmDiscard({ kind: "entry", entry, group })"#),
            "a row's discard stopped passing through the dialog:\n{row}"
        );
    }

    /// The bulk roads ride chunks of a hundred, and the discard classifies
    /// at the last moment — the map's P0-18: Orca's `BULK_CHUNK_SIZE`
    /// (git.ts), `bulkDiscardChanges` (status.ts:2242-2295) and
    /// `git-discard-path-safety.ts`, whole.
    ///
    /// The chunking is load-bearing: one command line over a few thousand
    /// generated files is an `E2BIG` from the kernel, and the panel's
    /// biggest button fails exactly when it is most needed. The discard asks
    /// `ls-files` which paths are tracked AT DISCARD TIME — the panel's rows
    /// are a snapshot — and the untracked half is realpath-fenced before AND
    /// after the tracked restore, because the restore itself can lay down
    /// new links (`beforeRemove`'s second look).
    #[test]
    fn the_bulk_roads_ride_chunks_and_the_discard_asks_git_at_the_last_moment() {
        let backend = shipped_backend();
        let (shipped, _) = backend.split_once("#[cfg(test)]").unwrap_or((backend, ""));
        let verbs = include_str!("../../../zerocode-orchestrator/src/lib.rs");

        assert!(
            verbs.contains("const BULK_CHUNK: usize = 100;")
                && verbs.contains("for chunk in paths.chunks(BULK_CHUNK)"),
            "the bulk roads lost Orca's hundred-path chunking — a big stage \
             is an E2BIG again"
        );
        assert!(
            verbs.contains(r#"OsString::from(":(literal)")"#),
            "pathspecs stopped being literal — a `*` in a filename globs again"
        );

        // Both window verbs walk the ONE classified road; the panel's own
        // tracked/untracked split is advisory, never load-bearing.
        for door in ["fn discard_paths(", "fn delete_untracked("] {
            assert!(
                block_after(shipped, door).contains("discard_by_git_truth(state, paths)"),
                "{door} left the classified road"
            );
        }
        let road = block_after(verbs, "pub fn discard_changes(");
        assert!(
            road.contains("self.tracked_paths_of(worktree, paths)?"),
            "the discard stopped asking ls-files and trusts a painted snapshot"
        );
        assert_eq!(
            road.matches("validate_untracked_discard_target(worktree, Path::new(path.as_str()))?")
                .count(),
            2,
            "the untracked fence no longer stands both before and after the \
             tracked restore"
        );
    }

    /// A rebased branch is offered a force push — with a lease, and only when
    /// the remote holds nothing but older copies of the same work.
    ///
    /// Orca's force path (1-부 §2, §7): the flag is BARE `--force-with-lease`
    /// inserted between `push` and `--set-upstream`, never the `=<ref>` form —
    /// the lease's baseline is git's own default (the remote-tracking ref as
    /// of the last fetch), and computing an expected OID here would replace
    /// the one check that makes this safe with our own guess about it. The
    /// promotion is gated on `--cherry-mark` saying every upstream-only commit
    /// is patch-identical to one of mine, and that walk is paid for ONLY when
    /// the branch is both ahead and behind. A refusal fetches and re-reads the
    /// standing, which is what re-arms the lease and what flips the button
    /// between Force Push and Sync.
    #[test]
    fn a_force_push_is_leased_gated_on_patch_equivalence_and_re_judged_after_a_refusal() {
        let backend = shipped_backend();
        let (shipped, _) = backend.split_once("#[cfg(test)]").unwrap_or((backend, ""));
        let window = window_source();
        let markup = include_str!("../../../../ui/index.html");

        assert!(
            shipped.contains("\n            scm_fetch,\n"),
            "the fetch that re-arms the lease is not registered"
        );

        // The flag is conditional, bare, and in Orca's own position.
        let pushing = block_after(shipped, "fn scm_push(");
        assert!(
            pushing.contains(concat!(
                "        let mut args = vec![\"push\"];\n",
                "        if force_with_lease {\n",
                "            args.push(\"--force-with-lease\");\n",
                "        }\n",
                "        args.extend_from_slice(&[\"--set-upstream\", \"origin\", \"HEAD\"]);\n",
            )),
            "the lease flag is no longer inserted conditionally between `push` \
             and `--set-upstream`:\n{pushing}"
        );
        assert!(
            !shipped.contains("--force-with-lease="),
            "an `=<ref>` lease appeared — the baseline stopped being git's own \
             remote-tracking ref and became something this window computed"
        );
        assert!(
            !shipped.contains("\"--force\"]") && !shipped.contains("\"--force\","),
            "a bare `--force` reached the push argv, which has no lease at all"
        );

        // The cherry-mark walk is paid for only where its answer can matter.
        let standing = block_after(shipped, "fn upstream_status(");
        assert!(
            standing.contains(
                "let behind_commits_are_patch_equivalent = (ahead > 0 && behind > 0).then(|| {"
            ),
            "the patch-equivalence walk is no longer gated on a diverged \
             branch:\n{standing}"
        );
        // 들여쓰기 한 단이 깊어진 것은 이 읽기가 호스트 경계를 지나가게 되었기
        // 때문이다(`host.vcs().text(`). 붙잡는 것은 그대로다 — 여섯 인자 하나의
        // cherry-mark 목록.
        assert!(
            standing.contains(concat!(
                "                    \"log\",\n",
                "                    \"--oneline\",\n",
                "                    \"--cherry-mark\",\n",
                "                    \"--right-only\",\n",
                "                    &range,\n",
                "                    \"--\",\n",
            )),
            "the equivalence answer no longer comes from one cherry-mark \
             listing:\n{standing}"
        );

        // The window promotes only on the measured `true`, never on a `null`
        // the backend never asked about.
        let promoting = block_after(window, "function shouldForcePushWithLease(status) {");
        assert!(
            promoting.contains("status.behind_commits_are_patch_equivalent === true"),
            "the promotion stopped requiring a measured equivalence:\n{promoting}"
        );
        let deciding = block_after(window, "function scmPrimaryAction(status) {");
        assert!(
            deciding.contains(
                "if (ahead > 0 && behind > 0) return shouldForcePushWithLease(status) \
                 ? \"force_push\" : \"sync\";"
            ),
            "a diverged branch no longer chooses between force push and \
             sync:\n{deciding}"
        );

        // The loop: a rejected or stale-lease refusal fetches and re-reads.
        // `runScmRemote` is the one road every network verb takes — the
        // primary button and the menu alike — so the loop cannot be bypassed
        // by whichever surface asked.
        let clicking = block_after(window, "async function runScmRemote(action) {");
        assert!(
            clicking.contains(concat!(
                "    if (kind === \"rejected\" || kind === \"stale-lease\") {\n",
                "      await invoke(\"scm_fetch\").catch(() => {});\n",
                "      await refreshUpstream();\n",
            )),
            "a refused push no longer re-fetches and re-judges, so the button \
             cannot promote or demote itself:\n{clicking}"
        );
        assert!(
            markup.contains(
                r#"<p class="scm-sync-error" id="scm-sync-error" role="alert" aria-live="polite" hidden></p>"#
            ),
            "the inline refusal line is gone from the panel"
        );
        // No confirmation dialog: Orca has none, and the safety is the
        // equivalence gate plus the lease plus the tooltip.
        let titling = block_after(window, "function scmActionTitle(action, status) {");
        assert!(
            titling.contains("sourceControl.forcePushTitle"),
            "the force push lost the tooltip that is its only warning:\n{titling}"
        );
    }

    /// The window can be held by its head — dragged, and double-clicked to
    /// zoom — from every passive stretch of the titlebar.
    ///
    /// Tauri starts a drag (and toggles maximize on a double click) only when
    /// the mousedown's TARGET carries `data-tauri-drag-region`; the attribute
    /// does not inherit. The header had it, but its children — wordmark,
    /// project name, nav, tab strip, right cluster — covered the surface, so
    /// the visible titlebar was a handle almost nowhere ("해드 잡고 클릭2번하면
    /// 커지고 작아지고 그리고 위에 집고 움직이고"). The attribute now rides
    /// every passive element; buttons and tabs stay without it, which is what
    /// keeps a tab a tab and not a handle.
    #[test]
    fn the_titlebar_is_a_handle_everywhere_it_is_not_a_control() {
        let markup = include_str!("../../../../ui/index.html");
        // Our OWN marker, not `data-tauri-drag-region`: that name is also read
        // by the webview's built-in handler, and two owners of one gesture —
        // each with its own double-click logic — is how the drag worked on
        // some presses and not others. One name, one listener.
        for handle in [
            r#"<header class="titlebar" data-drag-surface>"#,
            r#"<span class="wordmark" id="titlebar-app-name" data-drag-surface>"#,
            r#"<span class="project" id="project" data-drag-surface>"#,
            r#"<span class="branch" id="branch" data-drag-surface hidden>"#,
            r#"<div class="titlebar-nav" data-drag-surface>"#,
            r#"<div class="titlebar-right" data-drag-surface>"#,
        ] {
            assert!(
                markup.contains(handle),
                "a passive stretch of the titlebar stopped being a handle: {handle}"
            );
        }
        assert!(
            markup.contains(
                r#"<div class="tabstrip" id="tabstrip" role="tablist" data-drag-surface"#
            ),
            "the empty run of the tab strip stopped being a handle"
        );
        assert!(
            !markup.contains("data-tauri-drag-region"),
            "the built-in drag marker is back, so the gesture has two owners again"
        );
        // And the listener that owns the gesture keeps its own clock: the OS
        // eats the mouseup of every window drag, so the browser's click count
        // calls the NEXT press a double-click and a detail-based branch sends
        // every retry to maximize — "처음에는 돼는데 그다음 안돼".
        let window = window_source();
        let gripping = block_after(window, "let gripPressedAt = 0;");
        assert!(
            gripping.contains(r#"closest?.("[data-drag-surface]")"#)
                && gripping.contains("now - gripPressedAt < 350")
                && gripping.contains("pressBesideControl(grip, event.clientX, event.clientY)")
                && gripping.contains("kept from drag")
                && gripping.contains(
                    r#"event.target.closest("button, [role=\"tab\"], input, select, a")"#
                )
                && !gripping.contains("event.detail"),
            "the titlebar drag trusts the browser's click counter or steals a control's press:\n{gripping}"
        );
        let miss = block_after(window, "function pressBesideControl(grip, x, y) {");
        assert!(
            miss.contains("grip.id !== \"tabstrip\"")
                && miss.contains("GRIP_MISS_SLOP")
                && miss.contains("getBoundingClientRect()"),
            "the tab strip no longer keeps near-control misses out of the OS drag road:\n{miss}"
        );
        let adding = block_after(window, "function addTabButton(pane, group) {");
        assert!(
            adding.contains("const summon = (road) => {")
                && adding.contains("add.addEventListener(\"pointerdown\"")
                && adding.contains("event.preventDefault();")
                && adding.contains("event.stopPropagation();")
                && adding.contains("if (event.detail > 0) return;")
                && adding.contains("summon(\"keyboard\")"),
            "the plus waits for a click macOS may swallow, or pointer and keyboard have separate owners:\n{adding}"
        );
        let terminal = block_after(window, "function makeTermView(");
        assert!(
            terminal.contains("let paintPaused = false;")
                && terminal.contains("const painting = !host.hidden && !paintPaused;")
                && terminal.contains("function setPaintPaused(paused) {")
                && terminal.contains("if (!paintPaused && !host.hidden) repaint();"),
            "streaming frames still repaint beneath a top-layer control, or resume loses the banked rows:\n{terminal}"
        );
        let closing_palette = block_after(window, "function closeTabCreate(road = \"code\") {");
        assert!(
            closing_palette.contains("setTabCreateTerminalPaintPaused(false)")
                && block_after(window, "function openTabCreate(button, road = \"open\") {")
                    .contains("setTabCreateTerminalPaintPaused(true);"),
            "the create palette no longer owns and releases the terminal paint gate:\n{closing_palette}"
        );
        // And the door is actually open. `core:window:default` does NOT
        // include start-dragging or the maximize toggle — the invoke was
        // refused for as long as the capability said only `core:default`,
        // which is why the handle never worked no matter what the listener
        // did. A capability regression here is invisible in every test that
        // stubs invoke, so the file itself is the assertion.
        let capability = include_str!("../../capabilities/default.json");
        assert!(
            capability.contains("core:window:allow-start-dragging")
                && capability.contains("core:window:allow-internal-toggle-maximize"),
            "the titlebar's two verbs lost their permission — the listener \
             will call and be refused:\n{capability}"
        );
    }

    /// The wheel scrolls a terminal — history on the primary screen, arrows
    /// on the alternate one.
    ///
    /// Until this slice the wheel only spoke to a program that was tracking
    /// the mouse; at an ordinary prompt it did nothing at all ("터미널에서
    /// 스크롤링도 안됨"). The grid has held a scrollback all along — it was
    /// only ever read for session replay. Now the view can stand in it:
    /// scrolled frames go out `full` (the shift contract only knows the live
    /// screen), the caret is withheld, new output deepens the offset so the
    /// content under the reader stays put, and typing snaps back to live.
    /// On the alternate screen there is no history, so the wheel falls back
    /// to arrow keys — xterm's own rule, and what makes a wheel work in a
    /// pager or an agent TUI that never asked for the mouse.
    #[test]
    fn the_wheel_scrolls_history_and_typing_snaps_back_to_live() {
        let backend = shipped_backend();
        let (shipped, _) = backend.split_once("#[cfg(test)]").unwrap_or((backend, ""));
        let window = window_source();

        // The command is registered, and it splits on the screen in charge.
        assert!(
            shipped.contains("\n            term_scroll,\n"),
            "term_scroll is not registered with the window"
        );
        let scrolling = block_after(shipped, "fn term_scroll(");
        assert!(
            scrolling.contains("if pty.terminal().grid().alt_screen() {"),
            "the alternate screen no longer gets the arrow-key fallback:\n{scrolling}"
        );
        assert!(
            scrolling.contains("for _ in 0..lines.unsigned_abs().min(40) {"),
            "an inertial flick can type unbounded arrows into a TUI:\n{scrolling}"
        );
        assert!(
            scrolling.contains(".scroll_view(isize::try_from(lines).unwrap_or(0));"),
            "the primary screen no longer reaches the grid's view:\n{scrolling}"
        );

        // Typing is aimed at the program, and the program is at the bottom —
        // every road bytes travel in snaps the view back first.
        for door in ["fn term_key(", "fn write_terminal_text(", "fn term_paste("] {
            let body = block_after(shipped, door);
            assert!(
                body.contains("pty.terminal_mut().grid_mut().view_to_bottom();"),
                "{door} writes into a shell whose view is still in history"
            );
        }
        assert!(
            block_after(shipped, "fn term_text(")
                .contains("write_terminal_text(&state, term, &text)?;"),
            "the shared text command bypasses the snap-to-live writer"
        );

        // The wheel's other half: ONE conversion of pixels to whole rows,
        // above the fork, spent on whichever road takes the notch —
        // accumulated, because a trackpad speaks in single pixels and "at
        // least one line per event" turns a slow drag into a sprint, and
        // because a gesture measured differently on the two roads moved this
        // terminal's history six rows and the TUI inside it one.
        let wheeling = block_after(window, r#"host.addEventListener("wheel", (event) => {"#);
        assert!(
            wheeling.contains(concat!(
                "    const address = owner.address();\n",
                "    if (address === null) return;\n",
                "    event.preventDefault();\n",
            )) && wheeling.contains(concat!(
                "    const pixels = event.deltaMode === 1 ? event.deltaY * cell.height : event.deltaY;\n",
                "    wheelHeld += pixels * sensitivity;\n",
                "    const steps = Math.trunc(wheelHeld / cell.height);\n",
                "    if (steps === 0) return;\n",
                "    wheelHeld -= steps * cell.height;\n",
            )),
            "the wheel stopped converting pixels to whole rows once, for both roads:\n{wheeling}"
        );
        // Sensitivity multiplies the PIXELS, above the accumulator. Scaling
        // the whole rows afterwards instead would quantise every notch to a
        // multiple of five on the fast road and make a trackpad unusable —
        // and it is the accumulator, not the notch, that makes sub-row travel
        // survive.
        assert!(
            wheeling.contains("    const tuiOwnsWheel = !event.shiftKey && programHasMouse();\n")
                && wheeling.contains("    const sensitivity = tuiOwnsWheel\n")
                && wheeling.contains("      ? termPrefs.tui_scroll_sensitivity\n")
                && wheeling.contains(concat!(
                    "      : termPrefs.sensitivity * (event.altKey ",
                    "? termPrefs.fast_scroll_sensitivity : 1);\n",
                )),
            "the wheel stopped scaling its pixels before banking them:\n{wheeling}"
        );
        // Mouse-tracking still has right of way, now spending the same rows —
        // and shift is withheld from it, which is the only way to reach this
        // terminal's own scrolling while a full-screen TUI owns the pointer
        // (xterm.js `_consumeWheelEvent` answers 0 for `shiftKey`).
        assert!(
            wheeling.contains("    if (tuiOwnsWheel) {\n")
                && wheeling.contains(
                    r#"        if (!report(event, "press", steps < 0 ? 64 : 65)) break;"#
                ),
            "the mouse-tracking road lost its right of way, or its shift bypass:\n{wheeling}"
        );
        // Through the flight — one command per painted frame, never one per
        // DOM event: a trackpad fling speaks a hundred times a second, and
        // each crossing used to take the terminals lock against the pump
        // that was painting the very frames the scroll asked for (스크롤
        // 잔랙). The flush itself is pinned beside the scrollbar's gates,
        // where the drag's place-not-distance rule lives; here the wheel
        // banks.
        assert!(
            wheeling.contains("    scrollTo(-steps);"),
            "the wheel no longer banks whole rows into the scroll flight:\n{wheeling}"
        );
        // And the arrow fallback is for a program that never asked for the
        // mouse. One that IS tracking gets silence instead: it has already
        // said how it wants the wheel, and arrows it never pressed would walk
        // its composer's history (measured on `claude`).
        for road in [
            block_after(shipped, "fn term_scroll("),
            block_after(shipped, "fn lane_scroll("),
        ] {
            assert!(
                road.contains("MouseTracking::Off"),
                "the arrow fallback types at a program that is tracking the mouse:\n{road}"
            );
        }

        // The lane road carries the same two rules: the alternate screen's
        // arrow fallback with its cap, and history through the registry.
        assert!(
            shipped.contains("\n            lane_scroll,\n"),
            "lane_scroll is not registered with the window"
        );
        let lane_road = block_after(shipped, "fn lane_scroll(");
        assert!(
            lane_road.contains("if registry.alt_screen(id) == Some(true) {")
                && lane_road.contains("for _ in 0..lines.unsigned_abs().min(40) {")
                && lane_road.contains(".scroll_view(id, isize::try_from(lines).unwrap_or(0))"),
            "the lane road lost one of the wheel's rules:\n{lane_road}"
        );
        // And typing snaps a lane back to live INSIDE the registry's one
        // write door — pinned there because a door added later cannot be
        // trusted to remember what every caller must do.
        let registry = include_str!("../../../zerocode-lane/src/registry.rs");
        let writing = block_after(registry, "pub fn write_input(");
        assert!(
            writing.contains("entry.pty.terminal_mut().grid_mut().view_to_bottom();"),
            "a lane keeps reading history while the person types into it:\n{writing}"
        );
    }

    /// A repaint leaves what it did not change, and a copy leaves the padding.
    ///
    /// Both halves of "출력 중에는 텍스트를 선택할 수 없다", which was the most-felt
    /// gap on this surface. A native selection is anchored to DOM nodes, and
    /// `paintRow` opened with `replaceChildren()` — so every frame an agent
    /// streamed tore the selection out from under the pointer. Orca is not
    /// affected because xterm selects in BUFFER coordinates; a cell-coordinate
    /// selection layer is the real answer and is not this slice. Painting by
    /// difference is the other half and most of the relief: a frame that
    /// rewrites one run of one row leaves every other span standing, and a
    /// selection survives everything that did not touch the exact run it is in.
    ///
    /// The copy is the other complaint: a grid row is full width and its unused
    /// cells hold spaces, so pasting one line of output brought ninety columns
    /// of trailing blank with it. xterm trims on copy for the same reason.
    #[test]
    fn a_repaint_leaves_the_runs_it_did_not_change() {
        let window = window_source();

        // The tell: no wholesale teardown at the top of a row's paint.
        let painting = nested_block(window, "  function paintRow(index) {");
        assert!(
            !painting.contains("node.replaceChildren();"),
            "paintRow tears its row down again — a selection cannot survive that:\n{painting}"
        );
        assert!(
            painting.contains("if (span !== undefined && was !== undefined && was[at] !== undefined && sameRun(was[at], runs[at])) {")
                && painting.contains("        continue;"),
            "paintRow stopped skipping runs that did not change:\n{painting}"
        );
        // Even an identical string replaces the Text node it is assigned to,
        // which takes the selection with it — so the skip has to come BEFORE
        // any write, not merely avoid a visible difference.
        assert!(
            painting.contains("      dressRun(span, runs[at], was?.[at]);"),
            "a changed run is no longer written in place — or is written \
             without being told what the span already wears, which is what \
             decides how little has to be said to it:\n{painting}"
        );
        let dressing = nested_block(window, "  function dressRun(span, run, was) {");
        assert!(
            dressing.contains("else span.firstChild.data = run.text;")
                && dressing.contains("if (span.firstChild === null)"),
            "a changed run replaces its Text node instead of updating it in \
             place, so WebKit retains the discarded node and a selection \
             loses its anchor:\n{dressing}"
        );
        let coloring = block_after(window, "function finiteColorClass(");
        let styles = include_str!("../../../../ui/shell.css");
        assert!(
            coloring.contains("if (color?.rgb)")
                && coloring.contains("`term-${role}-${color.indexed}`")
                && styles.contains(".term .term-fg-0")
                && styles.contains(".term .term-bg-255")
                && dressing.contains("if (run.fg) span.style.color = run.fg;")
                && !dressing.contains("span.style.letterSpacing"),
            "a finite terminal colour or wide-glyph correction became an \
             inline span value again; only a true 24-bit run may take that \
             road:\n{coloring}\n{dressing}"
        );

        // The memory of what each row says has to be dropped everywhere the
        // DOM it describes is dropped, or the next frame skips runs whose
        // spans no longer exist and the row comes out blank.
        let shifting = nested_block(window, "  function shiftNodes(count) {");
        assert!(
            shifting.contains("const remembered = painted.shift();")
                && shifting.contains("painted.push(remembered);")
                && !shifting.contains("node.replaceChildren();"),
            "a shifted row discards spans instead of rotating their dress \
             memory with them:\n{shifting}"
        );
        // The model's row count follows the frame (`setSize`); the DOM's, and
        // the memory that describes it, follow at the paint.
        let sizing = nested_block(window, "  function followRowCount() {");
        assert!(
            sizing.contains("      painted.pop();")
                && sizing.contains("      painted.push(undefined);"),
            "a resize leaves the painted memory out of step with the rows:\n{sizing}"
        );

        // Trailing blank goes on copy — and only trailing. Interior spacing is
        // a program's own alignment (a table, a tree, a diff gutter) and
        // trimming it would destroy the thing being copied. The rule lives
        // with the cells, on the backend: the window's selection is a grid
        // model and the text it names is asked for from there (t-3242).
        let between = block_after(
            include_str!("../../../zerocode-pty/src/grid.rs"),
            "pub fn text_between(",
        );
        assert!(
            between.contains("let kept = text.trim_end().len();")
                && between.contains("text.truncate(kept);")
                && between.contains("if cell.is_continuation() {")
                && between.contains("if self.fold_hidden(self.fold_at(line)) {"),
            "a copied line brings the grid's padding with it, or a wide glyph twice, \
             or a folded body:\n{between}"
        );
        // And the window's three copy roads — ⌘C, the copy event, the pane
        // menu — all ask by the terminal's own address key, so a selection
        // standing in another screen is never this one's to copy.
        let selecting = block_after(window, "function terminalSelectionView(key) {");
        assert!(
            selecting.contains("view.selectionStands() && view.addressKey() === key"),
            "the terminal's copy rule accepts a selection owned by another surface:\n{selecting}"
        );
        let copying = block_after(window, r#"document.addEventListener("copy", (event) => {"#);
        assert!(
            copying.contains("terminalSelectionView(terminalTargetKey(keyboardTarget()))")
                && copying.contains("event.preventDefault();")
                && copying.contains("view.selectionText().then((text) => text !== \"\" && clipboardText.write(text))"),
            "the copy event stopped using the owned selection and the clipboard adapter:\n{copying}"
        );
    }

    /// A bell reaches the strip, and only from a tab nobody is looking at.
    ///
    /// The grid swallowed `BEL` ("BEL and everything else: swallowed"), so a
    /// background shell had no way to say a build had finished or that a prompt
    /// was waiting — the only way to find out was to click every tab. Orca
    /// marks the tab and debounces off the same signal (`onBell`, :20591).
    ///
    /// The mark, not a notification: a program can ring the bell in a loop, and
    /// this window's OS-notification road has its own rules about interrupting.
    /// What a bell earns is the dot the strip already uses to say "this one
    /// wants you", which is the same sentence.
    #[test]
    fn a_bell_reaches_the_tab_that_rang_it() {
        let grid = include_str!("../../../zerocode-pty/src/grid.rs");
        let window = window_source();
        let styles = strip_comments(include_str!("../../../../ui/shell.css"));

        // Raised where it used to be swallowed, and `dirty` is deliberately
        // NOT set with it: nothing about the screen changed.
        // And raised on BOTH cursors: the frame's, and the one the pump
        // announces from every round whether or not a screen pulls.
        assert!(
            grid.contains(
                "            0x07 => {\n                self.bell = true;\n                self.announce_bell = true;\n            }"
            ),
            "BEL is swallowed again — a background tab has nothing to say with"
        );
        assert!(
            grid.contains("    pub bell: bool,"),
            "the delta stopped carrying the bell"
        );
        // Its own reason to send a frame. The case this exists for is a build
        // that finishes without printing, and on a still screen nothing else
        // would rise.
        let taking = block_after(
            grid,
            "    pub fn take_delta(&mut self) -> Option<GridDelta> {",
        );
        assert!(
            taking.contains("            || self.bell"),
            "a bell rung into a still screen waits for an unrelated change:\n{taking}"
        );
        assert!(
            taking.contains("        let news = self.take_news_unchecked();"),
            "a delta bypasses the one-shot news drain:\n{taking}"
        );
        let draining = block_after(grid, "    fn take_news_unchecked(&mut self) -> GridNews {");
        assert!(
            draining.contains("        self.bell = false;"),
            "the bell is never cleared — it would ring on every later frame:\n{draining}"
        );
        // A snapshot cannot clear the flag, so it must not carry it: a reattach
        // showing an old screen is not the moment to announce an old bell.
        let snapping = block_after(grid, "    pub fn snapshot(&self) -> GridDelta {");
        assert!(
            snapping.contains("            bell: false,"),
            "a snapshot rings a bell it cannot clear:\n{snapping}"
        );

        // The window marks the tab, debounced, and never the one in front of
        // somebody who is here to hear it.
        assert!(
            window.contains("const BELL_DEBOUNCE_MS = 250;"),
            "the bell lost Orca's debounce — a program can ring it per line"
        );
        let noting = block_after(window, "function noteBell(term) {");
        assert!(
            noting.contains("  if (tab.id === activeTabId && document.hasFocus()) return;"),
            "a bell badges the very tab being read, and would never clear:\n{noting}"
        );
        assert!(
            noting.contains("  }, BELL_DEBOUNCE_MS);"),
            "the bell renders the strip once per ring:\n{noting}"
        );
        // Looking at the tab is the answer to its bell, and acknowledgement is
        // the one door every "seen" road already walks through.
        let acking = block_after(window, "function acknowledgeTab(tab) {");
        assert!(
            acking.contains("    bellRang.delete(term);"),
            "a bell outlives being looked at:\n{acking}"
        );
        assert!(
            styles.contains(".tab.is-bell .tab-dot,"),
            "the bell has no mark on the strip"
        );
    }

    /// The frame carries where the view is, so a scrollbar can exist (1-en).
    ///
    /// This terminal had no scrollbar and the reason was structural, not
    /// cosmetic: `.term` is `overflow: hidden` and the history lives in Rust,
    /// so the window could ASK for a scroll and never see where it landed.
    /// Two fields on the frame are the whole of it — and they must ride the
    /// frame that already goes out rather than becoming a question the window
    /// asks, or a scrollbar costs a round trip per paint.
    #[test]
    fn the_frame_says_where_the_view_is_so_a_scrollbar_can_be_drawn() {
        let grid = include_str!("../../../zerocode-pty/src/grid.rs");
        let window = window_source();
        let styles = strip_comments(include_str!("../../../../ui/shell.css"));

        for field in [
            "    pub view_offset: usize,",
            "    pub scrollback_len: usize,",
        ] {
            assert!(
                grid.contains(field),
                "the delta stopped carrying the scrollbar's numbers: {field}"
            );
        }
        // Compared, not flagged — history grows and shrinks from several
        // places, and a flag at each site is a flag the next site forgets.
        let taking = block_after(
            grid,
            "    pub fn take_delta(&mut self) -> Option<GridDelta> {",
        );
        assert!(
            taking.contains("|| (self.view_offset, self.scrollback.len()) != self.taken_view"),
            "a scrollbar number can change without the window hearing:\n{taking}"
        );
        // A snapshot carries them: they are state, not news, and a window
        // rebuilding from a reattach has to draw the bar it is reattaching to.
        let snapping = block_after(grid, "    pub fn snapshot(&self) -> GridDelta {");
        assert!(
            snapping.contains("            view_offset: self.view_offset,"),
            "a reattached screen draws no scrollbar:\n{snapping}"
        );

        // The window reads them BEFORE it paints: `paintRow` decides which
        // hits and which links belong to a row from where the view is, so a
        // row painted against the previous frame's position highlights the
        // line that used to be there.
        // Taken into the model with the frame (`update`), which every paint
        // follows.
        let updating = nested_block(window, "  function update(delta) {");
        assert!(
            updating.contains("    viewOffset = delta.view_offset ?? 0;")
                && updating.contains("    viewTop = scrollbackLen - viewOffset;"),
            "the view's position is read after the paint, or not at all:\n{updating}"
        );
        // `?? 0` and not a bare read: the fields are an extension, and a frame
        // without them means "live screen, no history" — which is what the
        // board's replayed snapshots are.
        assert!(
            updating.contains("delta.scrollback_len ?? 0"),
            "a frame from before the extension stops painting:\n{updating}"
        );

        // Dragging spends the one road that already exists, in lines — as a
        // PLACE, not a distance: the moves between two frames used to re-send
        // the same distance against a stale offset and the view rubber-banded
        // (스크롤 잔랙). The flight converts once per frame, at flush time.
        assert!(
            window.contains("    scrollToOffset(clamped);"),
            "the thumb drag stopped naming a place through the scroll flight"
        );
        assert!(
            window.contains("    scrollToOffset(0);"),
            "the way back to live stopped being one move to zero"
        );
        let flushing = nested_block(window, "  function flushScroll() {");
        assert!(
            flushing.contains("lines += pendingOffset - viewOffset;")
                && flushing.contains("invoke(\"term_scroll\", { term: address.term, lines })")
                && flushing.contains("invoke(\"lane_scroll\", { id: address.id, lines })"),
            "the flight no longer settles a named place against the freshest \
             offset on the one scroll road:\n{flushing}"
        );
        // Orca's own width, and out of flow — `gridSize` sizes the pty from
        // the host minus its padding, so anything in the flow would be counted
        // as screen and the bottom row would sit behind it.
        assert!(
            include_str!("../../../../ui/tokens.css").contains("--term-scrollbar-size: 7px;"),
            "the terminal scrollbar drifted off Orca's measured width"
        );
        let rail = block_after(&styles, ".term-rail {");
        assert!(
            rail.contains("position: absolute;"),
            "the scrollbar joined the flow and is now stealing a row:\n{rail}"
        );
    }

    /// ⌘F reaches a terminal, and the search happens where the history is.
    ///
    /// ⌘F used to return immediately unless the tab was a file, so in a
    /// terminal the key everybody presses did nothing — worse than an absent
    /// feature, because silence reads as broken. And the search cannot be done
    /// in the window at all: it holds the rows it is PAINTING and nothing
    /// else, while the line somebody wants is almost never on screen.
    #[test]
    fn the_terminal_can_be_searched_where_its_history_actually_is() {
        let backend = shipped_backend();
        let (shipped, _) = backend.split_once("#[cfg(test)]").unwrap_or((backend, ""));
        let window = window_source();

        for command in ["term_search", "term_view_to_line"] {
            assert!(
                shipped.contains(&format!("\n            {command},\n")),
                "{command} is not registered with the window"
            );
        }
        assert!(
            shipped.contains("keyboard_input_source::terminal_keyboard_layout,"),
            "Option as Alt lost its native macOS input-source authority"
        );
        // Bounded. `e` across a 50,000-line scrollback is a stall, and the
        // answer past the first few hundred is not one anybody reads.
        let searching = block_after(shipped, "fn term_search(");
        assert!(
            searching.contains("TERM_SEARCH_MAX"),
            "a terminal search is unbounded:\n{searching}"
        );
        // The jump answers where it landed, so the thumb is right on the same
        // frame rather than one behind.
        let jumping = block_after(shipped, "fn term_view_to_line(");
        assert!(
            jumping.contains("view_to_line(line)"),
            "the jump stopped going through the grid's own clamping:\n{jumping}"
        );

        // ⌘F no longer walks away from a terminal.
        let opening = block_after(window, "function openFind() {");
        assert!(
            opening.contains("  const screen = termFindView();")
                && opening.contains("    screen.openFind();"),
            "⌘F is silence in a terminal again:\n{opening}"
        );
        // The ACTIVE pane's screen, not the tab's first: a split tab is
        // several shells and the one being read is the one to search.
        let picking = block_after(window, "function termFindView() {");
        assert!(
            picking.contains("termViews.get(activePaneOf(tab))"),
            "a split tab searches a pane nobody is looking at:\n{picking}"
        );
        // The bar is the file finder's, by class — one set of rules, not two.
        assert!(
            window.contains(r#"find.className = "file-find term-find";"#),
            "the terminal find bar stopped reusing the file finder's rules"
        );
        // Its keys are its own. Without this the query is also typed at the
        // prompt, because a terminal listens to the window's key sink.
        assert!(
            window.contains(r#"find.addEventListener("keydown", (event) => {"#)
                && window.contains("    event.stopPropagation();"),
            "the find bar's keys reach the shell behind it"
        );
    }

    /// A printed path or URL can be clicked — on every screen, and without
    /// costing the hot path.
    ///
    /// The scan is a regular expression over a row's text, affordable because
    /// `marksOf` is reached from `paintRow`, which runs for rows that CHANGED:
    /// an idle screen scans nothing. It used to be skipped on the alternate
    /// screen and under a mouse-tracking program, on the reasoning that such a
    /// link could not be clicked anyway — and the ordinary case disproved it:
    /// an agent TUI prints a localhost URL and that URL is what a person
    /// reaches for. So the link stays live and the ACTIVATING PRESS is kept
    /// from the child instead, which is Orca's own rule
    /// (terminal-link-pty-mouse-suppression.ts) and the contract pinned below.
    #[test]
    fn output_links_are_live_on_every_screen_and_scanned_only_where_it_is_free() {
        let window = window_source();
        let styles = strip_comments(include_str!("../../../../ui/shell.css"));

        // The cost guarantee is the CALLER, not a screen test: marks are built
        // for a row being painted.
        let painting = nested_block(window, "  function paintRow(index) {");
        assert!(
            painting.contains("marksOf(index, cells)"),
            "the link scan left the painted-row road, so it now costs rows \
             nobody drew:\n{painting}"
        );
        let marking = nested_block(window, "  function marksOf(index, cells) {");
        assert!(
            !marking.contains("altScreen") && !marking.contains("programHasMouse()"),
            "the link scan judges the screen again, so a URL inside an agent \
             TUI cannot be clicked:\n{marking}"
        );
        // A press that lands on a link is HELD, and forwarded to the program
        // only when the link road did not take the gesture — a press merely
        // swallowed would be a mouse-aware program silently missing drags.
        assert!(
            window.contains("    if (event.button === 0 && event.target?.closest?.(\"[data-href]\")) deferredMouse = [];")
                && window.contains("    if (deferredMouse !== null) deferredMouse.push(send);")
                && window.contains("      linkPressClaimed = true;"),
            "the link press is no longer held back from a tracking program, or \
             is never released to it"
        );
        let flushing = nested_block(window, "  function flushDeferredMouse() {");
        assert!(
            flushing.contains("if (held === null || claimed) return;")
                && flushing.contains("for (const one of held) one();"),
            "the held mouse reports are dropped even when the link road \
             refused the gesture:\n{flushing}"
        );
        // A hit wins where the two collide: a run cannot wear both treatments
        // without one of them being a lie.
        assert!(
            marking.contains("!marks.some((mark) => mark.from < to && from < mark.to)"),
            "a link and a search hit can claim the same columns:\n{marking}"
        );

        // The run cache has to compare the link too, or a span reused by
        // ordinary text stays clickable and points wherever it used to.
        let comparing = nested_block(window, "  function sameRun(a, b) {");
        assert!(
            comparing.contains("a.href === b.href"),
            "a reused span can keep a link it no longer has:\n{comparing}"
        );
        let dressing = nested_block(window, "  function dressRun(span, run, was) {");
        assert!(
            dressing.contains("        delete span.dataset.href;")
                && dressing.contains("        delete span.dataset.tip;"),
            "a run that is not a link stays clickable:\n{dressing}"
        );
        // The link is written and taken away under ONE question, because both
        // are answered by the same field: a span whose href is unchanged must
        // not be asked about its tooltip either — `delete` on a `dataset` key
        // is a DOM operation whether or not the attribute is there, and it was
        // being done twice for every run of every changed row.
        assert!(
            dressing.contains("    if (was === undefined || was.href !== run.href) {"),
            "the link is re-decided on runs whose link did not move:\n{dressing}"
        );

        // A bare click NEVER opens anything outright: on a URL it raises the
        // action popover, and only through the pointer gate — armed at
        // mousedown, spoiled by a four-pixel drag or a selection that stood
        // when the press landed (Orca's terminal-link-pointer-gesture).
        // Files stay ⌘-only, and a click the terminal does not own — mac
        // Ctrl+click, a lone Alt or Shift — is yielded to the system whole.
        assert!(
            window.contains("    if (!terminalOwnsLinkGesture(event)) return;")
                && window.contains("      if (!canRequestTermLinkAction(host)) return;")
                && window.contains("      const url = canonicalHttpLink(href);")
                && window.contains("      if (url === null) {")
                && window.contains(
                    "        openFileLinkMenu(href, event.clientX ?? 0, event.clientY ?? 0);"
                ),
            "a bare click in terminal output opens things, or steals selection"
        );
        // And the selection that gate asks about is THIS screen's. Orca asks
        // the terminal the gesture was installed on — `terminal.hasSelection()`,
        // per-screen because xterm owns its own selection
        // (terminal-link-pointer-gesture.ts:33,58). Asking the document instead
        // hands one selection left standing anywhere — a filename in the tree,
        // a line in a diff — the power to swallow every link click in every
        // terminal until somebody clears it, which is how it was reported.
        assert!(
            window.contains(
                "    hadSelection: selectionStandsInside(event.target?.closest?.(\".terminal\")),"
            ) && window
                .contains("    !termLinkGesture.hadSelection && !selectionStandsInside(host);"),
            "the link gesture went back to asking the whole window about selection"
        );
        assert!(
            window.contains("const LINK_DRAG_THRESHOLD_PX = 4;")
                && window.contains("!termLinkGesture.hadSelection")
                && window.contains("!selectionStandsInside(host);"),
            "the popover's pointer gate lost its drag or selection sense"
        );
        // The path goes over as printed — resolving it here would be a second
        // copy of `resolve_in_project`, which is also the guard that stops a
        // path leaving the checkout.
        let opening = block_after(window, "async function openTermLink(path, line) {");
        assert!(
            !opening.contains("activeRoot") && opening.contains("openPath("),
            "the window resolves a printed path itself, around the backend's \
             own guard:\n{opening}"
        );
        // Quiet until the pointer is on one, or the modifier is down — a
        // terminal underlining every URL at rest is a terminal that looks like
        // a web page, and one that underlines none cannot say a link is there.
        assert!(
            styles.contains("body.mod-held .term-link,\n.term-link:hover {"),
            "links in output are decorated all the time, or never"
        );
    }

    /// 그리는 길에서는 아무것도 재지 않는다 (1-ew).
    ///
    /// The one cost of a *watched*, streaming shell that nobody could see, and
    /// the largest single number on this surface. `paintRail` opened with
    /// `rail.getBoundingClientRect().height` and runs at the tail of every
    /// `apply` — that is a forced, synchronous layout of a screen whose thirty
    /// changed rows were dirtied two statements earlier, sixty times a second.
    /// It reads like arithmetic, which is exactly why it stood.
    ///
    /// Measured on the window's own burst rig (`ui/tests/window.mjs`: 300
    /// frames, 20–40 changed rows each, SGR runs and Korean mixed in, one
    /// visible terminal): 865.6ms inside `apply` for the burst with the read,
    /// 251.6ms with the track watched instead (and the field-wise dressing
    /// below) — and 300 forced layouts became 0.
    ///
    /// A `ResizeObserver` answers the same question from AFTER layout, where
    /// the box has already been computed. The one read that stays is the lazy
    /// seed: an observation lands a frame after the rail is revealed, and a
    /// thumb drawn against zero is a thumb in the wrong place.
    ///
    /// (Orca does not have this shape to get wrong — its scrollbar is the
    /// browser's own on an overflow container, and xterm renders to a canvas.
    /// Ours is hand-drawn because the history lives in Rust and the surface is
    /// not a scroller, so the measurement is ours to not take.)
    #[test]
    fn the_frame_path_measures_nothing() {
        let window = window_source();

        // The frame path, end to end: what `apply` calls, and what those call.
        for (name, opens) in [
            ("apply", "  function apply(delta) {"),
            ("paintRow", "  function paintRow(index) {"),
            (
                "runsOf",
                "  function runsOf(cells, marks, selected = null) {",
            ),
            ("marksOf", "  function marksOf(index, cells) {"),
            ("dressRun", "  function dressRun(span, run, was) {"),
            ("shiftNodes", "  function shiftNodes(count) {"),
            ("paintRail", "  function paintRail() {"),
        ] {
            let body = nested_block(window, opens);
            assert!(
                !body.contains("getBoundingClientRect")
                    && !body.contains(".offsetWidth")
                    && !body.contains(".offsetHeight")
                    && !body.contains(".clientWidth")
                    && !body.contains(".clientHeight")
                    && !body.contains("getComputedStyle"),
                "`{name}` measures the screen it is in the middle of \
                 painting, which forces a layout per frame:\n{body}"
            );
        }

        // The track is watched instead, and the watch is given back with the
        // screen — an observation left running over a host that has left the
        // document is the leak this window counts elsewhere.
        assert!(
            window.contains("  const trackWatch = new ResizeObserver((entries) => {")
                && window.contains("  trackWatch.observe(rail);"),
            "the scrollbar's track is no longer watched, so somebody has to \
             measure it"
        );
        let releasing = nested_block(window, "  function release() {");
        assert!(
            releasing.contains("trackWatch.disconnect();"),
            "a screen given back keeps its observation:\n{releasing}"
        );
        // The seed, and only as a seed: zero means the observer has not
        // answered yet, which is true for exactly the frame that reveals the
        // rail.
        let seeding = nested_block(window, "  function railTrack() {");
        assert!(
            seeding.contains(
                "if (trackHeight === 0) trackHeight = rail.getBoundingClientRect().height;"
            ),
            "the track is never measured at all, so the frame that reveals \
             the rail draws its thumb against zero:\n{seeding}"
        );
        assert!(
            nested_block(window, "  function paintRail() {").contains("const track = railTrack();"),
            "the rail measures the track itself again"
        );
    }

    /// 스트리밍 프레임은 탭 줄을 그리지도, 스타일을 강제로 풀지도 않는다 (t-161).
    ///
    /// Two costs that hid on the road a streaming frame takes, both measured
    /// on the harness (`ui/tests/window.mjs`: 120 cursor-moving frames fed in
    /// one task, read off Chromium's own `Performance` ledger, and 40 renaming
    /// frames with `renderTabs` counted): `RecalcStyleCount` 122 → 0, and the
    /// strip drawn 40 → 0 times during the burst, once after it when the row
    /// did not exist yet. A standing agent row now takes the narrower road:
    /// 59 whole-strip paints / 247 mutations → 0 / 120 over 60 title frames.
    ///
    /// - `noteTermTitle` drew the WHOLE strip synchronously on the frame that
    ///   carried a new OSC 0/2 title — and `renderTabs` is the running count,
    ///   the machine figures, the stage and every group's strip. An agent CLI
    ///   renames its terminal with its current step as it works, so a
    ///   streaming pane repainted the window's chrome from inside the frame
    ///   handler. A standing tab and agent row now receive only their two
    ///   text leaves; missing nodes retain the agent-paint fallback.
    /// - The caret rewind called `Element.getAnimations()` on every frame the
    ///   cursor moved. That call flushes style before it answers (WebKit's
    ///   `Element::getAnimations` → `updateStyleIfNeeded`; Chromium alike), so
    ///   each streaming frame paid a forced style pass over the rows it had
    ///   just dirtied. The rewind is owed to a keystroke's echo: `typedSerial`
    ///   steps at the two doors a key leaves through, and a caret holds still
    ///   once per step.
    ///
    /// And the compositor boundary beside them: the four chrome bands under
    /// `[data-blur="on"]`, and the titlebar at all times, carried a
    /// `backdrop-filter` — a backdrop layer per window edge, re-rendered on
    /// every commit the streaming stage made, over a desktop the platform
    /// material (`apply_window_material`) already blurs. The bands wear the
    /// veil alone; the overlays keep their glass (the shared rule above is
    /// pinned by `a_floating_surface_uses_the_titanium_material`).
    #[test]
    fn a_streaming_frame_neither_draws_the_strip_nor_flushes_style() {
        let window = window_source();
        let naming = block_after(window, "function noteTermTitle(term, title) {");
        assert!(
            naming.contains(
                "if (!writeTermTitleLeaves(term)) scheduleAgentPaint([\"tabs\", \"cards\"]);"
            ) && !naming.contains("renderTabs()"),
            "a title change draws the strip on the frame path again:\n{naming}"
        );
        let leaves = block_after(window, "function writeTermTitleLeaves(term) {");
        assert!(
            leaves.contains("if (agentPaintDue.tabs || agentPaintDue.cards) return false;")
                && leaves.contains("writeTextContent(label, tabLabel(tab));")
                && leaves.contains("writeTextContent(fit.name, fit.primary);")
                && !leaves.contains("renderTabs()")
                && !leaves.contains("paintWorktreeAgents()"),
            "a standing title does not stay on its two guarded leaves:\n{leaves}"
        );
        // Paid once per paint, however many frames the paint follows.
        let painting = nested_block(window, "  function paint() {");
        let guard = painting
            .find("if (caretHeldFor !== typedSerial) {")
            .expect("the caret rewind is no longer owed to a keystroke");
        let rewind = painting
            .find("caret.getAnimations?.()")
            .expect("the caret rewind is gone");
        assert!(
            guard < rewind && painting.contains("caretHeldFor = typedSerial;"),
            "`getAnimations()` — a style flush — runs on every frame that moves the \
             cursor:\n{painting}"
        );
        for door in [
            "function routeText(text) {",
            "function routeKeyPress(target, press) {",
        ] {
            let body = block_after(window, door);
            assert!(
                body.contains("noteTyped();"),
                "a keystroke leaves through `{door}` without stepping the serial:\n{body}"
            );
        }

        let styles = include_str!("../../../../ui/shell.css");
        let bands = block_after_css(styles, ":root[data-blur=\"on\"] .titlebar,");
        assert!(
            bands.contains("background-color: var(--glass-veil);")
                && !bands.contains("backdrop-filter"),
            "the chrome bands blur a desktop the platform material already blurs:\n{bands}"
        );
        let titlebar = block_after_css(styles, ".titlebar {");
        assert!(
            !titlebar.contains("backdrop-filter:"),
            "the titlebar stands a backdrop layer over the streaming stage at all \
             times:\n{titlebar}"
        );
    }

    /// The terminal has settings, and the ones that are not stylesheet
    /// variables are applied where they actually live.
    ///
    /// Orca exposes more than twenty `terminal*` options; this surface carries
    /// only fields with concrete consumers. Renderer fields repaint live, while
    /// scrollback stays in the Rust grid and retells live shells only when that
    /// field changes.
    #[test]
    fn the_terminal_has_settings_and_they_reach_what_they_name() {
        let backend = shipped_backend();
        let (shipped, _) = backend.split_once("#[cfg(test)]").unwrap_or((backend, ""));
        let window = window_source();
        let markup = include_str!("../../../../ui/index.html");
        let styles = strip_comments(include_str!("../../../../ui/shell.css"));

        for command in [
            "terminal_prefs",
            "terminal_windows_status",
            "preview_warp_terminal_themes",
            "preview_ghostty_import",
            "apply_ghostty_import",
            "set_terminal_prefs",
            "patch_terminal_prefs",
        ] {
            assert!(
                shipped.contains(&format!("\n            {command},\n")),
                "{command} is not registered with the window"
            );
        }
        let patch_type = block_after(shipped, "enum TerminalPrefsPatch {");
        for variant in [
            "FontSize(u32)",
            "FontFamily(String)",
            "Ligatures(TerminalLigatureMode)",
            "MacOptionAsAlt(MacOptionAsAlt)",
            "JisYenToBackslash(bool)",
            "WindowsShell(WindowsTerminalShell)",
            "WindowsPowerShellImplementation(WindowsPowerShellImplementation)",
            "ThemeDark(String)",
            "UseSeparateLightTheme(bool)",
            "ThemeLight(String)",
            "ImportCustomThemes(Vec<CustomTerminalTheme>)",
            "RemoveCustomTheme(String)",
            "ColorOverride(TerminalColorOverridePatch)",
            "ResetColorOverrides",
            "Leading(f32)",
            "Weight(u32)",
            "CursorBlink(bool)",
            "CursorStyle(TerminalCursorStyle)",
            "CursorOpacity(f32)",
            "PaddingX(u32)",
            "PaddingY(u32)",
            "Sensitivity(f32)",
            "Scrollback(usize)",
            "WordSeparators(String)",
            "FastScrollSensitivity(f32)",
            "TuiScrollSensitivity(u32)",
            "FocusFollowsMouse(bool)",
            "HideMouseWhileTyping(bool)",
            "CopyOnSelect(bool)",
            "RightClickPaste(bool)",
            "InactivePaneOpacity(f32)",
            "DividerColorDark(String)",
            "DividerColorLight(String)",
            "DividerThicknessPx(u32)",
        ] {
            assert!(
                patch_type.contains(variant),
                "terminal patch lost its typed `{variant}` field:\n{patch_type}"
            );
        }
        let patching = block_after(shipped, "fn patch_terminal_prefs(");
        assert!(
            patching.contains("setting_key::TERMINAL_PREFS")
                && patching.contains("patch.apply(&mut settings.terminal_prefs);")
                && patching.contains(
                    "let changes_scrollback = matches!(&patch, TerminalPrefsPatch::Scrollback(_));"
                )
                && patching.contains("if changes_scrollback {")
                && patching.contains("for pty in state.terminals().handles() {"),
            "the per-control terminal patch does not commit canonically or update live shells:\n{patching}"
        );
        let sending = nested_block(window, "function setTermPrefs(change) {");
        assert!(
            sending.contains("Object.entries(change)[0]")
                && sending.contains("\"patch_terminal_prefs\"")
                && sending.contains("patch: { kind, value }")
                && !sending.contains("prefs: termPrefs"),
            "a terminal control sends stale sibling fields instead of one typed patch:\n{sending}"
        );
        assert!(
            window.contains(
                "termPrefs = { ...(termPrefs ?? {}), ...(snapshot.terminal_prefs ?? {}) };"
            ),
            "the terminal view does not repaint from the canonical snapshot"
        );
        let ghostty = include_str!("../../src/ghostty_import.rs");
        let ghostty_apply = block_after(shipped, "fn apply_ghostty_import(");
        assert!(
            window.contains("invoke(\"preview_ghostty_import\")")
                && window.contains("\"apply_ghostty_import\"")
                && markup.contains("id=\"term-ghostty-import\"")
                && markup.contains("id=\"term-ghostty-import-scrim\""),
            "the Ghostty import command or its visible owner was disconnected"
        );
        assert!(
            ghostty_apply.contains("setting_key::TERMINAL_PREFS")
                && ghostty_apply.contains("setting_key::WINDOW_MATERIAL")
                && ghostty_apply.contains("setting_key::EDITING_PREFS")
                && ghostty_apply.contains("patch.apply(settings)"),
            "Ghostty import is no longer one typed settings transaction:\n{ghostty_apply}"
        );
        assert!(
            ghostty.contains("MAX_CONFIG_BYTES: u64 = 1_000_000")
                && ghostty.contains("MAX_THEME_BYTES: u64 = 262_144")
                && ghostty.contains("durable_file::open_plain_file(path)")
                && ghostty.contains("selection-word-chars"),
            "Ghostty discovery, bounds, or unsupported-key truth drifted"
        );
        // Clamped in Rust as well as in the control: the value arrives from a
        // file anyone can edit, so a control's range is not a guarantee.
        let clamping = block_after(shipped, "impl TerminalPrefs {");
        assert!(
            clamping.contains("TERM_FONT_SIZE_BOUNDS")
                && clamping.contains("TERM_WEIGHT_BOUNDS")
                && clamping.contains("is_finite()")
                && clamping.contains("MIN_SCROLLBACK_LINES"),
            "a hand-edited settings file can describe a terminal this window \
             cannot draw:\n{clamping}"
        );
        // Every live shell is retold, and every new one is told at birth —
        // through ONE door, because there are eight spawn sites and a depth
        // applied at seven of them is the bug that reads as "the setting works
        // except for agents".
        let saving = block_after(shipped, "fn set_terminal_prefs(");
        assert!(
            saving.contains("settings.terminal_prefs = kept.clone();")
                && saving.contains("for pty in state.terminals().handles() {"),
            "the compatible full-record setter no longer replaces deliberately or updates live scrollback:\n{saving}"
        );
        let holding = block_after(
            shipped,
            "    fn hold_terminal(\n        &self,\n        settings: &settings::SettingsRepository,",
        );
        assert!(
            holding.contains("load_settings_for_boot(settings)")
                && holding.contains(".terminal_prefs;")
                && holding.contains("set_scrollback_cap(prefs.scrollback)"),
            "a newly spawned shell does not get the chosen scrollback:\n{holding}"
        );
        assert!(
            !shipped.contains("state.terminals().insert("),
            "a spawn site went around `hold_terminal` and its shell will keep \
             the default scrollback"
        );

        // Every control is a row somebody can find by its words —
        // the settings search reads rendered text and needs no registry.
        for id in [
            "term-font-size",
            "term-font-family",
            "term-ligatures",
            "term-option-as-alt",
            "term-jis-yen-to-backslash",
            "term-theme-dark",
            "term-separate-light-theme",
            "term-theme-light",
            "term-theme-import-auto",
            "term-theme-import-files",
            "term-theme-import-folder",
            "term-custom-theme-list",
            "term-theme-import-scrim",
            "term-color-overrides",
            "term-leading",
            "term-weight",
            "term-cursor-blink",
            "term-cursor-style",
            "term-cursor-opacity",
            "term-padding-x",
            "term-padding-y",
            "term-inactive-pane-opacity",
            "term-divider-thickness",
            "term-divider-color-dark",
            "term-divider-color-light",
            "term-sensitivity",
            "term-scrollback",
            "term-word-separators",
            "term-windows-shell",
            "term-windows-powershell",
            "term-fast-scroll",
            "term-tui-scroll",
            "term-focus-follows-mouse",
            "term-hide-mouse-while-typing",
            "term-copy-on-select",
            "term-right-click-paste",
        ] {
            assert!(
                markup.contains(&format!("id=\"{id}\"")),
                "the terminal settings lost its `{id}` row"
            );
        }
        // Applied by writing the tokens, so every screen redraws through the
        // cascade — and the cell box changes with the font, so the pty has to
        // be retold its grid or the child writes for a screen that is no
        // longer that shape.
        let applying = block_after(window, "function applyTermPrefs(previous = null) {");
        assert!(
            applying.contains(
                r#"root.style.setProperty("--term-font-size", `${termPrefs.font_size}px`);"#
            ) && applying.contains("--term-font-choice")
                && applying
                    .contains("terminalFontFamilyChoice(termPrefs.font_family, termPrefsSpec)")
                && applying.contains("root.dataset.termLigatures")
                && applying.contains("terminalLigaturesEnabled(")
                && applying.contains("root.dataset.termCursorStyle = termPrefs.cursor_style;")
                && applying.contains("--term-bold-weight")
                && applying.contains("terminalBoldWeight(termPrefs.weight, termPrefsSpec)")
                && applying.contains("--term-cursor-opacity")
                && applying.contains("--term-padding-x")
                && applying.contains("--term-padding-y")
                && applying.contains("--term-inactive-pane-opacity")
                && applying.contains("--term-divider-thickness")
                && applying.contains("--term-divider-color-dark")
                && applying.contains("--term-divider-color-light")
                && applying.contains("applyTerminalPalette();")
                && applying.contains("--term-divider-hit-size")
                && applying.contains("--term-divider-extension")
                && applying.contains("termPrefs.hide_mouse_while_typing !== true")
                && applying.contains("view.host.classList.remove(\"is-pointer-hidden\")")
                && applying.contains("\"font_family\"")
                && applying.contains("if (metricsChanged) resizeAllTerminals();"),
            "the terminal settings do not reach the screen, or reach it \
             without resizing the shell:\n{applying}"
        );
        assert!(
            styles.contains(
                ":root[data-term-cursor-style=\"bar\"] .term-caret::after"
            ) && styles.contains(
                ":root[data-term-cursor-style=\"underline\"] .term-caret::after"
            ) && styles.contains(
                ":root[data-term-cursor-style=\"block\"] .pane-slot:not(.is-active) .term-caret::after"
            ) && styles.contains("opacity: var(--term-cursor-opacity);")
                && styles.contains("padding: var(--term-padding-y) var(--term-padding-x);")
                && styles.contains("top: calc(var(--term-padding-y) + var(--term-inset-y, 0px));")
                && styles.contains("left: calc(var(--term-padding-x) + var(--term-inset-x, 0px));")
                && styles.contains("opacity: var(--term-inactive-pane-opacity);")
                && styles.contains("var(--term-divider-thickness)")
                && styles.contains("var(--term-divider-hit-size)")
                && styles.contains("var(--term-divider-extension")
                && styles.contains("var(--term-divider-color-active")
                && styles.contains("background: var(--term-selection-bg);")
                && styles.contains("color: var(--term-selection-fg);")
                && styles.contains("background: var(--term-cursor);")
                && styles.contains("var(--term-cursor-accent)")
                && styles
                    .contains("font-family: var(--term-font-choice, \"SF Mono\"), var(--font-mono);")
                && styles.contains("font-feature-settings: \"liga\" 0, \"calt\" 0;")
                && styles.contains(":root[data-term-ligatures=\"on\"] .term")
                && styles.contains("font-feature-settings: \"liga\" 1, \"calt\" 1;")
                && styles.contains(".terminal.is-pointer-hidden *")
                && styles.contains("cursor: none !important;"),
            "terminal appearance fields lost their live CSS consumers"
        );
        let palette = block_after(window, "function applyTerminalPalette() {");
        let palette_variables = block_after(
            window,
            "const TERMINAL_BASE_COLOR_VARIABLES = Object.freeze({",
        );
        assert!(
            palette.contains("terminalThemeUsesLightVariant()")
                && palette.contains("termPrefs.color_overrides")
                && palette.contains("TERMINAL_BASE_COLOR_VARIABLES")
                && palette.contains("terminalAnsiColorKeys()")
                && palette.contains("--term-divider-color-active")
                && palette.contains("forgetPalette();")
                && palette_variables.contains("--term-screen-bg")
                && palette_variables.contains("--term-selection-bg")
                && palette_variables.contains("--term-cursor-accent"),
            "terminal themes no longer compose one live palette:\n{palette}"
        );
        let pointer_input = block_after(window, "function hideTerminalPointerForInput(target) {");
        assert!(
            pointer_input.contains("termPrefs?.hide_mouse_while_typing !== true")
                && pointer_input.contains("terminalViewForTarget(target)")
                && pointer_input.contains("classList.add(\"is-pointer-hidden\")"),
            "terminal input no longer hides only the receiving screen:\n{pointer_input}"
        );
        let routing = block_after(window, "function routeText(text) {");
        let keying = block_after(window, "function routeKeyPress(target, press) {");
        let paste = block_after(window, "async function pasteTextAt(target, text) {");
        assert!(
            routing.contains("hideTerminalPointerForInput(target);")
                && keying.contains("hideTerminalPointerForInput(target);")
                && paste.contains("hideTerminalPointerForInput(target);")
                && window.contains("routeKeyPress(target, {\n    key: terminalKeyForEvent("),
            "text, keys, and paste do not share the hide-pointer input owner"
        );
        let jis_yen = block_after(window, "function isPlainPhysicalJisYenKey(event) {");
        let jis_remap = block_after(window, "function remapsJisYenToBackslash(event) {");
        assert!(
            jis_yen.contains("event.keyCode !== 229")
                && jis_yen.contains(r#"event.code === "IntlYen""#)
                && jis_yen.contains(r#"event.key === "¥""#)
                && jis_yen.contains("!event.metaKey")
                && jis_yen.contains("!event.ctrlKey")
                && jis_yen.contains("!event.altKey")
                && jis_yen.contains("!event.shiftKey")
                && jis_remap.contains("usesCommandModifier")
                && jis_remap.contains("termPrefs?.jis_yen_to_backslash === true")
                && window.contains("if (remapsJisYenToBackslash(event)) {\n    event.preventDefault();\n    routeText(\"\\\\\");\n    return;")
                && window.contains(r#"for (const eventName of ["keypress", "keyup"])"#)
                && window.contains(
                    "if (!remapsJisYenToBackslash(event) || keyboardTarget() === null) return;"
                ),
            "the macOS JIS Yen setting no longer maps one exact physical key to one backslash"
        );
        let terminal_view = block_after(window, "function makeTermView(");
        assert!(
            terminal_view.contains("function movePointer(event) {")
                && terminal_view.contains("host.classList.remove(\"is-pointer-hidden\")")
                && terminal_view.contains("host.removeEventListener(\"mousemove\", movePointer)"),
            "mouse movement or view release cannot restore/dispose the pointer state:\n{terminal_view}"
        );
        // The slot builder both renderers share — the split tree and the
        // responsive grid — so the pointer contract is checked where it
        // lives, once for both.
        let pane = block_after(window, "function paneSlotEl(tab, term) {");
        assert!(
            pane.contains("if (!termPrefs.focus_follows_mouse) return;")
                && pane.contains("setActivePane(tab, term);")
                && pane.contains("keySink.focus();"),
            "focus-follows-mouse changes the active mark without handing the terminal its keyboard:\n{pane}"
        );
    }

    #[test]
    fn terminal_clipboard_is_plain_text_least_privilege_and_single_owner() {
        let cargo = include_str!("../../Cargo.toml");
        let backend = shipped_backend();
        let window = window_source();
        let markup = include_str!("../../../../ui/index.html");
        let grid = include_str!("../../../zerocode-pty/src/grid.rs");
        let registry = include_str!("../../../zerocode-lane/src/registry.rs");
        let capability_text = include_str!("../../capabilities/default.json");
        let capability: serde_json::Value =
            serde_json::from_str(capability_text).expect("clipboard capability is JSON");
        let permissions: Vec<&str> = capability["permissions"]
            .as_array()
            .expect("capability permissions")
            .iter()
            .filter_map(serde_json::Value::as_str)
            .filter(|permission| permission.starts_with("clipboard-manager:"))
            .collect();
        assert_eq!(
            permissions,
            [
                "clipboard-manager:allow-read-text",
                "clipboard-manager:allow-write-text"
            ],
            "clipboard capability widened beyond plain text"
        );
        assert_eq!(
            capability["webviews"],
            serde_json::json!(["main", "board-popout"]),
            "clipboard authority escaped the two trusted app webviews"
        );
        assert!(
            cargo.contains(r#"tauri-plugin-clipboard-manager = "=2.3.2""#)
                && backend.contains(".plugin(tauri_plugin_clipboard_manager::init())"),
            "the audited clipboard plugin version is not registered"
        );
        assert!(
            window.contains("const clipboardText = Object.freeze({")
                && window.contains("window.__TAURI__.clipboardManager.readText()")
                && window.contains("window.__TAURI__.clipboardManager.writeText(String(value))")
                && !window.contains("navigator.clipboard"),
            "programmatic clipboard access has more than one authority"
        );
        let browser_menu = block_after(window, "function browserMenuItems(tab, said) {");
        assert_eq!(
            browser_menu.matches("clipboardText.write(").count(),
            3,
            "link, selection, and page copy must share the one clipboard adapter:\n{browser_menu}"
        );

        let selection = block_after(window, "function terminalSelectionView(key) {");
        assert!(
            selection.contains("view.selectionStands() && view.addressKey() === key"),
            "copy can consume a selection owned by another terminal:\n{selection}"
        );
        let reading = block_after(window, "async function pasteClipboardAt(target) {");
        let capture_at = reading
            .find("const captured = target ? { ...target } : null;")
            .expect("paste no longer captures its target");
        let read_at = reading
            .find("const text = await clipboardText.read({ quiet: true });")
            .expect("paste no longer reads through the clipboard authority");
        assert!(
            capture_at < read_at,
            "the paste target is read after the async clipboard gap:\n{reading}"
        );
        // The picture road comes second and only when the words came up
        // empty: the clipboard's text is still the one thing the shortcut
        // pastes when there is any, and the picture is seated by the same
        // backend writer the `paste` event road uses — never read here.
        let words_win = reading
            .find("if (text) return pasteTextAt(captured, text);")
            .expect("paste no longer prefers the clipboard's words");
        let picture_at = reading
            .find(r#"invoke("save_clipboard_image")"#)
            .expect("a picture-only clipboard has no road through the shortcut");
        assert!(
            read_at < words_win && words_win < picture_at,
            "the picture must be asked for after the words came up empty:\n{reading}"
        );
        assert!(
            !reading.contains("readImage"),
            "the shortcut must not read pixels in the window; the backend seats the picture:\n{reading}"
        );
        let routing = block_after(window, "async function pasteTextAt(target, text) {");
        assert!(
            routing.contains(r#"invoke("term_paste"#)
                && routing.contains(r#"invoke("paste_input"#)
                && !routing.contains(r#"invoke("term_text"#),
            "clipboard text bypasses the existing sanitized paste commands:\n{routing}"
        );
        let keydown = window
            .split_once("window.addEventListener(\"keydown\", (event) => {")
            .and_then(|(_, rest)| rest.split_once("/* Hangul, and every other script"))
            .map(|(body, _)| body)
            .expect("terminal keydown router");
        let encoder_at = keydown
            .find("routeKeyPress(target, {")
            .expect("terminal encoder road");
        let clipboard = block_after(
            window,
            "function terminalClipboardShortcut(event, target) {",
        );
        let clipboard_sites: Vec<usize> = keydown
            .match_indices("terminalClipboardShortcut(event, target)")
            .map(|(at, _)| at)
            .collect();
        assert!(
            clipboard.contains("const clipboardModifier = usesCommandModifier")
                && clipboard.contains("? event.metaKey && !event.ctrlKey")
                && clipboard.contains(": event.ctrlKey && !event.metaKey;")
                && clipboard.contains("if (!terminalSelectionStands(expectedKey)) return false;")
                && clipboard.contains("const expectedKey = terminalTargetKey(target);")
                && clipboard.contains("void copyTerminalSelection(expectedKey);")
                && clipboard.contains("void pasteClipboardAt(target);")
                && clipboard_sites.len() == 3
                && clipboard_sites[0] < encoder_at
                && clipboard_sites[1] < encoder_at
                && clipboard_sites[2] > encoder_at,
            "platform clipboard chords bypass ownership or double-send through the terminal encoder:\n{keydown}"
        );
        let terminal = block_after(window, "function makeTermView(");
        assert!(
            terminal.contains("if (event.button !== 2) return;")
                && terminal.contains("if (programHasMouse())")
                // Shift is the one exception, and the exception is the
                // xterm rule the wheel already keeps: a shifted gesture is the
                // terminal's own, reported to no program, so its selection may
                // be copied — the only way to select a tracking TUI's output.
                && terminal.contains("selectingLocally = event.shiftKey && programHasMouse();")
                && terminal.contains("pressOwnedByProgram = !event.shiftKey && programHasMouse();")
                && terminal.contains("if (selectingLocally) return false;")
                && terminal.contains("wasOwnedByProgram || programHasMouse()")
                && terminal.contains("termPrefs?.copy_on_select !== true")
                && terminal.contains("termPrefs?.right_click_paste !== true"),
            "middle-click or a mouse-tracking program can trigger clipboard gestures:\n{terminal}"
        );
        assert!(
            terminal.contains("function finishPointerGesture(event) {")
                && terminal
                    .contains(r#"window.addEventListener("mouseup", finishPointerGesture);"#)
                && terminal
                    .contains(r#"window.removeEventListener("mouseup", finishPointerGesture);"#),
            "a closed terminal keeps its window-level release listener:\n{terminal}"
        );
        assert!(
            backend.contains("allow_osc52_clipboard: bool")
                && backend.contains("AllowOsc52Clipboard(bool)")
                && backend.contains("allow_osc52_clipboard: true")
                && markup.contains("term-allow-osc52-clipboard")
                && window.contains("termPrefs?.allow_osc52_clipboard !== true")
                && backend.contains(
                    r#"const TERMINAL_CLIPBOARD_WRITE_EVENT: &str = "terminal:clipboard-write";"#
                )
                && window.contains(
                    r#"const TERMINAL_CLIPBOARD_WRITE_EVENT = "terminal:clipboard-write";"#
                )
                && window.contains("listen(TERMINAL_CLIPBOARD_WRITE_EVENT")
                && window.contains("await clipboardText.write(text);")
                && !window.contains("navigator.clipboard"),
            "OSC 52 lost its typed default-on setting or the single clipboard authority"
        );
        assert!(
            grid.contains("const MAX_OSC52_BASE64_CHARS: usize = 128 * 1024;")
                && grid.contains("take_osc52_clipboard_write")
                && grid.contains("matches!(byte, b'c' | b'p' | b'q' | b's' | b'0'..=b'7')")
                && registry.contains("ClipboardWrite { lane: LaneId, text: String }")
                && registry.contains(".take_osc52_clipboard_write()")
                && block_after(backend, "fn emit_lane_event(app: &AppHandle, event: LaneEvent) {")
                    .contains("app.emit_to(\n                MAIN_WINDOW_LABEL,\n                TERMINAL_CLIPBOARD_WRITE_EVENT,")
                && block_after(backend, "fn pump_loop(app: &AppHandle) {")
                    .contains("app.emit_to(\n                MAIN_WINDOW_LABEL,\n                TERMINAL_CLIPBOARD_WRITE_EVENT,"),
            "local, lane, and SSH transports no longer share one bounded OSC 52 parser/event road"
        );
        // A hidden terminal's OSC 52 write reaches the clipboard whether or
        // not any frame is drawn this round: the write is taken under the
        // lock, and the emission loop stands on its own, under no frames
        // gate. (The pump once emitted inside `if !frames.is_empty()`; the
        // gate is gone, and this pins that it stays gone.)
        let pumping = block_after(backend, "fn pump_loop(app: &AppHandle) {");
        let taken = pumping
            .find("take_osc52_clipboard_write()")
            .expect("the pump takes OSC 52 writes");
        let emitted = pumping
            .find("for text in clipboard_writes {")
            .expect("the pump emits the OSC 52 writes it took");
        assert!(
            taken < emitted && !pumping[taken..emitted].contains("if !frames.is_empty() {"),
            "a hidden terminal's OSC 52 write is trapped behind the watched-screen gate:\n{pumping}"
        );
    }

    #[test]
