                && backend.contains("primary_selection_middle_click_paste: Option<bool>")
                && backend.contains("\n            read_primary_selection,\n")
                && backend.contains("\n            write_primary_selection,\n")
                && primary_selection_source.contains("LinuxClipboardKind::Primary")
                && primary_selection_source
                    .contains("pub(crate) const MAX_BYTES: usize = 262_144;")
                && window.contains("const PRIMARY_SELECTION_MAX_CODE_UNITS = 65_536;")
                && window.contains("function installPrimarySelectionPaste() {")
                && window.contains("void readPrimarySelectionText().then((text) => pasteTextAt(")
                && window.contains("if (usesLinuxPlatform)")
                && window.contains("if (was === 1 && !wasOwnedByProgram")
