    #[test]
    fn open_in_apps_have_one_catalog_patch_and_safe_launch_owner() {
        let window = window_source();
        let markup = strip_comments(include_str!("../../../../ui/index.html"));
        let backend = shipped_backend();
        let (shipped, _) = backend.split_once("#[cfg(test)]").unwrap_or((backend, ""));

        assert!(
            shipped.contains("            patch_open_in_applications,")
                && shipped.contains("            open_workspace_in_application,")
                && shipped.contains("pub const OPEN_IN_APPLICATIONS"),
            "the Open in list or launch command is not registered once"
        );
        let patch = block_after(shipped, "fn patch_open_in_applications(");
        assert!(
            patch.contains("setting_key::OPEN_IN_APPLICATIONS")
                && patch.contains("patch.apply(&mut settings.open_in_applications)"),
            "Open in edits no longer patch one canonical item list:\n{patch}"
        );
        // ONE launch road, two fenced doors. The road holds the four
        // protections; each door holds only its own fence — the workspace
        // door resolves through the catalog, the file door through the
        // active-root fence — so neither can trust a renderer path, and a
        // protection fixed on the road is fixed for both.
        let road = block_after(shipped, "fn spawn_open_in_application(");
        assert!(
            road.contains(".find(|application| application.id == application_id)")
                && road.contains("open_in_application_launch(application, target)")
                && road.contains("shell_path::hydrated()")
                && road.contains("zerocode_core::reap::spawn_forgotten(opener)"),
            "the launch road trusts renderer command data or bypasses PATH/reaping:\n{road}"
        );
        // And a command that is not on the PATH is not the end of the road:
        // the editors this window ships presets for keep their CLI inside
        // their own bundle, so the ordinary machine reaches the second try
        // rather than the silence that was reported.
        assert!(
            road.contains(
                "open_in_application_by_name(macos_application_name(application), target)"
            ),
            "an editor whose CLI is not installed goes back to failing \
             silently:\n{road}"
        );
        let launch = block_after(shipped, "fn open_workspace_in_application(");
        assert!(
            launch.contains("known_workspace_context(state.config_root(), &path)")
                && launch.contains(
                    "spawn_open_in_application(state.settings(), &application_id, &workspace)"
                ),
            "the workspace door left the catalog fence or the one road:\n{launch}"
        );
        let filing = block_after(shipped, "fn open_path_in_application(");
        assert!(
            filing.contains("fenced_path(&state, &path)?")
                && filing.contains(
                    "spawn_open_in_application(state.settings(), &application_id, &seat)"
                ),
            "the file door left the active-root fence or the one road:\n{filing}"
        );
        assert!(
            shipped.contains("            open_path_in_application,"),
            "the file door is not registered"
        );
        let argv = block_after(shipped, "fn open_in_application_launch(");
        assert!(
            argv.contains("split_command(&application.command)")
                && argv.contains("arguments.push(workspace.as_os_str().to_owned())")
                && !argv.contains("sh -c")
                && !argv.contains("shell"),
            "the workspace path is no longer a separate argv item:\n{argv}"
        );

        assert!(
            markup.contains("id=\"settings-open-in-apps\"")
                && markup.contains("id=\"open-in-applications-list\"")
                && markup.contains("id=\"open-in-app-presets\"")
                && markup.contains("id=\"open-in-add-custom\""),
            "General no longer exposes the Open In Apps editor"
        );
        let ui_patch = block_after(window, "function patchOpenInApplications(patch) {");
        assert!(
            ui_patch.contains("\"open_in_applications\"")
                && ui_patch.contains("\"patch_open_in_applications\"")
                && ui_patch.contains("{ patch }")
                && !ui_patch.contains("set_settings"),
            "the renderer replaced the list through a whole-document writer:\n{ui_patch}"
        );
        let snapshot = block_after(
            window,
            "function applyWorkflowSettingsSnapshot(snapshot, first) {",
        );
        assert!(
            snapshot.contains("hasSetting(snapshot, \"open_in_applications_spec\")")
                && snapshot.contains("hasSetting(snapshot, \"open_in_applications\")")
                && snapshot.contains("paintOpenInApplications()"),
            "the renderer invented a preset/cap catalog or restart no longer repaints the list:\n{snapshot}"
        );
        let menu = block_after(window, "function worktreeOpenInItems(worktree) {");
        assert!(
            menu.contains("openWorkspaceInApplication(worktree.path, application.id)")
                && menu.contains("openWorkspaceInApplication(worktree.path)")
                && menu.contains("setSettingsOpen(true, \"settings-open-in-apps\")"),
            "the workspace menu bypasses configured ids, its file manager, or Customize:\n{menu}"
        );
    }

