    /// The stage's documents survive the window closing.
    ///
    /// Orca persists its editor centre whole — tabs, groups, split tree,
    /// focus — and validates on the way back (`hydrateUnifiedFormat`,
    /// I18nProvider:57156). The measured rules live in `stage_layout.rs`
    /// and are tested there; this gate holds where each piece lives:
    /// the rules on this side, the window sending raw and rebuilding
    /// through its own doors.
    #[test]
    fn the_stages_documents_survive_the_window_closing() {
        let shell = shipped_backend();
        let (shipped, _) = shell.split_once("#[cfg(test)]").unwrap_or((shell, ""));
        let rules = include_str!("../../src/stage_layout.rs");
        let (ruling, _) = rules.split_once("#[cfg(test)]").unwrap_or((rules, ""));
        let window = window_source();

        // Both halves of the round trip are registered, and the read hands
        // back a layout already normalised — the window never learns the
        // rules exist.
        assert!(
            shipped.contains("stage_layouts,") && shipped.contains("save_stage_layouts,"),
            "a stage layout command fell out of the handler list"
        );
        assert!(
            block_after(shipped, "fn stage_layouts(")
                .contains("stage_layout::StageLayout::normalized"),
            "the read returns the file raw, so a hand edit reaches the window"
        );

        // The measured refusals: a transient tab is a view of a moment
        // (`isTransientEditorContentType`, :50810), a path that left the
        // disk cannot come back, and a tree that disagrees with its own
        // group count is a hand edit refused whole.
        let keeping = block_after(ruling, "fn keeps(&self)");
        assert!(
            !keeping.contains("\"diff\"") && !keeping.contains("\"imagediff\""),
            "a stored diff reopens as a comparison that is no longer true"
        );
        assert!(
            keeping.contains("is_file()"),
            "a file that left the disk is offered back anyway"
        );
        assert!(
            block_after(ruling, "pub fn normalized(")
                .contains("self.root.leaves() != self.groups.len()"),
            "the tree and the groups can disagree and still restore"
        );
        // A group that kept nothing folds out, and focus closes ranks —
        // `pruneTabGroupLayoutForGroups` + `selectHydratedActiveGroupId`.
        assert!(
            ruling.contains("fn prune_leaves(") && ruling.contains("fn renumbered("),
            "an emptied group leaves a hole in the tree instead of folding"
        );

        // The window: the record travels raw from the live stage, the
        // restore walks the SAME doors a person walks, and the restore
        // never writes the file it is reading.
        let persisting = block_after(window, "function persistStageLayouts(");
        let flushing = block_after(window, "async function flushStageLayouts(");
        assert!(
            persisting.contains("pendingStageLayouts.set(worktree, layout);")
                && persisting.contains("flushStageLayouts();")
                && flushing.contains("if (savingStageLayouts) return;")
                && flushing
                    .contains(r#"await invoke("save_stage_layouts", { worktree, layout });"#),
            "the stage snapshot no longer reaches its serialized writer"
        );
        let reopening = block_after(window, "async function reopenStageTab(");
        for door in [
            "openFile(",
            "openImage(",
            "openBoard()",
            "openChangesArea(",
            "openVault()",
        ] {
            assert!(
                reopening.contains(door),
                "`{door}` is not how a stored tab of that kind comes back — \
                 a second opener drifts from the real one:\n{reopening}"
            );
        }
        let restoring = block_after(window, "async function restoreStageLayout(");
        assert!(
            restoring.contains("restoringStage = true") && restoring.contains("finally"),
            "the restore can write the file it is still reading"
        );
        assert!(
            block_after(window, "function persistStageLayouts(").contains("if (restoringStage"),
            "the persist door does not know a restore is running"
        );
    }

    /// A closed window's screens reopen showing what they showed.
    ///
    /// Orca's scrollback round trip, measured at both ends: the shutdown
    /// capture serialises every live pane under the 512 KiB cap, binary-
    /// searching the largest TAIL of rows that fits
    /// (`captureTerminalShutdownLayout`, index-ftls8Hg_.js:100871); the
    /// restore strips a trailing alt-screen segment and follows the buffer
    /// with the measured mode reset (`restoreScrollbackBuffers` +
    /// `POST_REPLAY_MODE_RESET`, I18nProvider:46152/:46043). The rules live
    /// in `zerocode_pty::serialize`, tested there; this gate holds the
    /// wiring around them.
    #[test]
    fn a_closed_windows_screens_reopen_showing_what_they_showed() {
        let shell = shipped_backend();
        let (shipped, _) = shell.split_once("#[cfg(test)]").unwrap_or((shell, ""));
        let rules = include_str!("../../src/pane_layout.rs");
        let writer = include_str!("../../../zerocode-pty/src/serialize.rs");
        let (writing, _) = writer.split_once("#[cfg(test)]").unwrap_or((writer, ""));
        let window = window_source();

        // The cap and the tail search — head-truncation keeps the oldest
        // output and loses the part the person was looking at.
        assert!(
            writing.contains("SCROLLBACK_BUFFER_BYTE_LIMIT: usize = 512 * 1024")
                && writing.contains("usize::midpoint(lo, hi)"),
            "the capture lost its measured cap or its tail search"
        );
        // The replay strip: a buffer ending inside the alternate screen is
        // cut at the entry, and the reset hands over a sane terminal.
        assert!(
            block_after(writing, "pub fn replay_payload(")
                .contains("(Some(on), Some(off)) if on > off")
                && writing.contains("POST_REPLAY_MODE_RESET"),
            "the replay lost the alt-screen strip or the mode reset"
        );

        // The capture runs at the one moment every shell is still alive,
        // spends the session's pty ids, and clears them — a number left in
        // the file would point the NEXT session's capture at somebody
        // else's shell.
        assert!(
            shipped.contains("RunEvent::ExitRequested")
                && shipped.contains("capture_scrollback_at_exit"),
            "nothing captures the screens on the way out"
        );
        assert!(
            block_after(shipped, "fn capture_scrollback_at_exit(")
                .contains("std::mem::take(&mut layout.terms)"),
            "the capture no longer spends and clears the stored pty ids"
        );
        // The replay feeds the terminal's PARSER — never the child's stdin:
        // this is what the screen showed, not what somebody typed.
        let replaying = block_after(shipped, "fn replay_stored_screen(");
        assert!(
            replaying.contains("terminal.feed(") && !replaying.contains("write_input"),
            "the replay writes at the child instead of the screen:\n{replaying}"
        );
        // And it rides the spawn, ahead of the hold: nothing parses a child's
        // output until its terminal is held, so a screen fed before the hold
        // precedes the program's first byte. A replay sent after the spawn
        // answered came after a resumed zo had switched bracketed paste on,
        // and the replay's mode reset switched it off for the pane's life —
        // every multi-line paste submitted at its first line break
        // (2026-09-17). All three roads a restored leaf takes.
        for (road, file) in [
            (
                "fn open_term_tab(",
                include_str!("../../src/cmd/terminal.rs"),
            ),
            (
                "fn launch_agent_tab(",
                include_str!("../../src/cmd/terminal.rs"),
            ),
            ("fn resume_session(", include_str!("../../src/cmd/board.rs")),
        ] {
            let body = block_after(file, road);
            let replay_at = body.find("replay_stored_screen(");
            let hold_at = body.find("state.hold_terminal(");
            assert!(
                matches!((replay_at, hold_at), (Some(replay), Some(hold)) if replay < hold),
                "`{road}` does not put the stored screen in before it holds the terminal"
            );
        }
        assert!(
            !shipped.contains("fn replay_scrollback("),
            "a second, after-the-spawn replay command is back"
        );
        // And what crosses the bridge is the shape, not the freight: the
        // window rebuilds the tree while the buffers replay over here.
        assert!(
            block_after(shipped, "fn pane_layouts_read(")
                .contains("layout.buffers = HashMap::new()"),
            "half a megabyte per leaf crosses the bridge to be ignored"
        );
        // The file trusts nothing: a buffer past the cap is a hand edit.
        assert!(
            block_after(rules, "let buffers = self")
                .contains("held.len() <= zerocode_pty::SCROLLBACK_BUFFER_BYTE_LIMIT"),
            "an edited file can feed an unbounded buffer to a fresh terminal"
        );
        // The window's half: the live shells travel by position with every
        // save, and every restored leaf asks for its screen back.
        assert!(
            block_after(window, "function tabLayoutRecord(").contains("terms"),
            "the record no longer says which shells hold the screens"
        );
        let mounting = block_after(window, "async function mountStoredLayout(");
        assert!(
            mounting.contains("{ worktree, id: record.id, ordinal: at }")
                && mounting.contains("spawnStoredLeaf(wake, record.running?.[at], grid, restore)")
                && !window.contains(r#"invoke("replay_scrollback""#),
            "a restored leaf comes back blank, or its screen is replayed after its program started:\n{mounting}"
        );
        let leaf = block_after(window, "async function spawnStoredLeaf(");
        assert!(
            leaf.contains("!!wake.interrupted, restore)")
                && leaf.contains(r#"rows, cols, restore })"#)
                && leaf
                    .contains(r#"invoke("open_term_tab", { rows, cols, plain: true, restore })"#),
            "a spawn road a restored leaf takes drops its stored screen:\n{leaf}"
        );
    }

    #[test]
    fn the_pane_layout_survives_the_window_closing() {
        let backend = shipped_backend();
        let rules = include_str!("../../src/pane_layout.rs");
        let window = window_source();

        // Both halves of the round trip are registered.
        assert!(
            backend.contains("pane_layouts,") && backend.contains("save_pane_layouts,"),
            "a layout command fell out of the handler list"
        );

        // The two measured rules, in the one place they live.
        assert!(
            rules.contains("EVEN_ENOUGH: f64 = 5e-3")
                && rules.contains("(value * 1e3).round() / 1e3"),
            "the ratio rules moved or changed — they are measured \
             (I18nProvider-4EBrmTGg.js:46127-46128) and live in pane_layout.rs"
        );
        // And the window holds no copy of them: it sends ratios raw.
        let recording = block_after(window, "function paneNodeRecord(");
        assert!(
            !recording.contains("1e3") && !recording.contains("0.005"),
            "the window grew its own copy of the storing rules:\n{recording}"
        );

        // A worktree with no tabs stored still gets its plain first terminal —
        // and one WITH them gets them back before that terminal exists.
        let returning = block_after(window, "async function restoreActiveWorktreeTab(");
        let restore_at = returning
            .find("restoreWorktreeLayouts(")
            .expect("the restore is asked");
        let plain_at = returning
            .rfind("openTermTab()")
            .expect("the plain terminal is still there");
        assert!(
            restore_at < plain_at,
            "the plain terminal opens before the stored layouts are asked for, \
             so every restored worktree gets an extra empty tab"
        );

        // Every shape change persists through the one door, and the door is
        // shut while a restore is walking through it.
        assert!(
            block_after(window, "function renderPanes(").contains("persistPaneLayouts("),
            "layout changes stopped reaching the file"
        );
        let persisting = block_after(window, "function persistPaneLayouts(");
        assert!(
            persisting.contains("restoringPanes"),
            "a restore writes the file it is still reading:\n{persisting}"
        );
        // An agent tab travels when a leaf can be WOKEN — a session the
        // backend called resumable, restored by the agent's own resume
        // command (Orca's cold restore from its sleeping record,
        // index-ftls8Hg_.js:95637) — or, failing that, when a leaf simply
        // HELD an agent. The second arm is not a weakening of the first: a
        // pane running `zo` has no session to be called resumable about,
        // because zo wires no hook, and dropping the tab for it is what put
        // `claude` in a workspace that was running `zo`.
        assert!(
            persisting.contains("!tab.agent ||")
                && persisting.contains("paneSessions.get(term)?.resumable")
                && persisting.contains("paneAgents.has(term)"),
            "agent tabs are stored without a way back, and will restore as \
             impostors — or a tab whose agent left no session is thrown away \
             whole:\n{persisting}"
        );
        // The wake goes through `resume_session` — validated argv, launch
        // token, the session pre-seeded — and a wake that refuses falls back
        // to a plain shell rather than a hole in the layout.
        let waking = block_after(window, "async function spawnStoredLeaf(");
        assert!(
            waking.contains("wakeConversation(")
                && block_after(window, "async function wakeConversation(")
                    .contains("invoke(\"resume_session\"")
                && waking.contains("invoke(\"open_term_tab\""),
            "a sleeping conversation is no longer woken, or a failed wake \
             leaves a hole where its pane was:\n{waking}"
        );
        // And a wake that refused does not take the conversation with it.
        //
        // This one cost four workspaces. The fallback pane holds no session,
        // so the very next persist wrote a record with no `agents` at all —
        // and a conversation that existed only as a line in that file was
        // gone. One bad login erased every past this window knew about
        // ("zerocode도 빈화면으로 시작함 마지막 resume이 아니엿어"). The
        // refusal is about the machine, not the conversation.
        let refusal_at = waking
            .find("catch (error) {")
            .expect("the wake still catches its refusal");
        assert!(
            waking[refusal_at..].contains("refused = {"),
            "a refused wake forgets the conversation it was asked for:\n{waking}"
        );
        let plain_at = waking
            .find("invoke(\"open_term_tab\"")
            .expect("the fallback pane is still a plain shell");
        assert!(
            waking[plain_at..].contains("paneSessions.set(term, refused)"),
            "the pane standing in for a refused wake is stored as a bare \
             shell, which is how the record loses it:\n{waking}"
        );
        // And only sessions the backend called resumable are ever stored —
        // the record dies with the JS paneSessions check, and the file's own
        // normaliser refuses what could never wake.
        let recording = block_after(window, "function tabLayoutRecord(");
        assert!(
            recording.contains("held?.resumable"),
            "wake records are stored for sessions with no way back:\n{recording}"
        );

        // The three pane verbs are keyboard actions now — expand on Orca's
        // own default, the others shipped unbound the way Orca ships them
        // (platformBindings([]), I18nProvider-4EBrmTGg.js:80959-80990).
        assert!(
            window.contains("id: \"terminal.expandPane\"")
                && window.contains("chord: \"mod+shift+enter\""),
            "⌘⇧Enter lost its action"
        );
        for verb in [
            "terminal.equalizePaneSizes",
            "terminal.setTitle",
            "terminal.clearPaneTitle",
        ] {
            assert!(
                window.contains(&format!("id: \"{verb}\"")),
                "`{verb}` fell out of the action table — the remap panel \
                 cannot offer a key for a row that is not there"
            );
        }
    }

    /// Every road that opens a zo PANE hands it the team it will split from.
    ///
    /// zo reaches its sub-agent panes by the same fake `tmux` claude does
    /// (`zerocode_core::agent_teams::Dialect::of("zo") == Tmux`), so a zo pane
    /// launched without `open_team`'s environment has no shim on its `PATH`,
    /// no `TMUX_PANE` to cut from, and no token to present — and its `Agent`
    /// calls stay inside the process with nothing on screen to say so. The
    /// three doors are the launch, the resume, and a configured terminal
    /// command that IS zo; all three already run the generic team road, and
    /// this pins that the zo branch keeps consuming the environment it built.
    ///
    /// The LANE is deliberately absent. `open_lane` opens a zo process that is
    /// not a terminal — it has a `LaneId`, never a `TermId` — and a team's
    /// leader is a term. Handing a lane a team would name some other pane as
    /// the thing to cut.
    #[test]
    fn every_zo_pane_road_carries_the_team_its_subagents_split_from() {
        let terminal = include_str!("../../src/cmd/terminal.rs");
        let board = include_str!("../../src/cmd/board.rs");
        let project = include_str!("../../src/cmd/project.rs");

        for (source, road) in [
            (terminal, "pub(crate) fn launch_agent_tab("),
            (board, "pub(crate) fn resume_session("),
        ] {
            let there = block_after(source, road);
            let team_at = there
                .find("agent_teams::open_team(")
                .unwrap_or_else(|| panic!("{road} no longer opens a team"));
            let extended = there
                .find("env.extend(team_env.iter().cloned());")
                .unwrap_or_else(|| panic!("{road} no longer carries the team environment"));
            let zo_at = there
                .find("open_zo_pane_process(")
                .unwrap_or_else(|| panic!("{road} no longer opens a zo pane"));
            assert!(
                team_at < extended && extended < zo_at,
                "{road} opens its zo pane before the team environment reaches it"
            );
            // And that environment is the one the process is actually handed —
            // a zo pane spawned from a different vec would carry the shims in
            // a value nobody passed on.
            assert!(
                there.contains("&env,"),
                "{road} hands its zo pane an environment that is not the one it built:\n{there}"
            );
            // The record the split host reads back when a teammate is cut.
            assert!(
                there.contains("state.team_envs().insert(term, env.clone());"),
                "{road} opens a team and then forgets its environment:\n{there}"
            );
        }

        // A configured terminal command that is `zo` is a leader like any
        // other — the gate is the program, and `Dialect::of` is the one place
        // that decides which programs speak the multiplexer.
        let shell = block_after(shipped_backend(), "fn spawn_shell(");
        assert!(
            shell.contains("agent_teams::open_team(")
                && shell.contains("launch_env.extend(team_env.iter().cloned());"),
            "a configured zo terminal command no longer opens a team:\n{shell}"
        );

        // The lane road says nothing about teams, on purpose.
        let lane = block_after(project, "pub(crate) async fn open_lane(");
        assert!(
            !lane.contains("open_team("),
            "a lane has no terminal to be the leader of, so it must not open a team:\n{lane}"
        );
    }

    /// A Zo typed into a plain terminal has no launch-time channel record.
    /// The existing foreground beat must discover its pid-published identity,
    /// adopt it through the same subscriber as a lane, and release only the
    /// session claim that this pane actually won.
    #[test]
    fn a_plain_zo_process_is_adopted_by_its_published_channel() {
        let backend = shipped_backend();
        let project = include_str!("../../src/cmd/project.rs");
        let transport = include_str!("../../../zerocode-lane/src/pty_transport.rs");

        let sweeping = block_after(backend, "fn sweep_arrived_agents(app: &AppHandle) {");
        assert!(
            sweeping.contains("pty.foreground_process_id()")
                && sweeping.contains("reconcile_zo_adoptions(app, &zo_processes)"),
            "the foreground beat no longer hands a Zo pid to channel adoption:\n{sweeping}"
        );
        // The window's own Zo keeps handing over its child pid after adoption
        // too: a pid that stops arriving reads as a moved process and tears
        // the subscription — and the worker's prompt acknowledgement — down.
        assert!(
            sweeping.contains("launched_zo.contains(term)") && sweeping.contains("zo_channel_pid("),
            "a launched Zo pane no longer reports its child pid through zo_channel_pid:\n{sweeping}"
        );
        assert!(
            transport.contains("fn foreground_process_id(&self) -> Option<u32>"),
            "the type-erased terminal cannot report the foreground pid"
        );

        let adopting = block_after(backend, "fn start_zo_adoption(");
        for fact in [
            "discover_pane_channel(&runtime, pid)",
            "pane_channel_session_id(",
            "pane_sessions()",
            "orchestration::pane_session_reported(",
            "attach_zo_pane_channel(",
            "ZoChannelOwner::Term(term)",
        ] {
            assert!(
                adopting.contains(fact),
                "pid discovery no longer reaches `{fact}`:\n{adopting}"
            );
        }
        assert!(
            !adopting.contains("note_zo_pane_state("),
            "channel discovery was mistaken for the worker accepting its briefing:\n{adopting}"
        );
        let identity = adopting.find("pane_sessions()").expect("provider session");
        let ledger = adopting
            .find("orchestration::pane_session_reported(")
            .expect("ledger session report");
        let subscribe = adopting
            .find("attach_zo_pane_channel(")
            .expect("channel attach");
        assert!(
            identity < ledger && ledger < subscribe,
            "the Zo worker can receive its briefing before worker_done has a durable caller identity:\n{adopting}"
        );

        let reconciling = block_after(backend, "fn reconcile_zo_adoptions(");
        assert!(
            reconciling.contains("process_moved")
                && reconciling.contains("file_gone")
                && reconciling.contains("stream_gone")
                && reconciling.contains("detach_adopted_zo(app, term)"),
            "process, file, or stream loss no longer detaches the adopted channel:\n{reconciling}"
        );

        let attaching = block_after(project, "pub(crate) fn attach_zo_pane_channel(");
        let claim = attaching
            .find("subscribed(state.subscriptions()).insert")
            .expect("session-id claim");
        let address = attaching
            .find("state.channels().insert")
            .expect("channel address");
        let subscriber = attaching.find("spawn_subscriber(").expect("subscriber");
        assert!(
            claim < address && address < subscriber && attaching.contains("return false"),
            "a duplicate session can replace the winning address or spawn a second subscriber:\n{attaching}"
        );
    }

    /// A restored tab starts its shells when it is LOOKED at, and not before.
    ///
    /// This is Orca's §11 measured whole: the tab set is persisted per
    /// worktree and put back on activation, but a pane holds no pty until it
    /// renders — `connect()` reattaches a live session or calls `pty:spawn`
    /// (store-BgJxB0hr.js:945920), and `pendingActivationSpawn` is explicitly
    /// excluded from what is persisted. So opening a project with nine stored
    /// tabs costs nine strip entries and ONE shell. The reason it cannot be
    /// nine shells is not thrift: the other eight would be programs somebody
    /// did not ask to run again, in a checkout they have not looked at yet.
    ///
    /// The other half of the same rule is that no tab may come back as a
    /// PICTURE. The stored screen is replayed into a real shell, so what a
    /// person recognises is a terminal they can type into — never a corpse
    /// painted where a terminal used to be.
    #[test]
    fn a_restored_tab_starts_its_shells_only_when_it_is_looked_at() {
        let shipped = shipped_backend();
        let rules = include_str!("../../src/pane_layout.rs");
        let window = window_source();

        // The restore builds the strip and spawns NOTHING. Every road to a
        // shell is an `invoke`, so the absence of one in this function is the
        // whole assertion.
        let restoring = block_after(window, "async function restoreWorktreeLayouts(");
        assert!(
            restoring.contains("openStoredTab(")
                && !restoring.contains("invoke(")
                && !restoring.contains("spawnStoredLeaf(")
                && !restoring.contains("mountStoredLayout("),
            "the restore spawns shells for tabs nobody is looking at:\n{restoring}"
        );
        // A tab it builds has no shell in it and says so — the two fields a
        // live term tab is read through are both empty until the wake.
        let asleep = block_after(window, "function openStoredTab(");
        assert!(
            asleep.contains("layout: null") && asleep.contains("asleep: record"),
            "a restored tab claims shells it does not have:\n{asleep}"
        );

        // The one door from asleep to running is the stage drawing it.
        assert!(
            block_after(window, "function updateStage(").contains("wakeStoredTab("),
            "nothing starts a restored tab when it comes on screen — it would \
             sit on the strip forever with an empty leaf"
        );
        let waking = block_after(window, "async function wakeStoredTab(");
        assert!(
            waking.contains("mountStoredLayout(") && waking.contains("persistPaneLayouts("),
            "a woken tab never tells the file which shells it holds, so the \
             exit capture cannot find its screens:\n{waking}"
        );

        // And the wake spawns BEFORE it paints: the shells are made, the
        // stored screen is replayed into them, and only then does the tab
        // draw. A paint that ran first would be the dead screen this rule
        // exists to forbid.
        let mounting = block_after(window, "async function mountStoredLayout(");
        let spawn_at = mounting.find("spawnStoredLeaf(").expect("the leaves spawn");
        let paint_at = mounting.find("renderPanes(").expect("the tab paints");
        assert!(
            spawn_at < paint_at && mounting.contains("grid, restore)"),
            "a restored tab paints before its shells exist:\n{mounting}"
        );

        // Opening the window goes through the workspace's own road, which is
        // what makes the set come back at all — straight to `openTermTab` and
        // a restart silently drops every tab a person had open.
        let booting = block_after(window, "async function boot(");
        assert!(
            booting.contains("restoreActiveWorktreeTab()"),
            "boot opens a bare terminal instead of the workspace's own tabs"
        );

        // A tab still asleep goes back to the file exactly as it came. Built
        // from the tab instead, it would be recorded as an empty one — and a
        // save is the whole set, so the first shape change of a session would
        // close, on disk, every tab nobody had clicked on yet.
        let recording = block_after(window, "function tabLayoutRecord(");
        assert!(
            recording.contains("if (tab.asleep) return"),
            "a sleeping tab is written from the tab rather than from its \
             record:\n{recording}"
        );
        assert!(
            block_after(window, "function persistPaneLayouts(").contains("tab.asleep ||"),
            "a restored agent tab is dropped from the file for having no live \
             session — which is every agent tab nobody has opened yet"
        );

        // The screens follow the tab's NAME through a save, never its
        // position: a sleeping tab has no shells to serialise, and the tabs
        // around it are closed and pinned to the front while it waits.
        assert!(
            block_after(rules, "pub fn store(")
                .contains("held.iter().find(|one| one.id == Some(id))"),
            "a save wipes the stored screens of every tab still asleep"
        );
        assert!(
            block_after(shipped, "fn replay_stored_screen(")
                .contains("layout.id == Some(screen.id)"),
            "the replay finds a tab by counting, so a closed tab hands its \
             last screen to whichever tab took its seat"
        );
    }

    /// Opening a workspace starts the agent somebody chose — unless what that
    /// workspace stored was a conversation.
    ///
    /// Orca's initial terminal for a workspace IS the default agent: the
    /// activation carries `sequencedStartup.launchAgent`, and the quick road
    /// that fills it resolves `pickQuickWorkspaceAgent(settings.defaultTuiAgent,
    /// detected, disabled)` → `pickTuiAgent` (store-BgJxB0hr.js:59131 — the
    /// preferred agent when it is actually detected, `blank` meaning a plain
    /// shell). It creates that terminal only for a workspace showing no tabs
    /// (`shouldAutoCreateInitialTerminal(count) => count === 0`,
    /// worktree-activation-C2aVGSrf.js:4106) — and the tabs it comes back to
    /// are the running programs themselves, reattached, so nobody there ever
    /// lands on a bare shell where an agent belonged. Ours re-spawns from a
    /// record, so a record of nothing but bare shells restored bare shells
    /// and the default agent was never reached at all. That is the reported
    /// break, and it is a wiring order, not a missing feature: `openTermTab`
    /// has honoured the setting since 1-di.
    ///
    /// The fix is asymmetric and the asymmetry is the whole gate. A stored
    /// CONVERSATION is a thing somebody said — it wins, always. A stored
    /// plain shell is a shape, and a shape yields to the agent that was
    /// chosen. With 자동 chosen there is nothing to yield TO, so the stored
    /// shells come back exactly as before. Either half alone is a product:
    /// one that loses conversations, or one that never fixes the report.
    ///
    /// Both halves are pinned as contiguous blocks assembled here at run time
    /// (1-cv/1-da): the judgment is called by the browser suite, which is the
    /// better test of a rule, and what this gate holds is the WIRING that
    /// rule hangs on — three arms one keystroke apart from each other.
    #[test]
    fn a_workspace_opens_on_the_agent_it_was_told_to() {
        let window = window_source();

        // The judgment, whole. Bounded by the tree's own leaf count because
        // `mountStoredLayout` reads wakes by ordinal and stops there — an
        // `agents` entry past the last leaf is one nothing would ever wake,
        // and counting it would make a workspace of plain shells look like
        // somebody's conversation and keep the agent off the screen forever.
        let judging = [
            "  return records.some((record) => {",
            "    const wakes = record?.agents;",
            "    const ran = record?.running;",
            "    if (!wakes && !ran) return false;",
            "    const leaves = recordLeafCount(record.root);",
            "    for (let at = 0; at < leaves; at += 1) {",
            "      if (wakes?.[at]?.agent || ran?.[at]) return true;",
            "    }",
            "    return false;",
            "  });",
        ]
        .join("\n");
        let judgment = block_after(window, "function storedLayoutsHoldProgram(records) {");
        assert!(
            judgment.contains(&judging),
            "the rule that decides whether a stored set holds a program is \
             no longer the leaf-bounded walk the mount performs — a \
             workspace either loses what somebody said, or never opens on the \
             agent it was told to:\n{judgment}"
        );
        // And it decides from the RECORDS. A judgment that had to look at the
        // stage could not be asked before the stage is built, which is
        // exactly when this question is asked.
        assert!(
            !judgment.contains("document.") && !judgment.contains("invoke("),
            "the judgment reads something other than the records it was \
             handed:\n{judgment}"
        );

        // The wiring, whole: read the stored set once, ask the rule, and let
        // a set of nothing but plain shells step aside for the chosen agent.
        // Every arm is one keystroke from a different product — dropping
        // `storedLayoutsHoldProgram` restores over a conversation,
        // dropping `defaultAgentChosen` puts an unasked-for shell where 자동
        // means the terminal command, and dropping `stored.length > 0` makes
        // a workspace that stored nothing skip a restore it was never going
        // to do — so the block travels as one.
        let wiring = [
            "  const stored = await storedPaneLayouts(activeWorktreePath);",
            "  const yieldsToDefaultAgent =",
            "    stored.length > 0 && !storedLayoutsHoldProgram(stored) \
             && defaultAgentChosen();",
            "  if (!yieldsToDefaultAgent) {",
            "    if (await restoreWorktreeLayouts(activeWorktreePath, stored)) {",
            "      settleRestoredStage();",
            "      return;",
            "    }",
            "    if (docsRestored) {",
            "      settleRestoredStage();",
            "      return;",
            "    }",
            "  }",
        ]
        .join("\n");
        let restoring = block_after(
            window,
            "async function restoreActiveWorktreeTab({ firstTerminal = true } = {}) {",
        );
        assert!(
            restoring.contains(&wiring),
            "workspace activation no longer weighs its stored terminals \
             against the default agent — a workspace of plain shells never \
             opens on the agent that was chosen, or a sleeping conversation \
             is thrown away for one:\n{restoring}"
        );

        // The documents are not part of the bargain: the stage comes back
        // first and unconditionally, and only the TERMINALS ever yield.
        let stage = restoring
            .find("const docsRestored = await restoreStageLayout(activeWorktreePath);")
            .expect("the stage is still restored");
        assert!(
            stage < restoring.find("const stored =").unwrap_or(0),
            "the documents were folded into the terminal decision — a \
             workspace can now open without the files somebody left \
             open:\n{restoring}"
        );

        // One spelling of "an agent was chosen", asked by both doors: what a
        // new terminal starts, and whether stored shells give way. Two
        // spellings drift, and the drift is a window that yields the shells
        // and then opens a plain one.
        let chosen = block_after(window, "function defaultAgentChosen() {");
        assert!(
            chosen.contains("return defaultAgentId() !== null;"),
            "the typed default-agent choice no longer distinguishes an agent \
             from 자동 and 에이전트 없음:\n{chosen}"
        );
        let opening = block_after(
            window,
            "async function openTermTab({ placement, door = \"agent\" } = {}) {",
        );
        // ACTIVATION starts the chosen agent — the door named `agent`, which
        // is the one the original stands an agent up on. The three terminal
        // doors do not, and the pin that holds that line is
        // [`the_terminal_doors_open_terminals_and_only_activation_seats_an_agent`].
        assert!(
            opening.contains("if (door === \"agent\" && defaultAgentChosen()) {")
                && opening.contains("launchAgentTab({")
                && opening.contains("|| defaultAgent.kind === \"blank\""),
            "activation no longer seats the chosen agent through the launch \
             door:\n{opening}"
        );
        assert_canonical_setting_round_trip(
            shipped_backend(),
            window,
            "set_default_agent",
            "setting_key::DEFAULT_AGENT",
            "settings.default_agent = preference;",
            "async function chooseDefaultAgent(",
            "default_agent",
            "defaultAgent = normalizeDefaultAgent(snapshot.default_agent);",
        );
    }

    /// A workspace comes back because nobody has put it back yet — not
    /// because nothing is standing in it.
    ///
    /// 재시작 뒤 한 체크아웃의 클로드 판이 죽은 채 돌아오지 않았다. 기록은
    /// 남아 있었고(`pane-layouts.json`에 그 대화의 wake가 그대로 있었다) 대화도
    /// 디스크에 살아 있었다. 잃은 자리는 하나였다: 저장된 세트에서 판으로 가는
    /// 유일한 길(`restoreActiveWorktreeTab` → `restoreWorktreeLayouts`)이 「이
    /// 체크아웃에 탭이 하나라도 있으면」 파일을 읽지도 않고 돌아섰고, 재시작
    /// 복원이 원장 워커를 그 체크아웃에 먼저 앉혀 두었기 때문에 그 문장에
    /// 걸렸다. 그리고 그 워크트리의 다음 저장이 — 원장 소유 탭을 걸러 낸 —
    /// 빈 세트를 쓰면서, 읽히지도 않은 기록을 지웠다.
    ///
    /// 3단계에서 원장 쪽에 잡은 결함 둘이 여기 그대로 다시 열려 있었다. 판
    /// 이름 재사용의 원장 밖 짝은 term id가 아니라 **세션 id**이고(term은
    /// 재사용되지 않는다), durable 한 기록보다 먼저 이어받는 것의 짝은 원장
    /// 워커가 아직 읽히지 않은 pane-layouts 기록보다 먼저 워크트리를 차지하는
    /// 것이다. 방어를 두 벌 두지 않는다: 되살릴지 말지는 여전히
    /// `restoreActiveWorktreeTab` 한 곳에서 나고, 한 대화가 이미 서 있는지는
    /// 백엔드의 `conversation_wake` 한 곳에서 난다.
    #[test]
    fn a_workspace_the_ledger_seated_still_reads_its_own_stored_set() {
        let window = window_source();
        let restoring = block_after(
            window,
            "async function restoreActiveWorktreeTab({ firstTerminal = true } = {}) {",
        );

        // 「탭이 있다」와 「이 창이 이 워크트리를 이미 세웠다」는 서로 다른
        // 사실이다. 하나가 다른 하나를 대신 답하면 그 자리에서 대화가 사라진다.
        assert!(
            restoring.contains("if (target && restoredWorkspaces.has(worktree)) {")
                && restoring.contains("restoredWorkspaces.add(worktree);"),
            "a checkout that already holds a tab skips its own stored set \
             again — the conversation stored for it is never read, and the \
             next save writes it away:\n{restoring}"
        );

        // 그리고 세트가 아무것도 돌려주지 않았을 때에도, 이미 일하고 있는 판
        // 위에 두 번째 터미널을 얹지 않는다.
        let seated_at = restoring
            .rfind("  if (target) {")
            .expect("a workspace something else seated is still answered by that tab");
        let plain_at = restoring
            .rfind("openTermTab()")
            .expect("the plain terminal is still there");
        assert!(
            seated_at < plain_at,
            "opening a checkout the ledger seated a worker in stacks a second \
             terminal on top of it:\n{restoring}"
        );

        // 원장이 판을 이어받는 그 순간, 일반 세트는 그 판을 놓는다. 놓지 않으면
        // 파일이 원장 소유가 된 대화를 계속 이름하고, 다음 재시작이 그 하나를
        // 파일에서 한 번·원장에서 한 번 되살린다.
        // The seating body is shared with a pane following its own process
        // (t-3612): `seatLedgerManagedTerm` names the ledger's extras and
        // `reseatTerm` does the moving, persistence included.
        let seating = block_after(window, "function reseatTerm(term, extra) {");
        assert!(
            seating.contains("persistPaneLayouts(worktree);"),
            "a tab the ledger adopted stays in the generic stored set, so one \
             conversation comes back twice:\n{seating}"
        );

        // 한 대화에 한 판, 그리고 그 판정은 한 곳에서 난다 — 백엔드의
        // `conversation_wake`가 `resume_session` 길에서 한 번(단위 계약
        // `a_resume_is_judged_before_anything_of_the_wake_happens`). 창은 그
        // 사본을 들지 않는다: 문마다 들었던 사본은 서로의 진행 중 wake를 보지
        // 못했고, 사이드바 행이 제 활성화가 깨우던 zo 대화에 두 번째
        // `zo --resume`을 세웠다(2026-09-16). 창의 문들은 한 함수로 답을 듣는다.
        let hearing = block_after(window, "async function wakeConversation(");
        assert!(
            hearing.contains("invoke(\"resume_session\"")
                && hearing.contains("if (!woke.standing) paneSessions.set("),
            "a door hears the backend's answer somewhere else, or a pane it did \
             not open is written down as its own:\n{hearing}"
        );
        // 사이드바의 두 행은 한 문을 지나고, 그 문은 제 활성화가 시작한 복원이
        // 끝난 뒤에 묻는다 — 답이 가리키는 판이 탭에 서 있어야 갈 수 있다.
        let reopening = block_after(window, "async function reopenConversationIn(path, known) {");
        let settled = reopening
            .find("storedWakesSettled(path)")
            .expect("the door asks before the restore it started has landed");
        let asked = reopening
            .find("resumeSession(known)")
            .expect("the door no longer opens through the judged road");
        assert!(
            reopening.contains("activateWorktree(path)") && settled < asked,
            "a sidebar row for an absent conversation opens it in the wrong \
             checkout, or asks while its own restore is still waking it:\n{reopening}"
        );
        for row in [
            "function makeSurvivorRow(one) {",
            "function makeRetainedRow(path, row) {",
        ] {
            assert!(
                block_after(window, row).contains("reopenConversationIn("),
                "a sidebar row grew its own door:\n{}",
                block_after(window, row)
            );
        }
        // 「서 있다」는 답은 그 판으로 간다 — 탭 메뉴의 「이 대화 다시 열기」도.
        let going = block_after(window, "async function resumeSession(known) {");
        let standing_at = going
            .find("if (woke.standing) {")
            .expect("a door no longer tells an opened pane from a standing one");
        let mounted_at = going
            .find("mountTermTab(")
            .expect("an opened pane still gets a tab");
        assert!(
            going.contains("wakeConversation(")
                && going.contains("focusAgentPane(")
                && standing_at < mounted_at,
            "a conversation already standing is mounted as a second tab, or \
             no longer gone to:\n{going}"
        );

        // 깨우기를 거부당한 대화는 소리를 낸다. 화면이 조용하면 「이어서」는
        // 그냥 안 된 것으로 보이고, 다음 조사는 시작할 자리가 없다.
        let waking = block_after(window, "async function spawnStoredLeaf(");
        assert!(
            waking.contains("showError(") && waking.contains("\"session.wakeRefused\""),
            "a wake that refused is still only a console line:\n{waking}"
        );
    }

    /// A repository wears the colour mark it was given — and nothing else wears
    /// one at all.
    ///
    /// Orca keeps `repoBadgeColor` per repository and draws it as `RepoBadgeMark`
    /// beside the name (`block size-1.5 shrink-0`, an inline `backgroundColor`;
    /// `index-ftls8Hg_.js:23489`), out of an eight-colour palette whose first
    /// entry is a neutral grey (`REPO_COLORS`, `I18nProvider-4EBrmTGg.js:23340`).
    ///
    /// The RULE — what counts as a colour — is a pure function with its own
    /// behaviour tests in `zerocode-core::repo_mark`, which is where a rule
    /// belongs (1-cv). What this gate holds is the three pieces of wiring around
    /// it, each of which is one line away from a different product:
    ///
    ///   1. **Two lists of eight colours** — the core's and the window's. They
    ///      cannot be compared by count: swapping a colour for another keeps
    ///      the count and makes the picker offer a swatch the backend has never
    ///      heard of.
    ///   2. **The save reads the value through the normaliser.** A command that
    ///      stored `color` as it arrived would put `#ABC` — or a string that is
    ///      not a colour at all — in the file, where the picker can never match
    ///      it against a swatch again and the sidebar paints nothing.
    ///   3. **An unmarked repository draws NO square.** Orca resolves an absent
    ///      colour to the neutral grey before drawing (`resolveRepoBadgeColor`);
    ///      we deliberately do not carry that, because a grey square on all
    ///      eleven rows is eleven marks that mean nothing. The default must not
    ///      creep back in on either side of the wire — so the backend is held to
    ///      naming no colour at all, and the window's paint to hiding the square
    ///      rather than filling it.
    ///
    /// Every needle is assembled here at run time so that no line of this test
    /// is byte-identical to the shipped line it is watching (1-cv/1-da).
    #[test]
    fn a_repository_wears_only_the_mark_it_was_given() {
        let window = window_source();
        let styles = include_str!("../../../../ui/shell.css");
        let backend = shipped_backend();
        let core = include_str!("../../../zerocode-core/src/repo_mark.rs");
        let (shipped, _) = backend.split_once("#[cfg(test)]").unwrap_or((backend, ""));
        let (rules, _) = core.split_once("#[cfg(test)]").unwrap_or((core, ""));

        /// The `"#rrggbb"` strings inside one array literal, in order.
        fn colours(source: &str, opens: &str) -> Vec<String> {
            let listed = source
                .split_once(opens)
                .map(|(_, rest)| rest.split_once("];").map_or(rest, |(inside, _)| inside))
                .unwrap_or_else(|| panic!("`{opens}` is gone"));
            listed
                .lines()
                .filter_map(|line| line.trim().strip_prefix('"'))
                .filter_map(|rest| rest.split_once('"').map(|(colour, _)| colour.to_string()))
                .collect()
        }

        // 1. One palette, spelled twice, in one order. The window keeps a copy
        // so a menu opening under the pointer has its swatches in the first
        // frame; this is what keeps the copy honest.
        let held = colours(rules, "pub const REPO_MARK_PALETTE");
        let offered = colours(window, "const REPO_MARK_COLORS = [");
        assert_eq!(held.len(), 8, "the core palette is no longer eight colours");
        assert_eq!(
            held, offered,
            "the window's palette and the core's have drifted — the picker \
             offers a colour the rest of the product does not know, or has \
             stopped offering one somebody has already marked a repository with"
        );

        // 2. The save reads what it was handed through the normaliser, and
        // refuses what is not a colour rather than storing it or dropping it.
        let saving = block_after(shipped, "fn set_repo_mark(");
        let reading = [
            "    let mark = match color.as_deref() {".to_string(),
            format!(
                "        Some(said) => match zerocode_core::{}(Some(said)) {{",
                "normalize_repo_mark"
            ),
            "            Some(colour) => Some(colour),".to_string(),
            "            None => {".to_string(),
        ]
        .join("\n");
        assert!(
            saving.contains(&reading),
            "the repository mark is no longer read through the normaliser — a \
             value that is not a colour, or one spelled a second way, now \
             reaches the file:\n{saving}"
        );
        assert!(
            saving.contains(&format!("entry.{} = mark;", "mark_color")),
            "the mark that is stored is no longer the normalised one:\n{saving}"
        );
        assert!(
            saving.contains(&format!("return {}(", "Err")),
            "an unreadable colour no longer refuses — the person who asked for \
             a mark watches it fail to appear with no word about why:\n{saving}"
        );

        // The mark shares its stored entry with this machine's script settings
        // and with what that repository says about external worktrees. This gate
        // used to pin one carry-forward line — the mark being read out and put
        // back around a save that replaced the whole record. That shape is the
        // bug: every field added since would have needed its own line, and the
        // one that got forgotten would empty somebody's sidebar. What is pinned
        // now is that no writer of this map replaces the record at all, which is
        // the guarantee the line was standing in for.
        let script_policy = block_after(shipped, "fn set_project_script_policy(");
        assert!(
            script_policy.contains("update_project_script_policy("),
            "the policy command bypasses the keyed script migration writer:\n{script_policy}"
        );
        for (name, opens) in [
            ("mark", "fn set_repo_mark("),
            ("visibility", "fn set_external_worktree_visibility("),
            ("added-at", "fn note_project("),
        ] {
            let writing = block_after(shipped, opens);
            assert!(
                writing.contains(&format!("{}(", "update_project_settings")),
                "the {name} save no longer goes through the one writer, so it can \
                 erase a field it has never heard of:\n{writing}"
            );
            assert!(
                !writing.contains(&format!("{} {{", "ProjectSettings")),
                "the {name} save builds a whole record again — every per-project \
                 field this save does not name is about to be thrown \
                 away:\n{writing}"
            );
        }
        // The date a project joined the list is stamped ONCE, and only for a
        // project the list has never held. `note_project` runs at every boot, so
        // an unconditional stamp dates TODAY the project somebody has had open
        // for months — and a project dated after the visibility rollout hides
        // its external worktrees by default, which is precisely the sidebar this
        // date exists to keep full. There is no unit test behind this: reaching
        // it means writing into `$HOME`, and this file's tests do not move the
        // environment out from under each other. So the guard is pinned as a
        // contiguous block, with its two halves — the "never held" question and
        // the write it gates.
        let noting = block_after(shipped, "fn note_project(");
        let once = [
            "    let listed = root.to_string_lossy().into_owned();",
            "    if !known.iter().any(|held| held == &listed) {",
            "        let at = now_epoch_ms();",
            "        let _ = update_project_settings(repository, &project_settings_key(&listed), |entry| {",
            "            entry.added_at = Some(at);",
            "        });",
            "    }",
        ]
        .join("\n");
        assert!(
            noting.contains(&once),
            "the join date is no longer written once for a project nobody has \
             seen before — a project somebody has had open for months is about \
             to be dated today, and dated today it hides its own \
             worktrees:\n{noting}"
        );

        // And the one writer takes an entry that says nothing back out, so an
        // erase leaves no trace rather than a `{}` that reads as an opinion.
        let writer = block_after(shipped, "fn update_project_settings(");
        assert!(
            writer.contains(&format!("if entry.{}() {{", "says_nothing"))
                && writer.contains("held.remove(root);"),
            "an emptied entry now stays in the file as an opinion nobody \
             gave:\n{writer}"
        );

        // And the read side normalises too, because the file can be edited by
        // hand: a colour typed there in three digits has to reach the picker in
        // the six the palette is spelled in.
        let holding = block_after(shipped, "fn stored_repo_marks(");
        assert!(
            holding.contains(&format!("zerocode_core::{}(", "normalize_repo_mark")),
            "marks are read out of the file unnormalised, so a hand-written \
             one can never match a swatch:\n{holding}"
        );

        // The catalog carries what was stored and invents nothing. A colour
        // named ANYWHERE in the backend would be a default waiting to be
        // painted onto a repository that never chose it.
        let listing = block_after(shipped, "fn project_catalog(");
        assert!(
            listing.contains(&format!("{}(state.settings())", "stored_repo_marks"))
                && listing.contains(&format!("{}: marks.get(&listed).cloned(),", "mark_color")),
            "the sidebar catalog no longer carries each repository's stored \
             mark:\n{listing}"
        );
        for colour in &held {
            assert!(
                !shipped.contains(colour.as_str()),
                "the backend names `{colour}` — a repository nobody marked is \
                 about to be given a colour it never chose"
            );
        }

        // 3. The paint: the square is hidden for a repository with no mark, and
        // the colour arrives as an inline custom property rather than as style
        // injected into the document.
        let painting = block_after(window, "function makeProjectHeader(project) {");
        let drawing = [
            "  const mark = row.querySelector(\".proj-mark\");".to_string(),
            format!("  const marked = project.{} ?? null;", "mark_color"),
            "  mark.hidden = !marked;".to_string(),
            format!(
                "  if (marked) mark.style.setProperty(\"--{}\", marked);",
                "repo-mark"
            ),
        ]
        .join("\n");
        assert!(
            painting.contains(&drawing),
            "the repository row no longer draws exactly the mark it was given — \
             either an unmarked repository has been handed a default colour, or \
             a marked one has stopped showing its own:\n{painting}"
        );
        for colour in &held {
            assert!(
                !painting.contains(colour.as_str()),
                "the repository row names `{colour}` itself, which is a default \
                 by another spelling"
            );
        }

        // The stylesheet holds the box and no colour: 6px is Orca's `size-1.5`,
        // and the absence of a `display` is what lets `hidden` do its work.
        let square = block_after_css(styles, ".proj-mark {");
        assert!(
            square.contains("width: 6px;") && square.contains("height: 6px;"),
            "the mark is no longer the measured 6px square:\n{square}"
        );
        assert!(
            square.contains(&format!("background: var(--{});", "repo-mark")),
            "the mark's colour no longer comes from the property the paint \
             sets:\n{square}"
        );
        assert!(
            !square.contains("display:"),
            "the mark rule took a `display`, which beats the user-agent rule \
             behind `hidden` — every unmarked repository now shows an empty \
             square:\n{square}"
        );

        // The picker offers the palette and the way back out of it. The clear
        // cell sends `null`, which is the one value the command reads as an
        // erase, and it is the pressed cell when there is no mark — so the
        // strip always shows exactly one answer.
        let strip = block_after(window, "function makeRepoMarkStrip(path, current) {");
        let cells = [
            "  for (const colour of REPO_MARK_COLORS) {".to_string(),
            "    const cell = document.createElement(\"button\");".to_string(),
        ]
        .join("\n");
        assert!(
            strip.contains(&cells),
            "the picker no longer walks the palette, so it offers colours of \
             its own:\n{strip}"
        );
        assert!(
            strip.contains(&format!("current === colour ? \"{}\" : \"false\"", "true"))
                && strip.contains(&format!("current ? \"false\" : \"{}\"", "true")),
            "the picker no longer says which cell this repository is wearing, \
             or says it of two cells at once:\n{strip}"
        );
        assert!(
            strip.contains(&format!("void setRepoMark(path, {});", "null")),
            "the cell that clears the mark no longer sends the erase:\n{strip}"
        );

        // And the two doors into it: the menu builds the strip, and the
        // repository menu asks for one with that repository's current answer.
        let menu = block_after(
            window,
            "function openSidebarMenu(x, y, items, opener = null) {",
        );
        assert!(
            menu.contains(&format!("{}(item.marks", "makeRepoMarkStrip")),
            "the sidebar menu can no longer draw a mark picker:\n{menu}"
        );
        let asking = block_after(window, "function projectMenuAt(x, y, path = null) {");
        assert!(
            asking.contains(&format!(
                "marks: project.path, mark: project.{}",
                "mark_color"
            )),
            "the repository menu no longer offers the mark picker, or offers it \
             without saying which mark is already on:\n{asking}"
        );
    }

    /// The vault browses somebody's conversation history. It must never be able
    /// to damage it.
    ///
    /// The strongest form of that promise is that no writer exists to call, so
    /// this asserts by ABSENCE — under every plausible name a writer would wear —
    /// rather than by checking that the writers we have are careful. A gate that
    /// checked carefulness would pass the day somebody adds a careless one.
    #[test]
    fn the_vault_can_read_a_transcript_and_never_change_one() {
        let shell = shipped_backend();
        let (shipped, _) = shell.split_once("#[cfg(test)]").unwrap_or((shell, ""));
        let core = include_str!("../../../zerocode-core/src/vault.rs");
        let (rules, _) = core.split_once("#[cfg(test)]").unwrap_or((core, ""));
        let window = window_source();

        for absent in [
            "fn write_vault",
            "fn save_vault",
            "fn delete_vault",
            "fn rename_vault",
            "fn prune_vault",
            "fn clear_vault",
            "fn archive_vault",
        ] {
            assert!(
                !shipped.contains(absent),
                "`{absent}` exists — the vault reads a vendor's record of somebody's \
                 work, and a writer here can destroy conversations this product did \
                 not create"
            );
        }
        // And the rules module touches nothing either. Named calls rather than
        // the word "write", because the module's prose says "nothing writes".
        for absent in [
            "fs::write",
            "fs::remove_file",
            "fs::remove_dir",
            "fs::rename",
            "fs::create_dir",
            "OpenOptions",
        ] {
            assert!(
                !rules.contains(absent),
                "zerocode_core::vault calls `{absent}` — the scan is read-only, and \
                 a cache written beside a session store is still a write into it"
            );
        }
        // The window asks for nothing of the sort.
        assert!(
            !window.contains("invoke(\"delete_vault") && !window.contains("invoke(\"write_vault"),
            "the vault panel asks to change a session"
        );

        // The reveal is bounded, canonicalised on both sides, and bounded BY THE
        // DISCOVERY TABLE — so an agent added to the vault is revealable without
        // a second list to keep in step, and a path from the webview cannot walk
        // out of a root that textually contains it.
        let revealing = block_after(shipped, "fn reveal_vault_session(");
        assert!(
            revealing.contains("is_file()")
                && revealing.contains("canonicalize()")
                && revealing.contains("vault::AGENT_SOURCES")
                && revealing.contains("real.starts_with(root)"),
            "the vault's reveal is not bounded to the session stores by canonical \
             path:\n{revealing}"
        );
        // One agent's card names a DATABASE rather than a transcript, and that
        // file stands in a data directory no session root contains. Without it
        // in the bound, the reveal refuses the only card it cannot be wrong
        // about — the path came from the row, not from a walk.
        assert!(
            revealing.contains("opencode_home::data_dirs()"),
            "the reveal does not know where OpenCode's database lives, so the \
             one agent whose sessions are rows cannot be revealed:\n{revealing}"
        );

        // The panel has two readers and the database one has no root to be
        // walked into, so it is called by name here or its sessions do not
        // exist. This machine's own file holds 86 of them.
        let scanning = block_after(shipped, "async fn vault_sessions(");
        assert!(
            scanning.contains("vault_opencode_scan::scan(limit)")
                && scanning.contains("vault::merge(walked, found.sessions, limit)"),
            "the vault stopped reading OpenCode's database, or stopped merging \
             it into the same limit as the walked stores:\n{scanning}"
        );
        // And that walk is paid for ONCE. Fourteen directory trees and a
        // database, on a surface that re-asks on every keystroke: what is held
        // is consulted before anything reads the disk, and only the reload
        // button refuses it.
        let spot = |needle: &str| {
            scanning
                .find(needle)
                .unwrap_or_else(|| panic!("`{needle}` is gone from `vault_sessions`"))
        };
        assert!(
            spot("vault_walk::kept(force)") < spot("vault::scan(&home, limit)")
                && scanning.contains("vault_walk::keep(walk.clone())"),
            "the vault reads the disk without asking what it already has, or \
             reads it and keeps nothing — either way a keystroke costs fourteen \
             directory trees:\n{scanning}"
        );
        // The resume base is a SETTING, and settings are re-read per call.
        // Written into the walk that gets kept instead, a launch override
        // somebody edits would need a reload before a card believed it.
        assert!(
            spot("vault_walk::keep(walk.clone())") < spot("resume_command_with_base"),
            "the resume base is baked into the kept walk, so a settings change \
             stops reaching the cards:\n{scanning}"
        );
        // Both surfaces say which they are asking for, and only the two reload
        // buttons ask for a walk. `force` has no default on the command: a
        // caller that forgot it does not compile.
        assert_eq!(
            window.matches("force: force === true,").count(),
            2,
            "a vault surface asks without saying whether it wants the disk read \
             again"
        );
        assert!(
            window.contains("refreshVault(true)") && window.contains("refreshVaultDock(true)"),
            "a reload button stopped asking for a new walk, so the button whose \
             whole job is to notice a conversation that started a minute ago \
             cannot"
        );
        // One resolver, two surfaces. The panel sent `[]` on every call for as
        // long as it existed while the docked list had all three scopes wired —
        // the same backend filter reachable from the small surface and not from
        // the big one. A second copy of the resolution is how the two drift, and
        // the copy that was here read a global its caller had to set and put
        // back to ask about a scope it was not in.
        assert!(
            window.contains("function vaultScopePaths(scope)")
                && !window.contains("function vaultDockScopePaths("),
            "the vault's two surfaces resolve a scope separately"
        );
        assert_eq!(
            window.matches("scope_paths: asked.paths,").count(),
            2,
            "a vault surface sends a scope it did not resolve — a scope that \
             points nowhere reaches the backend as \"everywhere\" while the \
             control still says otherwise"
        );
        // Both database readers go through the one opener, and that opener is
        // the read-only promise in code. A second `open_with_flags` anywhere is
        // a connection somebody can forget to make read-only — on a file that
        // holds a person's whole history of talking to an agent.
        let opener = include_str!("../../src/sqlite_read.rs");
        assert!(
            opener.contains("SQLITE_OPEN_READ_ONLY")
                && opener.contains(r#"pragma_update(None, "query_only", true)"#),
            "the shared opener no longer refuses writes"
        );
        for (name, reader) in [
            ("vault", include_str!("../../src/vault_opencode_scan.rs")),
            (
                "ledger",
                include_str!("../../src/usage_stats_opencode_scan.rs"),
            ),
        ] {
            let (using, _) = reader.split_once("#[cfg(test)]").unwrap_or((reader, ""));
            assert!(
                using.contains("sqlite_read::open_read_only") && !using.contains("open_with_flags"),
                "the {name} reader opens OpenCode's database itself instead of \
                 through the read-only opener"
            );
        }

        // The resume runs a command the BACKEND built. A window that could hand
        // over an arbitrary string would have a shell on this channel.
        let resuming = block_after(shipped, "fn resume_vault_session(");
        assert!(
            resuming.contains("vault::resume_command_with_base(&session, base.as_deref())")
                && resuming.contains(".filter(|sent| *sent == expected)"),
            "the vault resumes a command it did not build itself:\n{resuming}"
        );

        // The walk is bounded three ways and does not follow links, because these
        // directories are not ours and a link in one is not hypothetical.
        let walking = block_after(rules, "fn walk(");
        assert!(
            walking.contains("depth > MAX_DEPTH")
                && walking.contains("found.len() >= MAX_CANDIDATE_FILES")
                && walking.contains("symlink_metadata")
                && walking.contains("is_symlink()"),
            "the session walk lost a bound or started following links:\n{walking}"
        );
        assert!(
            block_after(rules, "fn read_head(").contains("MAX_HEAD_BYTES"),
            "a session file is read whole — a long conversation is megabytes and \
             there are two hundred cards"
        );
    }

    /// A session card dragged onto a workspace continues INSIDE that workspace.
    ///
    /// Four things have to hold together, and each of them is a different way
    /// for this gesture to look like it worked and not have:
    ///
    /// - The dropped workspace outranks the session's own directory. Ignore it
    ///   and the drop is decoration: the card lands, a terminal opens, and the
    ///   agent reads the tree it was already reading.
    /// - The path is resolved through the catalog. A webview that could name a
    ///   working directory could start an agent anywhere on this disk, which is
    ///   the rule every other path command in this file follows.
    /// - The resolved workspace reaches the COMMAND too. The resume line opens
    ///   with a `cd`, so a shell started in the dropped workspace and handed a
    ///   command that walks back out of it has moved nothing.
    /// - And the ORDER survives: the window's string is checked against the one
    ///   this side builds before anything is spawned.
    ///
    /// Every needle is assembled at run time, so this gate's source is not a
    /// copy of the lines it guards (1-cy).
    #[test]
    fn a_session_dropped_on_a_workspace_continues_inside_it() {
        let backend = shipped_backend();
        let (shipped, _) = backend.split_once("#[cfg(test)]").unwrap_or((backend, ""));
        let window = window_source();
        let sheet = include_str!("../../../../ui/shell.css");

        let resuming = block_after(shipped, "fn resume_vault_session(");

        // 1. The named workspace goes through the catalog, exactly once.
        let through_the_catalog = [
            "    let dropped = match worktree {",
            "        Some(requested) => Some(",
            "            match known_workspace_context(state.config_root(), &requested)? {",
            "                KnownWorkspace::Git(_, chosen) => chosen.path,",
            "                KnownWorkspace::Folder(folder) => folder,",
            "            },",
            "        ),",
            "        None => None,",
            "    };",
        ]
        .join("\n");
        assert!(
            resuming.contains(&through_the_catalog),
            "a resume takes the webview's word for where to start a shell:\n{resuming}"
        );
        assert_eq!(
            resuming.matches("known_workspace_context(").count(),
            1,
            "the drop target is resolved more than once, and two answers to \
             where a session reopens is two products:\n{resuming}"
        );

        // 2. The order is the core rule's, argument for argument: dropped
        //    workspace, then the session's directory, then this window's root.
        let in_order = [
            "    let root = std::path::PathBuf::from(zerocode_core::vault::resume_root(",
            "        target.as_deref(),",
            "        session.cwd.as_deref(),",
            "        &here,",
            "        |path| std::path::Path::new(path).is_dir(),",
            "    ));",
        ]
        .join("\n");
        assert!(
            resuming.contains(&in_order),
            "the dropped workspace no longer outranks the directory the session \
             ran in, so a drop reopens somewhere else:\n{resuming}"
        );
        assert_eq!(
            shipped.matches("vault::resume_root(").count(),
            1,
            "a second place decides where a resumed session stands"
        );
        // And the shape that only ever knew the session's own directory is gone
        // rather than left beside the new one.
        let only_the_session = [".filter(|path| path.", "is_dir())"].concat();
        let only_the_root = ["unwrap_or_else(|| state.", "active_root())"].concat();
        assert!(
            !resuming.contains(&only_the_session) && !resuming.contains(&only_the_root),
            "the pre-drop ladder is back beside the resolved one:\n{resuming}"
        );

        // 3. The workspace reaches the command, from the same builder.
        let rebuilt = [
            "    let elsewhere = dropped.filter(|target| target.as_path() == root.as_path());",
            "    let command = match elsewhere {",
            "        Some(target) => {",
            "            let mut moved = session.clone();",
            "            moved.cwd = Some(target.to_string_lossy().into_owned());",
        ]
        .join("\n");
        assert!(
            resuming.contains(&rebuilt),
            "the command still `cd`s into the session's old directory, so a \
             drop opens a shell that walks straight back out of the workspace \
             it was dropped on:\n{resuming}"
        );
        assert_eq!(
            resuming.matches("vault::resume_command_with_base(").count(),
            2,
            "the resumed command is no longer built by the module that knows \
             each agent's spelling, or is built once and edited:\n{resuming}"
        );
        // Both spellings from the SAME resolved base: two bases would let the
        // equality check pass a command the drop road then rebuilds
        // differently.
        assert_eq!(
            resuming.matches("vault_resume_base(").count(),
            1,
            "the base is resolved more than once inside one resume:\n{resuming}"
        );

        // 4. Checked, then resolved, then spawned — in that order.
        let checked = ["    .filter(|sent| *sent == ", "expected)"].concat();
        let at = |needle: &str| {
            resuming
                .find(needle)
                .unwrap_or_else(|| panic!("`{needle}` is gone from the resume:\n{resuming}"))
        };
        assert!(
            at(&checked) < at("known_workspace_context(")
                && at("known_workspace_context(") < at("vault::resume_root(")
                && at("vault::resume_root(") < at("PtyLane::spawn("),
            "a resume spawns before it has checked the command or resolved the \
             workspace it was dropped on:\n{resuming}"
        );

        // The card is the drag source, and only where there is a command to
        // carry — a card that cannot reopen would light up every workspace row
        // on the way past and fail on the drop.
        let carrying = block_after(window, "function vaultRow(");
        let guard = ["if (session.", "resume) {"].concat();
        let handle = ["    row.dragg", "able = true;"].concat();
        let payload = [
            "      vaultDragged = session;",
            "      event.dataTransfer.effectAllowed = \"copy\";",
            "      event.dataTransfer.setData(VAULT_DRAG_TYPE, session.id);",
        ]
        .join("\n");
        assert!(
            carrying.contains(&handle) && carrying.contains(&payload),
            "a vault card cannot be dragged, or carries nothing a drop could \
             identify it by:\n{carrying}"
        );
        assert!(
            carrying.find(&guard) < carrying.find(&handle),
            "a session with no resume command is draggable, so a drop on a \
             workspace ends in an error dialog:\n{carrying}"
        );

        // The workspace row is the drop target: it accepts by TYPE (all a
        // dragover may read) and reopens the card in its own path.
        let dropping = block_after(window, "function makeWorktreeNode(");
        let accepting = [
            "    if (!carriesVaultSession(event.dataTransfer)) return;",
            "    event.preventDefault();",
            "    event.dataTransfer.dropEffect = \"copy\";",
        ]
        .join("\n");
        let landing = [
            "    const session = droppedVaultSession(event.dataTransfer);",
            "    row.classList.remove(\"is-drop-into\");",
            "    if (session === null) return;",
            "    event.preventDefault();",
            "    resumeVaultSession(session, worktree.path);",
        ]
        .join("\n");
        assert!(
            dropping.contains(&accepting),
            "a workspace row no longer accepts a session card, so the drop \
             never arrives:\n{dropping}"
        );
        assert!(
            dropping.contains(&landing),
            "a card dropped on a workspace no longer reopens in THAT \
             workspace:\n{dropping}"
        );

        // The window moves before it asks, and names the workspace it moved to.
        let reopening = block_after(window, "async function resumeVaultSession(");
        let moved = [
            "  if (worktree && worktree !== activeWorktreePath && !(await activate",
            "Worktree(worktree))) return;",
        ]
        .concat();
        let named = ["      worktree: worktree ?? ", "null,"].concat();
        assert!(
            reopening.contains(&moved) && reopening.contains(&named),
            "a dropped session opens a tab in a workspace the window is not \
             standing in, or asks for one without naming it:\n{reopening}"
        );
        // And the button beside it still names none, which is what keeps
        // "reopen where it ran" and "continue it here" two gestures.
        let pressed = ["open.onclick = () => resume", "VaultSession(session);"].concat();
        assert!(
            window.contains(&pressed),
            "the 다시 열기 button started naming a workspace, so a session can \
             no longer be reopened where it actually ran"
        );

        // The row says it is a target while a card is over it.
        let lit = block_after_css(sheet, ".wt-row.is-drop-into {");
        assert!(
            lit.contains("--ai-accent") && lit.contains("box-shadow"),
            "a workspace under a dragged session gives no sign it would take \
             it:\n{lit}"
        );
    }

    #[test]
    fn the_skills_page_only_reads_and_reveals_within_its_roots() {
        let shell = shipped_backend();
        let (shipped, _) = shell.split_once("#[cfg(test)]").unwrap_or((shell, ""));
        let source = window_source();

        // 1. No writing command, under any of the words one would be called.
        for absent in [
            "fn write_skill",
            "fn save_skill",
            "fn delete_skill",
            "fn create_skill",
            "fn install_skill",
        ] {
            assert!(
                !shipped.contains(absent),
                "`{absent}` exists — the skills surface is read-only by design, \
                 and a writer here edits files this product does not own"
            );
        }
        // And the window asks for nothing of the sort either.
        assert!(
            !source.contains("invoke(\"write_skill") && !source.contains("invoke(\"delete_skill"),
            "the skills page asks to change a skill"
        );

        // 2. The reveal is bounded, and bounded by canonical paths.
        let revealing = block_after(shipped, "fn checked_file(");
        assert!(
            revealing.contains("is_file()"),
            "reveal accepts something that is not a file:\n{revealing}"
        );
        assert!(
            revealing.contains(".canonicalize()") && revealing.contains("real.starts_with(root)"),
            "reveal no longer bounds the path to a skill root, so it opens \
             anything on the disk:\n{revealing}"
        );
        assert!(
            shipped.contains("skill::discovery_sources(&self.home, &self.repos)"),
            "reveal bounds against a list of its own rather than the roots that \
             were actually scanned:\n{revealing}"
        );

        // 3. One roots table, in Rust. The window must not carry its own.
        let core = include_str!("../../../zerocode-core/src/skill.rs");
        for root in [".codex", ".claude", ".grok", ".omp", "antigravity"] {
            assert!(
                core.contains(&format!("\"{root}\"")),
                "`{root}` left the roots table, so those skills are invisible"
            );
        }
        assert!(
            !source.contains(".claude\", \"skills") && !source.contains("skills-roots-table"),
            "the window carries its own copy of the skill roots"
        );
        let listing = block_after(source, "async function refreshSkills(force = false) {");
        assert!(
            listing.contains(r#""skills_rescan" : "skills_list""#),
            "the page no longer gets its skills from the backend:\n{listing}"
        );
    }

    /// The combined view loads by the file, and the history opens together —
    /// the G3 slice of the SCM parity order.
    ///
    /// - **Entries first, diffs as asked** (`loadSection` +
    ///   `createCombinedDiffLoadScheduler`, CombinedDiffViewer.tsx): the
    ///   first six sections load unasked (their
    ///   `COMBINED_DIFF_INITIAL_SECTION_LOAD_COUNT = 6`), the rest as they
    ///   approach the viewport, ONE at a time — their scheduler's default,
    ///   "serializing keeps large lockfile-style diffs from stacking render
    ///   work". The original couples approach to its virtualizer's range;
    ///   this window couples it to an IntersectionObserver 600px ahead — a
    ///   recorded adaptation, same contract. An answer that outlives its tab
    ///   re-finds its section by path or is dropped — a reopened tab must
    ///   not inherit rows aimed at the list it replaced.
    /// - **Every opening hand asks**: the fold, the tree, expand-all — a
    ///   section opened by any of them requests itself; a section that
    ///   already answered (or was withheld, or errored) is not asked again
    ///   (`shouldRequestCombinedDiffSectionLoad`'s gate).
    /// - **The body speaks its state** (DiffSectionBody.tsx): loading line,
    ///   error line with a Retry that clears and re-asks, then the shared
    ///   row painter. `hideUnchangedRegions: {enabled: true}` (:201,
    ///   combined-only in the original) is this engine's native posture —
    ///   git's hunk context never drew the unchanged regions at all; the
    ///   original's click-to-expand seams are the recorded gap.
    /// - **An untracked file is an answer, not an absence**: `file_diff`
    ///   synthesizes the unified diff a staged-new file would get, through
    ///   the SAME size gate and parser, so the untracked area's combined
    ///   view and the single view show the file instead of an empty body.
    /// - **The history opens together** ("Open all changes together",
    ///   git-history-commit-files.tsx): the expanded commit's file list ends
    ///   in the door, the sections stand from the sheet the expansion
    ///   already cached, each file answers through `commit_file_diff` — and
    ///   a commit section's own open-door routes to the COMMIT's diff, not
    ///   the working tree's today.
    /// - **The whole-tree door is gone**: `worktree_diff` had no callers
    ///   left, and an unregistered door nobody can knock on is the only
    ///   honest kind of gone.
    #[test]
    fn the_combined_view_loads_by_the_file_and_the_history_opens_together() {
        let house = shipped_backend();
        let (shipped, _) = house.split_once("#[cfg(test)]").unwrap_or((house, ""));
        let window = window_source();

        assert!(
            window.contains("const CHANGES_INITIAL_LOAD = 6;"),
            "the initial load moved off the original's six \
             (COMBINED_DIFF_INITIAL_SECTION_LOAD_COUNT)"
        );
        let draining = block_after(window, "async function drainChangesLoads(tab) {");
        assert!(
            draining.contains("if (load.busy) return;")
                && draining.contains("while (load.queue.length) {"),
            "the loads stopped being serialized — one at a time is the \
             original scheduler's default, for render work's sake:\n{draining}"
        );
        assert!(
            draining.contains("const section = tab.sections.find((one) => one.path === path);")
                && draining.contains("if (!section) continue;"),
            "an answer that outlived its tab writes to an orphan section:\n{draining}"
        );
        assert!(
            draining.contains(r#"? await invoke("commit_file_diff", {"#)
                && draining.contains(r#": await invoke("file_diff", { path });"#),
            "a section stopped fetching through its surface's own door:\n{draining}"
        );
        let requesting = block_after(window, "function requestChangesSection(tab, path) {");
        assert!(
            requesting.contains(
                "if (!section || section.lines !== null || section.limit || section.error) return;"
            ),
            "a section that already answered is asked again \
             (shouldRequestCombinedDiffSectionLoad's gate):\n{requesting}"
        );
        let watching = block_after(window, "function watchChangesApproach(tab, view) {");
        assert!(
            watching.contains(r#"rootMargin: "600px 0px""#)
                && watching.contains("watch.unobserve(hit.target);"),
            "the approach watcher lost its margin or keeps watching a \
             section it already asked for:\n{watching}"
        );
        // Reopen resets the queue (the original scheduler's reset), and a
        // closed tab takes its loader and watcher with it.
        assert!(
            block_after(
                window,
                "async function openChangesSections(sections, source, baseRef = null, extra = {}) {"
            )
            .contains("load.queue.length = 0;"),
            "a reopened combined tab inherits the old list's queue"
        );
        assert!(
            window.contains("changesLoads.delete(removed.id);")
                && window.contains("changesWatches.get(removed.id)?.disconnect();"),
            "a closed combined tab leaves its loader or watcher behind"
        );

        // The body's ladder, and the retry that clears before it re-asks.
        let body = block_after(window, "function changesSectionBody(tab, section) {");
        assert!(
            body.contains(r#"t("changes.loading", "diff 읽는 중…")"#)
                && body.contains("section.error = null;")
                && body.contains("requestChangesSection(tab, section.path);"),
            "the section body lost its loading line or its retry:\n{body}"
        );
        assert!(
            window.contains("\"changes.loading\": \"Loading diff...\",")
                && window.contains("\"changes.areaStaged\": \"Staged Changes\",")
                && window.contains("\"changes.areaUntracked\": \"Untracked Files\",")
                && window.contains("\"history.openAll\": \"Open all changes together\",")
                && window.contains("\"changes.commitLabel\": \"Commit {{ref}}: {{subject}}\","),
            "a combined-view word walked away from the original's spelling"
        );

        // The untracked arm: the synthesized diff walks the same gates.
        let asking = block_after(shipped, "fn file_diff(");
        assert!(
            asking.contains("if diff.trim().is_empty() && !git_tracks(&root, &path) {")
                && asking.contains("diff = untracked_as_added(&root, &path);"),
            "an untracked file is an empty answer again:\n{asking}"
        );
        let synthesizing = block_after(
            shipped,
            "fn untracked_as_added(root: &Path, path: &str) -> String {",
        );
        assert!(
            synthesizing.contains("new file mode 100644")
                && synthesizing.contains("if file.text.is_empty() {"),
            "the synthesized diff stopped spelling itself like a staged-new \
             file's, or writes a hunk that says nothing for an empty file:\n{synthesizing}"
        );

        // The history's together-door, on the cached sheet, and the commit
        // section's own open route.
        let paneling = block_after(window, "function historyFilesPanel(item) {");
        assert!(
            paneling.contains(r#"t("history.openAll", "모든 변경을 함께 열기")"#)
                && paneling.contains("void openCommitChanges(item.id, item.subject ?? \"\")"),
            "the expanded commit lost its open-together door:\n{paneling}"
        );
        assert!(
            block_after(
                window,
                "async function openCommitChanges(id, subject = \"\") {"
            )
            .contains("await historySheet(id);"),
            "opening a commit's changes stopped reusing the sheet the \
             expansion already cached"
        );
        let heading = block_after(window, "function changesHeader(tab, section) {");
        assert!(
            heading.contains(
                "void openCommitFileDiff(tab.commit, section.path, section.origin ?? null);"
            ),
            "a commit section's open-door walks to the working tree's diff \
             instead of the commit's:\n{heading}"
        );
        // The Eye, gated the original's way (canOpenDiffSectionPreviewToSide):
        // no commit surface, no deleted file, a previewable language.
        assert!(
            heading.contains("tab.source !== \"commit\" && section.status !== \"deleted\"")
                && heading.contains("renderedAs(section.path) === \"markdown\""),
            "the preview eye lost its gate:\n{heading}"
        );
        // Reload folds the sheet cache — a refresh that hands back the same
        // sheet is not a refresh.
        assert!(
            block_after(window, "function paintChangesView(tab) {")
                .contains("historySheets.delete(tab.commit);"),
            "reloading a commit surface re-reads nothing"
        );
        // The reopen road routes by surface.
        let reopening = block_after(window, "async function reopenStageTab(tab) {");
        assert!(
            reopening.contains("if (tab.source === \"committed\") return openCommittedChanges();")
                && reopening.contains(
                    "if (tab.source === \"commit\") return openCommitChanges(tab.commit, tab.subject ?? \"\");"
                ),
            "a stored combined tab comes back as a different surface:\n{reopening}"
        );

        // The whole-tree door is gone — fn and registration both.
        assert!(
            !shipped.contains("async fn worktree_diff(")
                && !shipped.contains("            worktree_diff,"),
            "the callerless whole-tree door is still standing"
        );
    }

    /// A changed file can be fixed where it is being reviewed.
    ///
    /// The original's combined view is a stack of Monaco diff editors, and the
    /// sections of the unstaged area are editable in place
    /// (`isEditable = section.area === 'unstaged'`, DiffSectionItem.tsx:71).
    /// Ours renders rows, and those rows carry the diff notes and the
    /// line-level hands Monaco has no equivalent for — so the recorded
    /// deviation is that a hand on the section head turns THAT section into
    /// the editing surface, rather than every section being one always.
    ///
    /// Everything under that is the original's:
    /// - **Which sections** can be edited at all. A commit's diff is not a
    ///   file, and a document with no stamp is one this window cannot save —
    ///   the same sentence the single-file diff already says with
    ///   `Boolean(tab.version)`.
    /// - **One side only.** `originalEditable: false`, and it is also just
    ///   true: the left document is a snapshot, not a file.
    /// - **The draft lives in the SECTION**, for the original's own reason:
    ///   "virtualized rows unmount when scrolled away, so the draft must live
    ///   in section state instead of only in Monaco's mounted model."
    /// - **⌘S saves that one section** (`installEditorSaveShortcut` sits on
    ///   the modified pane's node) — here a CodeMirror keymap, so the window's
    ///   one keydown road is not given a second lane.
    /// - **The write is THE write.** The modified side of a section is the
    ///   working file, so it is written by the write a file tab is written by
    ///   — a second path would be a second optimistic lock and a second
    ///   `create_if_missing`, which is what `saveFile`'s own comment forbids.
    ///   A refusal keeps the draft: a save that discards what somebody typed
    ///   is not a save.
    ///
    /// One thing ours does that the original has no need to: after a write it
    /// RE-READS the section. Monaco recomputes its own chunk table from two
    /// documents it holds; our rows and the head's tallies are what Rust read,
    /// and they would otherwise describe the file as it was before the fix.
    #[test]
    fn a_changed_file_can_be_fixed_where_it_is_being_reviewed() {
        let window = window_source();
        let styles = include_str!("../../../../ui/shell.css");

        // The two documents already arrive; the combined view used to drop them.
        assert!(
            block_after(window, "async function drainChangesLoads(tab) {")
                .contains("section.texts = answer.texts ?? null;"),
            "the section throws away the only thing an edit could be saved from"
        );

        // Which sections, and one side of them.
        let gate = block_after(window, "function changesSectionEditable(tab, section) {");
        assert!(
            gate.contains("tab.source !== \"commit\" && Boolean(section.texts?.version)"),
            "a commit's diff, or a document with no stamp, became editable:\n{gate}"
        );
        let body = block_after(window, "function changesMergeBody(tab, section) {");
        assert!(
            body.contains(
                "a: { doc: section.texts.original, extensions: diffExtensions(section, false) },"
            ) && body.contains("doc: section.draft ?? section.texts.modified,"),
            "the committed side became editable, or the draft stopped being \
             what the editing side opens on:\n{body}"
        );

        // ⌘S is the editor's, not a second road through the window.
        assert!(
            body.contains("CM.keymap.of([{ key: \"Mod-s\", run: () => (void saveChangesSection(tab, section), true) }]),"),
            "the section's save shortcut left the editor's own keymap:\n{body}"
        );

        // The draft is the section's, so a repaint cannot lose it.
        assert!(
            block_after(window, "function changesTyped(tab, section, typed) {")
                .contains("section.draft = typed;"),
            "the draft stopped living where a section that unmounts can keep it"
        );

        // The write is THE write. A section's save builds a target for the one
        // save and reads its stamp back — it does not grow a second optimistic
        // lock, which is what `saveFile`'s own comment forbids.
        let saving = block_after(window, "async function saveChangesSection(tab, section) {");
        assert!(
            saving.contains("const wrote = await saveFile(target);")
                && saving.contains("version: texts.version,")
                && saving.contains(
                    "section.texts = { ...texts, modified: content, version: target.version };"
                ),
            "the section's save left the one save, or stopped carrying the \
             stamp it read:\n{saving}"
        );
        assert!(
            saving.contains("target.stale") && saving.contains("return false;"),
            "a refused save no longer says what happened:\n{saving}"
        );
        assert!(
            saving.contains("section.lines = null;")
                && saving.contains("requestChangesSection(tab, section.path);"),
            "the rows and the tallies keep describing the file as it was:\n{saving}"
        );

        // And the editors are destroyed — on the hand, and with the tab.
        assert!(
            block_after(window, "function dropChangesMerge(key) {")
                .contains("held.merge.destroy();"),
            "a section's editor is dropped without destroying it"
        );
        assert!(
            block_after(window, "if (removed?.kind === \"changes\") {")
                .contains("dropChangesMerge(key);"),
            "closing a combined view leaves its section editors measuring an \
             unmounted tree"
        );

        // A section holding an unsaved draft says so.
        assert!(
            styles.contains(".changes-section.is-dirty > .changes-head .changes-name::after {"),
            "an unsaved section stopped wearing its mark"
        );
    }

    /// The board classifies in Rust; the window only gathers and draws.
    ///
    /// Orca's `AgentKanbanBoard` (AgentKanbanBoard-CzEPAxZN.js, 1.4.164) puts one
    /// card per running agent in four columns and moves the card as the agent's
    /// state changes. Two things about that are easy to get subtly wrong and
    /// impossible to notice:
    ///
    ///   1. **Two vocabularies, one column.** A supervised lane says `streaming`
    ///      and an agent reporting through hooks says `working` — the same
    ///      situation, spelled twice, because `LaneState` and `HookState` are
    ///      different enums with different serde casings. If the window decided
    ///      columns itself, those two would land in different ones the day
    ///      somebody adds a state to only one table. So the mapping is one
    ///      tested function and the window has no copy of it.
    ///   2. **A number outside the door and a list behind it.** The badge counts
    ///      what wants a person; the Needs You column lists it. They are asked
    ///      the same way, so they cannot disagree.
    #[test]
    fn the_board_decides_its_columns_in_one_place() {
        let source = window_source();
        let core = include_str!("../../../zerocode-core/src/board.rs");

        if source.contains("async function paintAgentGraphView(") {
            let painting = block_after(source, "async function paintAgentGraphView(");
            assert!(
                painting.contains(r#"invoke("board_snapshot""#),
                "the graph reclassifies what Rust's one snapshot already decided:\n{painting}"
            );
            let snapshot = block_after(core, "pub fn snapshot(");
            assert!(
                snapshot.contains("let bucket = card.bucket_at(now_ms);")
                    && snapshot.contains("attention_count += 1;")
                    && snapshot.contains("BoardSnapshot"),
                "Rust no longer produces the graph and badge from one classification pass:\n{snapshot}"
            );
            let badge = block_after(source, "function applyBoardBadge(answer) {");
            assert!(
                badge.contains("answer.attention_count")
                    && badge.contains(r#"invoke("set_dock_badge", { count: stuck })"#),
                "the badge invented a second attention rule:\n{badge}"
            );
            return;
        }

        // 1. Every state word either half of this product can produce is in the
        // core's table. Named, not counted — a count passes when a word is
        // dropped and another added.
        let (rules, _) = core.split_once("#[cfg(test)]").unwrap_or((core, ""));
        let mapping = rules
            .split_once("pub fn of_word(")
            .map(|(_, rest)| rest)
            .unwrap_or_default();
        for word in [
            "streaming",
            "working",
            "waiting",
            "blocked",
            "needs-attention",
            "awaiting-permission",
            "done",
            "exited",
        ] {
            assert!(
                mapping.contains(&format!("\"{word}\"")),
                "`{word}` is a state this window produces and the board does not \
                 classify, so an agent in it lands in the idle column"
            );
        }
        // And the two enums' own words still spell what that table reads. The
        // casings differ on purpose (`LaneState` snake, `HookState` kebab) and the
        // mapping normalises — this is the assertion that the normalising is
        // still there, because without it half the words silently miss.
        assert!(
            mapping.contains("replace('_', \"-\")"),
            "the two state vocabularies use different casings; without \
             normalising, `awaiting_permission` falls through to idle"
        );

        // 2. The window classifies nothing. No bucket names in a JS conditional,
        // and no second sort of the cards.
        let gathered = block_after(source, "async function boardCards() {");
        assert!(
            gathered.contains(r#"invoke("pane_agents")"#) && gathered.contains("cardsFromLanes()"),
            "the board no longer gathers from both sources, so half the running \
             agents are missing from it:\n{gathered}"
        );
        let painted = block_after(source, "async function paintBoardView(");
        assert!(
            painted.contains(r#"invoke("board_columns""#),
            "the window groups the board itself, which is a second copy of the \
             tested rules:\n{painted}"
        );
        assert!(
            !painted.contains(".sort(") && !painted.contains(".filter("),
            "the window re-sorts or re-filters what Rust already grouped:\n{painted}"
        );
        // The badge asks the same question through the same door.
        let badge = block_after(source, "async function refreshBoardBadge() {");
        assert!(
            badge.contains(r#"invoke("board_columns""#) && badge.contains(r#"=== "attention""#),
            "the door's badge counts by its own rule, so it can disagree with \
             the column behind it:\n{badge}"
        );

        // (That the stage actually HIDES this new surface is
        // `a_surface_with_no_tab_is_hidden`'s subject, and it checks every
        // document kind rather than only this one.)

        // The state a card shows comes from the backend, which is the only half
        // that knows what happened before this window was listening.
        let shell = shipped_backend();
        let (shipped, _) = shell.split_once("#[cfg(test)]").unwrap_or((shell, ""));
        assert!(
            shipped.contains("fn pane_agents(") && shipped.contains("pane_states()"),
            "`pane_agents` no longer answers from retained state, so a board \
             opened mid-session shows every agent as idle"
        );
        // And it is forgotten when the pane goes, beside the token and the
        // session that are forgotten there for the same reason — otherwise the
        // board draws a card for an agent that is gone.
        assert!(
            shipped.contains("state.pane_states().remove(&term);"),
            "a closed pane keeps its last reported state"
        );
    }

    /// A card's clock is honest twice over: a dead session stops claiming its
    /// state, and a lane's age counts from its last word rather than from the
    /// render.
    ///
    /// The decay is Orca's `AGENT_STATUS_STALE_AFTER_MS` — 30 minutes, applied
    /// to non-done rows only (index-ftls8Hg_.js:25808-25843): a board that says
    /// "working" about a process that died at lunch is telling the person their
    /// work is progressing when nobody knows. It is computed in RUST with this
    /// process's clock, because the stamps were written by this process — a
    /// webview clock would make a card stale on one side and fresh on the
    /// other, and a JS `.filter` would break the no-refiltering gate above.
    ///
    /// The lane stamp is written at INGESTION, on the state transition — the
    /// same discipline `hook_loop` applies to `PaneState.at`. Stamped at
    /// render, every lane says "방금" forever; stamped only at open, a lane
    /// ages while it is still talking.
    #[test]
    fn a_cards_clock_is_stamped_at_ingestion_and_believed_with_limits() {
        let backend = shipped_backend();
        let (shipped, _) = backend.split_once("#[cfg(test)]").unwrap_or((backend, ""));
        let window = window_source();
        let core = include_str!("../../../zerocode-core/src/board.rs");
        let (rules, _) = core.split_once("#[cfg(test)]").unwrap_or((core, ""));

        // The decay rule lives in core, takes the clock, and spares done.
        assert!(
            rules.contains("pub const STALE_AFTER_MS: i64 = 30 * 60 * 1000;"),
            "the staleness threshold moved off Orca's measured number"
        );
        let aging = block_after(core, "pub fn bucket_at(");
        assert!(
            aging.contains("self.changed_at > 0") && aging.contains("plain != Bucket::Done"),
            "the decay forgot the no-clock guard or started demoting finished \
             work:\n{aging}"
        );

        // The shell hands core ITS clock — the one that wrote the stamps.
        let grouping = block_after(shipped, "fn board_columns(");
        assert!(
            grouping.contains("zerocode_core::board::columns(&cards, &query, epoch_ms_now())"),
            "the column grouping stopped passing this process's clock:\n{grouping}"
        );

        // The lane stamp: at ingestion, on the transition, and never at render.
        let ingesting = block_after(window, "function upsertLane(");
        assert!(
            ingesting
                .contains("if (entry.lane.state !== lane.state) entry.changedAt = Date.now();"),
            "a lane's stamp is no longer written on the state change:\n{ingesting}"
        );
        let lanes_cards = block_after(window, "function cardsFromLanes() {");
        assert!(
            !lanes_cards.contains("changed_at: 0,"),
            "lane cards went back to no clock at all:\n{lanes_cards}"
        );
        assert!(
            !lanes_cards.contains("Date.now()"),
            "a lane card reads the render clock, so everything says 방금 \
             forever:\n{lanes_cards}"
        );
        assert!(
            lanes_cards.contains("changed_at: changedAt ?? 0,"),
            "a lane the stamp never reached no longer degrades to \"no \
             age\":\n{lanes_cards}"
        );
    }

    /// A board card carries the conversation's last words — what was asked
    /// and what came back — the way Orca's does (`lastUserMessage`/
    /// `lastAgentMessage`, I18nProvider-4EBrmTGg.js:96432-96442, filled from
    /// hook payloads and transcript tails, out/main/index.js:9842-9859).
    /// The extraction is shared with the vault, which is the other consumer
    /// of the same vendor files; this gate pins the sharing and the three
    /// rules that keep the lines truthful.
    #[test]
    fn a_board_card_carries_the_conversations_last_words() {
        let shell = shipped_backend();
        let (shipped, _) = shell.split_once("#[cfg(test)]").unwrap_or((shell, ""));
        let bridging = include_str!("../../src/hooks.rs");
        let reading = include_str!("../../../zerocode-core/src/transcript.rs");
        let (reader, _) = reading.split_once("#[cfg(test)]").unwrap_or((reading, ""));
        let vault = include_str!("../../../zerocode-core/src/vault.rs");
        let window = window_source();

        // ONE extraction, and the vault reads through it — two readers of the
        // same vendor files is how previews and cards drift apart.
        assert!(
            vault.contains("use crate::transcript::{clamp, message_text}")
                && !vault.contains("fn message_text("),
            "the vault grew its own copy of the message extraction"
        );

        // The reader is bounded and read-only: these are the vendors' files.
        assert!(
            reader.contains("take(MAX_TAIL_BYTES)"),
            "the tail read lost its bound, so a 2 GB transcript is read whole"
        );
        for forbidden in ["fs::write", "fs::rename", "OpenOptions", "fs::remove"] {
            assert!(
                !reader.contains(forbidden),
                "`{forbidden}` in the transcript reader — it reads records of \
                 somebody's work and must not be able to change them"
            );
        }

        // The prompt only rides prompt events; the answer rides turn-ending
        // ones whole, and tool events mid-turn with what the tool just did
        // (`extractClaudeToolFields`, out/main/index.js:9541) — a `message`
        // field means other things elsewhere.
        let reporting = block_after(bridging, "pub fn report_of(");
        assert!(
            reporting.contains(
                "let payload = zerocode_core::payload::HookPayload::of(&envelope.payload);"
            ) && reporting.contains("userpromptsubmit")
                && reporting.contains("prompt_in_parsed")
                && reporting.matches(".map(sanitize_card_text)").count() == 2
                && reporting.contains("HookState::Done {")
                && reporting.contains("said_in_parsed")
                && reporting.contains("\"posttooluse\" => ")
                && reporting.contains("tool_said_in_parsed")
                && reporting.contains("tool_failure_in_parsed"),
            "the report reads card lines off events that do not carry \
             them:\n{reporting}"
        );

        // The clear rule: a turn that ends saying nothing CLEARS the card's
        // answer line (Orca's clearLastAssistantMessage) — the merge replaces
        // `said` wholesale on Done, and across working events a tool's words
        // replace while silence carries (Orca's `?? previous`, :8842).
        assert!(
            shipped.contains("report.said.clone()")
                && shipped.contains(".or_else(|| prior.and_then(|held| held.said.clone()))"),
            "the pane state stopped merging, so either every event wipes the \
             card's lines or a stale answer survives under a new prompt"
        );

        // The compact card draws one recent utterance. The answer wins over
        // the prompt, control characters are stripped, and a stale tool error
        // cannot headline work that is currently healthy.
        let drawing = block_after(window, "function boardCardNode(");
        assert!(
            drawing.contains("agentGraphMessage(card, agentGraphState({ card, bucket }))")
                && drawing.contains("board-card-you")
                && drawing.contains("board-card-said")
                && drawing.contains("board-card-who")
                && block_after(window, "function agentGraphMessage(").contains("mayHeadlineError")
                && block_after(window, "function agentGraphCleanText(").contains("\\u0000-\\u0008"),
            "the card no longer draws one safe recent utterance:\n{drawing}"
        );

        // The question box. Extracted only on attention events, never carried
        // to the next event (Orca: "carrying it forward leaves a stale live
        // card", index.js:8840) — the merge writes `None` on every state that
        // is not the asking.
        assert!(
            block_after(bridging, "pub fn report_of(").contains("HookState::NeedsAttention)"),
            "the ask is read off events that are not the asking"
        );
        assert!(
            shipped.contains("report.ask.clone()"),
            "the pane state stopped taking the ask from the event that \
             carried it"
        );
        // Drawn only in the attention column (Orca reads the bucket, :26400),
        // below the status row. Round two (t-2466) keeps the state mark in
        // that row on every state: the row says which state owns the card,
        // the box says what needs answering — a card that lost its mark on
        // one state misaligned against every other card's row, and the
        // window harness pins the same shape from the DOM.
        assert!(
            drawing.contains("bucket === \"attention\"")
                && drawing.contains("board-card-ask")
                && drawing.contains(
                    "status.append(boardStateMark(card.state, settled), stateWord, phase)"
                ),
            "the question box left the attention column, or the status row \
             lost its state mark:\n{drawing}"
        );
    }

    /// A question answered on a card walks the agent's own TUI — and every
    /// rule of that walk lives in Rust, where it is tested.
    ///
    /// The protocol is Orca's, measured: `buildAskAnswerKeys` (digits pick
    /// rows, the "Type something" row is one past the options, arrows move
    /// between questions — index-ftls8Hg_.js:69118), one key group per
    /// second (`NATIVE_CHAT_QUESTION_STEP_MS`, :65035), a new answer
    /// cancelling the one still being typed (`cancelInFlight`, :69780), and
    /// the full question shape riding only the event that asked it. The
    /// window collects picks and hands them over; it builds no keys.
    #[test]
    fn an_answer_walks_the_agents_own_tui() {
        let shell = shipped_backend();
        let (shipped, _) = shell.split_once("#[cfg(test)]").unwrap_or((shell, ""));
        let bridging = include_str!("../../src/hooks.rs");
        let keys = include_str!("../../../zerocode-core/src/ask.rs");
        let (protocol, _) = keys.split_once("#[cfg(test)]").unwrap_or((keys, ""));
        let cards = include_str!("../../../zerocode-core/src/board.rs");
        let window = window_source();

        // The keys are the measured grammar, in the tested crate: the digit
        // that picks a row, the row one PAST the options for free text, and
        // the submit-tab Enter that only a multi-question walk earns.
        assert!(
            protocol.contains("(q.options.len() + 1).to_string()")
                && protocol.contains(
                    "multi_question || (questions.len() == 1 && questions[0].multi_select)"
                )
                && protocol.contains("\\x1b[C"),
            "the claude key grammar lost a rule it was measured to have"
        );
        // And the command spends them without rebuilding them: the split by
        // agent, the refusal when nothing was answered, the pacing, and the
        // paste envelope for text — all by reference to the protocol crate.
        let answering = block_after(shipped, "fn answer_ask(");
        for wired in [
            "ask::has_answer(&prompt, &selections)",
            "ask::keys_for(&agent, &prompt, &selections)",
            "ask::QUESTION_STEP_MS",
            "ask::line_keys(&ask::format_answer(&prompt, &selections))",
        ] {
            assert!(
                answering.contains(wired),
                "`{wired}` left answer_ask — the walk no longer follows the \
                 measured protocol:\n{answering}"
            );
        }
        // The walk itself — the pacing between groups and the paste envelope
        // for text — is the one walker the card shares with a pane's
        // hand-over (`walk_key_groups`), so the two cannot type differently.
        let walking = block_after(shipped, "fn walk_key_groups(");
        assert!(
            walking.contains("std::thread::sleep(step)") && walking.contains("encode_paste(text"),
            "the walk no longer paces its groups or pastes its text:\n{walking}"
        );
        // A second answer for the same pane stops the first mid-walk —
        // otherwise both type into one TUI and the interleaving answers
        // neither question. The card hands the walker that question.
        assert!(
            answering.contains("ask_sends")
                && answering.contains("== Some(&generation)")
                && answering.contains("walk_key_groups(&state, term, &groups, step, same_send)"),
            "a newer answer no longer cancels the walk in flight:\n{answering}"
        );

        // The full shape rides only the asking event, exactly like the
        // summary beside it — and the merge drops both together.
        assert!(
            block_after(bridging, "pub fn report_of(").contains("ask::prompt_in_parsed"),
            "the report no longer parses the question's shape off the event"
        );
        // 「함께 산다」는 배포 본문에서 재고, 「함께 죽는다」는 비우는 갈래가
        // **소식에서 아무것도 나르지 않는다**로 잰다.
        //
        // 칸 수는 세지 않는다 — 컴파일러가 이미 두 갈래의 길이를 같게 만들고,
        // 튜플의 철자를 요구하는 핀은 칸이 하나 늘어나는 날 **아무 의미 없이**
        // 깨져서 고치는 사람이 의도째로 지운다. `(None, None, None)`을
        // 요구하던 앞 판이 정확히 그렇게 깨졌다(제출 낱말이 넷째 칸으로
        // 들어오면서). 그 자리를 사실로 바꾼다.
        let noting = block_after(shipped, "fn note_pane_state(");
        assert!(
            noting.contains("report.ask_prompt.clone(),"),
            "the merge stopped taking the question's shape from the report"
        );
        let clearing = noting
            .split_once("report.approval.clone(),")
            .expect("the approval left the branch the ask lives in")
            .1
            .split_once("} else {")
            .expect("the ask has no clearing branch — it would outlive its event")
            .1;
        let clearing = clearing.split_once("};").map_or(clearing, |(head, _)| head);
        assert!(
            !clearing.contains("report."),
            "the clearing branch carries a field off the report, so one part \
             of the ask now lives past the event that brought it:\n{clearing}"
        );
        // And it survives the trip through the column rules — the card the
        // window gets back still holds the choices.
        assert!(
            cards.contains("pub ask_prompt: Option<crate::ask::AskPrompt>"),
            "BoardCard dropped the prompt, so the columns strip the choices \
             off every card on the way to the screen"
        );
        assert!(
            shipped.contains("ask_prompt: held.and_then(|one| one.ask_prompt.clone())"),
            "pane_agents stopped shipping the question's shape"
        );

        // The window: the amber box opens into the panel, the picks travel
        // through the one command, and a draft is keyed to ITS question —
        // Orca's dismiss key — so a new question never inherits old picks.
        let drawing = block_after(window, "function boardCardNode(");
        assert!(
            drawing.contains("askDraftFor(card)") && drawing.contains("askPanelNode(card, draft)"),
            "the card no longer opens the answer panel:\n{drawing}"
        );
        assert!(
            block_after(window, "function submitAsk(").contains(r#"invoke("answer_ask""#),
            "the panel answers around the command"
        );
        assert!(
            block_after(window, "function askSignature(").contains("JSON.stringify(prompt")
                && block_after(window, "function askSignature(").contains("card.approval"),
            "drafts lost the question signature, so a new question inherits \
             picks that answered something else"
        );
        // No key building in the window — the grammar has one home.
        assert!(
            !window.contains("\\x1b[C") && !window.contains("options.length + 1"),
            "the window grew its own copy of the key grammar"
        );
    }

    /// A permission request is answered from its card with one key, at once.
    ///
    /// The approval is Orca's, measured end to end: built only off the
    /// `PermissionRequest` event (`deriveInteractivePrompt`,
    /// out/main/index.js:9035), summarised by the one telling input field
    /// clipped at 200 (`summarizeApprovalInput`, :9011), never mistaken for
    /// a question (`parseInteractivePrompt` asks in that order,
    /// index-ftls8Hg_.js:69232), and answered raw — Allow is `"1"`, Deny is
    /// escape, sent without pacing and dismissed in the same breath
    /// (`parseApprovalFromStatus` :69216, `onChoose` → `sendRaw` :69583).
    #[test]
    fn an_approval_is_one_key_sent_at_once() {
        let shell = shipped_backend();
        let (shipped, _) = shell.split_once("#[cfg(test)]").unwrap_or((shell, ""));
        let bridging = include_str!("../../src/hooks.rs");
        let keys = include_str!("../../../zerocode-core/src/ask.rs");
        let (protocol, _) = keys.split_once("#[cfg(test)]").unwrap_or((keys, ""));
        let window = window_source();

        // The two keys live in the tested crate, and the question wins over
        // the approval — a questions-shaped payload is never an approval.
        assert!(
            protocol.contains(r#"pub const APPROVAL_ALLOW: &str = "1""#)
                && protocol.contains(r#"pub const APPROVAL_DENY: &str = "\x1b""#),
            "the approval keys left the protocol crate"
        );
        assert!(
            block_after(protocol, "pub fn approval_in_parsed(")
                .contains("questions_shape).is_some()"),
            "a question wearing a tool's name is read as an approval"
        );

        // Narrower than the ask: only the permission event carries one.
        assert!(
            block_after(bridging, "pub fn report_of(").contains("permissionrequest"),
            "the approval is read off events that are not the permission \
             request — a Notification has nothing to allow"
        );

        // The command spends the crate's keys through the one terminal door.
        let answering = block_after(shipped, "fn answer_approval(");
        assert!(
            answering.contains("ask::APPROVAL_ALLOW")
                && answering.contains("ask::APPROVAL_DENY")
                && answering.contains("with_terminal"),
            "answer_approval no longer spends the measured keys:\n{answering}"
        );

        // The panel: both verbs through the command, dismissed on press.
        let panel = block_after(window, "function approvalPanelNode(");
        assert!(
            panel.contains(r#"invoke("answer_approval""#) && panel.contains("draft.open = false"),
            "the approval panel answers around the command, or lingers \
             after the answer:\n{panel}"
        );
        // Question first, approval second — Orca's own order.
        assert!(
            block_after(window, "function boardCardNode(")
                .contains("card.ask_prompt ? askPanelNode(card, draft) : approvalPanelNode"),
            "the approval panel takes precedence over the question's"
        );
    }

    /// A question waiting for an answer is never overwritten by the next one.
    ///
    /// Two agents stopping at once is the ordinary case on a board built for
    /// five of them, and every surface that can only show ONE question at a
    /// time owes the others the same three things: they WAIT rather than
    /// replace, the person is told how many are behind the one on screen, and
    /// a question whose owner has gone leaves instead of standing in front of
    /// the ones that can still be answered.
    ///
    /// Orca does not solve this and cannot be copied here: its question is one
    /// slot on the pane's own status (`lastToolByPaneKey`'s
    /// `interactivePrompt`, out/main/index.js:8832-8845, overwritten on every
    /// update and deliberately never inherited), drawn as one card per pane
    /// (`NativeChatInteractiveCard`, index-ftls8Hg_.js:69488-69494). That is
    /// right for a pane — a TUI asks one thing at a time — and it is why the
    /// per-pane cards below need no queue at all. The two surfaces that are
    /// SINGULAR for the whole window do: the permission modal, and the
    /// pinned-close question, which was literally a single slot and dropped
    /// the first caller's promise on the floor when a second aim arrived.
    #[test]
    fn a_waiting_question_is_never_overwritten_by_the_next_one() {
        let window = window_source();
        let markup = include_str!("../../../../ui/index.html");
        let sheet = include_str!("../../../../ui/shell.css");

        // ── the pinned-close question ────────────────────────────────────
        // A queue, and the slot it used to be is GONE. ⌘W is a chord and a
        // chord has no scrim to be blocked by, so a second question can
        // always arrive while the first stands; the slot answered that by
        // losing the first promise, and the tab a person had just asked to
        // close silently stayed open.
        assert!(
            window.contains("const pinnedAsks = [];") && !window.contains("pinnedAsk = {"),
            "the pinned-close question went back to a single slot — the \
             second question overwrites the first, whose caller is then \
             never answered at all"
        );
        let asking = block_after(window, "function askAboutPinned(");
        assert!(
            asking.contains("pinnedAsks.find((one) => one.tab === tab)")
                && asking.contains("waiting.resolves.push(resolve)")
                && asking.contains("pinnedAsks.push({ tab, resolves: [resolve] })"),
            "asking twice about the same tab no longer collapses into one \
             question with both callers on it:\n{asking}"
        );
        let painting = block_after(window, "function paintPinnedAsk() {");
        assert!(
            painting.contains("pinnedAsks[0]")
                && painting.contains("pinnedAsks.length - 1")
                && painting.contains(r#"t("ask.more""#),
            "the dialog stopped showing the OLDEST question, or stopped \
             counting the ones behind it:\n{painting}"
        );
        let answering_pin = block_after(window, "function answerPinned(");
        assert!(
            answering_pin.contains("pinnedAsks.shift()")
                && answering_pin.contains("paintPinnedAsk()")
                && answering_pin.contains("of asked?.resolves ?? []"),
            "an answer no longer advances the queue, or no longer reaches \
             every caller waiting on that one question:\n{answering_pin}"
        );
        // And a tab that leaves by another road takes its question with it —
        // through the one door every close ends at, with the answer still
        // DELIVERED, because a caller parked on that promise is a close that
        // never finishes.
        assert!(
            block_after(window, "function withdrawPinnedAsk(").contains("resolve(false)")
                && block_after(window, "function dropTab(").contains("withdrawPinnedAsk(removed)"),
            "a question about a tab that has gone stays in the queue, or its \
             caller is left hanging"
        );

        // ── the permission modal ─────────────────────────────────────────
        // A prompt arriving behind one already on screen only moves the
        // count. A repaint here would rebuild the buttons an answer in
        // flight was pressed on, which is how one answer becomes two.
        let raising = block_after(window, "function raisePermission(");
        assert!(
            raising.contains("if (alreadyRaised(frame)) return;")
                && raising.contains("if (activePrompt) paintPermissionCount();")
                && raising.contains("else showNextPermission();"),
            "a second permission prompt no longer waits its turn, or repaints \
             the modal an answer is being pressed on:\n{raising}"
        );
        assert!(
            block_after(window, "function alreadyRaised(").contains("prompt_id"),
            "the same prompt id can be raised twice — a re-hydrated channel \
             then shows a modal whose id the server has already retired"
        );
        // The answer belongs to the question it was pressed on, and only that
        // question advances the queue: a withdrawal landing inside the await
        // already moved the modal on, and a second shift would take the next
        // agent's question off the queue without ever showing it.
        let answering = block_after(window, "async function answerPermission(");
        assert!(
            answering.contains("const answered = activePrompt;")
                && answering.contains("if (activePrompt !== answered) return;")
                && answering.contains("if (activePrompt === answered) showNextPermission();"),
            "an answer can now be delivered to, or advance past, a question \
             other than the one it was pressed on:\n{answering}"
        );
        // A session that ended takes its questions out of the queue — from
        // both roads that end one, because a prompt id retired with its
        // channel can only fail, and a modal that cannot be answered is a
        // wall in front of the questions behind it. Nothing is hidden: the
        // lane is gated `blocked` on the same event (제품 원칙 1).
        let withdrawing = block_after(window, "function withdrawPermissions(");
        assert!(
            withdrawing.contains("permissionQueue.splice(at, 1)")
                && withdrawing
                    .contains("if (activePrompt?.session === session) showNextPermission();"),
            "withdrawing a session's questions no longer clears the queue or \
             the modal:\n{withdrawing}"
        );
        assert!(
            block_after(window, r#"listen("session:ended", (event) => {"#)
                .contains("withdrawPermissions(session)")
                && block_after(window, "function removeLane(")
                    .contains("withdrawPermissions(entry.lane.session_id)"),
            "a session ending, or its lane closing, leaves a question nobody \
             can answer standing in front of the ones somebody can"
        );

        // ── and the count is a real element, in every language ───────────
        assert!(
            markup.contains(r#"id="pin-more""#) && markup.contains(r#"id="perm-more""#),
            "the dialogs have nowhere to say how many questions are waiting"
        );
        assert!(
            !block_after_css(sheet, ".perm-more {").is_empty(),
            "the waiting count has no dress of its own"
        );
        assert_eq!(
            window.matches(r#""ask.more":"#).count(),
            4,
            "the waiting count is missing from a language (four tables ship \
             beside the Korean the calls carry)"
        );
    }

    /// The agents an agent started are drawn under it, and no row is ever lost
    /// on the way.
    ///
    /// Orca's agent-row lineage (`useWorktreeAgentRows-BZzQmOQU.js:14-100`) —
    /// not its worktree lineage, which is a different feature about which
    /// workspace was cut from which. Three things have to hold together or the
    /// tree is either empty or a lie:
    ///
    ///   1. **Somebody records the edge.** Orca reads it out of an
    ///      orchestration database it keeps anyway; this window has none, so
    ///      the launch writes it down at the one moment the fact exists. There
    ///      is exactly one road — an agent quick command, which belongs to a
    ///      pane's own menu — and the gate pins that road end to end rather
    ///      than pinning a field that nothing fills.
    ///   2. **The shape is decided once, in Rust.** Depth, the sibling flags
    ///      and the child count come from `zerocode_core::agent_lineage`, whose
    ///      own tests pin the invariants. The window reads the answer and does
    ///      no arithmetic of its own — a second counter is how the chip comes
    ///      to say three over two visible rows.
    ///   3. **No row disappears.** Every bad edge is repaired by PROMOTION —
    ///      an orphan becomes a root, a cycle is cut at one edge — and never by
    ///      dropping the row. A card that vanishes takes a running agent off
    ///      the only surface built to find it, and the person cannot even tell
    ///      there is something missing.
    #[test]
    fn the_agents_a_pane_started_are_drawn_under_it_and_never_dropped() {
        let shell = shipped_backend();
        let (shipped, _) = shell.split_once("#[cfg(test)]").unwrap_or((shell, ""));
        let cards = include_str!("../../../zerocode-core/src/board.rs");
        let lineage = include_str!("../../../zerocode-core/src/agent_lineage.rs");
        let (rules, checks) = lineage.split_once("#[cfg(test)]").unwrap_or((lineage, ""));
        let window = window_source();

        if window.contains("function agentGraphModel(columns, places, reviews") {
            let graph = block_after(window, "function agentGraphModel(");
            assert!(
                graph.contains("entry.card.parent")
                    && graph.contains("const children = new Map();")
                    && graph.contains("if (!placed.has(entry.card.pane)) place(entry, 0);")
                    && graph.contains("!visiting.has(child.card.pane)"),
                "the graph can lose an orphan or cycle, or stopped reading spawned-by edges:\n{graph}"
            );
            assert!(
                window.contains(r#"parent: pane.parent == null ? "" : `term:${pane.parent}`,"#),
                "the window no longer turns the backend parent handle into a graph pane key"
            );
            let quick = block_after(window, "function runQuickCommand(command, term) {");
            assert!(
                quick.contains("launchAgentTab({") && quick.contains("parent: term,"),
                "an agent quick command stopped recording its spawning pane:\n{quick}"
            );
            return;
        }

        // ---- 1. the one road that records an edge -------------------------
        //
        // The launch takes a parent and writes it down; a pane naming itself
        // is refused at the door rather than left for the tree rules to untie
        // on every paint.
        let launching = block_after(shipped, "fn launch_agent_tab(");
        assert!(
            launching.contains("parent: Option<TermId>"),
            "`launch_agent_tab` no longer takes the pane that asked for it, so \
             nothing can record a subagent edge:\n{launching}"
        );
        assert!(
            launching.contains("if let Some(above) = parent.filter(|above| *above != term) {")
                && launching.contains("state.pane_parents().insert(term, above);"),
            "the launch stopped recording who asked for the pane, or stopped \
             refusing a pane that names itself:\n{launching}"
        );
        // And the window's one producer: the quick-command menu belongs to a
        // pane, so the agent it starts was started BY that pane.
        let quick = block_after(window, "function runQuickCommand(command, term) {");
        assert!(
            quick.contains("launchAgentTab({") && quick.contains("parent: term,"),
            "an agent quick command no longer hands over the pane its menu \
             belongs to — the board's tree has no source left:\n{quick}"
        );

        // ---- 2. the shape is Rust's, and the window only reads it ----------
        for field in [
            "pub parent: String,",
            "pub lineage: crate::agent_lineage::Lineage,",
        ] {
            assert!(
                cards.contains(field),
                "`{field}` left BoardCard, so the tree cannot cross the wire"
            );
        }
        assert!(
            shipped.contains("parent: Option<TermId>,")
                && shipped.contains("parent: parents.get(term).copied(),"),
            "`pane_agents` stopped reporting which pane asked for each pane"
        );
        // The window spells a handle the way a card names itself, and reads
        // the depth it was given rather than deriving one from `parent`.
        assert!(
            window.contains(r#"parent: pane.parent == null ? "" : `term:${pane.parent}`,"#),
            "the window no longer turns a terminal handle into the pane id a \
             card answers to"
        );
        let drawing = block_after(window, "function boardCardNode(");
        assert!(
            drawing.contains("card.lineage.child_count > 0")
                && drawing.contains(
                    r#"node.style.setProperty("--card-depth", String(card.lineage.depth));"#
                ),
            "the card stopped reading the lineage Rust computed:\n{drawing}"
        );
        assert!(
            !drawing.contains("card.parent"),
            "the card reads the raw parent, so it can indent a row Rust \
             promoted to a root:\n{drawing}"
        );
        // No second copy of the indent, either: the step is the sidebar's own
        // token, so the two trees in this window cannot drift apart.
        assert!(
            include_str!("../../../../ui/shell.css")
                .contains("margin-left: calc(var(--card-depth, 0) * var(--nav-indent));"),
            "the board's indent stopped being the sidebar's measured step"
        );

        // ---- 3. no row disappears -----------------------------------------
        //
        // The column build hands EVERY chosen card through the arrangement and
        // takes the answer back by index. A `filter` here would be a row
        // silently dropped, which is the one thing this feature must never do.
        let grouping = block_after(cards, "pub fn columns(");
        assert!(
            grouping.contains("crate::agent_lineage::arrange(&rows)")
                && grouping.contains("chosen[placed.index].clone()"),
            "the columns no longer arrange by the tested rules:\n{grouping}"
        );
        assert!(
            !grouping.contains("placed.filter") && !grouping.contains(".retain("),
            "the column build grew a way to drop an arranged row:\n{grouping}"
        );
        // The repairs are promotions. Both spellings are named, because both
        // are places a well-meaning edit would reach for a `continue`.
        assert!(
            rules.contains("Some(found) if found != index => Some(found),")
                && rules.contains("parent[index] = None;"),
            "the lineage rules stopped repairing a bad edge by promotion"
        );
        assert!(
            !rules.contains(".filter(") && !rules.contains(".retain("),
            "something in the lineage rules can now drop a row instead of \
             promoting it:\n{rules}"
        );
        // And the invariant is asked of the rules themselves, in the crate
        // where they live — a gate that only reads source cannot prove a
        // permutation.
        assert!(
            checks.contains("fn no_row_ever_disappears()")
                && checks.contains("assert_eq!(drawn.len(), rows.len()"),
            "the lineage crate stopped asserting that every row comes back"
        );
        // The window's fold rides that same tree order rather than walking a
        // graph of its own, and it forgets a fold whose branch is gone —
        // otherwise a card that starts a NEW subagent hides it on arrival.
        let column = block_after(
            window,
            "function boardColumnNode(column, now, reviews, places) {",
        );
        assert!(
            column.contains("if (foldedAt !== null && card.lineage.depth > foldedAt) continue;"),
            "the fold stopped reading the depth Rust ordered the cards by:\n{column}"
        );
        assert!(
            block_after(window, "async function paintBoardView(")
                .contains("if (!stillParents.has(pane)) boardFolded.delete(pane);"),
            "a fold outlives the branch it folded"
        );
        // A closed pane forgets only its OWN parent. Erasing the panes it
        // started would be the promotion rule written a second time, here,
        // where nothing tests it.
        let closing = block_after(shipped, "fn forget_term_state(");
        assert!(
            closing.contains("state.pane_parents().remove(&term);")
                && !closing.contains("pane_parents().retain"),
            "closing a pane no longer forgets who started it, or started \
             erasing the panes it started:\n{closing}"
        );

        // ---- and the words, in every language ------------------------------
        // `board.subagents`는 Orca의 어휘("서브에이전트 {{count}}개")이고,
        // 카드의 접기 단추와 오케스트레이션 타일이 **같은** 낱말을 쓴다 — 한
        // 사실을 두 낱말로 부르면 두 그림이 서로 다른 제품처럼 읽힌다.
        let keys = [
            "board.subagents",
            "board.childrenShow",
            "board.childrenHide",
        ];
        for language in ["en", "ja", "zh", "es"] {
            let catalog = block_after(window, &format!("  {language}: {{"));
            for key in keys {
                assert!(
                    catalog.contains(&format!("\"{key}\":")),
                    "`{key}` is missing from the {language} catalog"
                );
            }
        }
        for key in keys {
            assert!(
                window.contains(&format!("t(\"{key}\", ")),
                "`{key}` is in every catalog but nothing on screen reads it"
            );
        }
    }

    /// The board's ontology is a checked source contract. Without this gate
    /// the UI quietly grows a sixth state, a third relationship, or a second
    /// meaning for "running".
    ///
    /// The vocabulary it holds — Project ▸ Workspace ▸ Agent ▸ Subagent,
    /// containment beside lineage, `needs-attention` as a state, a repaint
    /// only when the picture changes, rendered pixels as the evidence — was
    /// read out of a design note until 2026-09-21. The notes stay off the
    /// public tree, so the promises are spelled here, beside the code they
    /// hold, and what is left below is the half that was ever about code.
    #[test]
    fn the_agent_board_implements_its_documented_ontology() {
        let markup = include_str!("../../../../ui/index.html");
        let window = window_source();

        assert!(
            markup.contains(r#"class="agent-graph-run""#)
                && markup.contains(r##"<use href="#i-orbit"></use>"##)
                && !markup.contains(r#"class="agent-graph-live""#),
            "the header turned the run count back into an agent activity state"
        );
        assert!(
            window.contains("function agentGraphFoldedActivities(")
                && window.contains("function agentGraphBreadcrumbNode(")
                && window.contains("agentGraphExpandedTimelines"),
            "cards and detail stopped sharing the folded activity/breadcrumb ontology"
        );
        for language in ["en", "ja", "zh", "es"] {
            let catalog = block_after(window, &format!("  {language}: {{"));
            for key in [
                "board.graph.run",
                "board.graph.failed",
                "board.graph.breadcrumb",
                "board.graph.moreActivities",
            ] {
                assert!(
                    catalog.contains(&format!("\"{key}\":")),
                    "`{key}` is missing from the {language} catalog"
                );
            }
        }
    }

    /// A diagram is laid out in Rust and drawn as elements, never as markup.
    ///
    /// Orca bundles `mermaid` — ~1,500 lines of core plus twenty chunks, loaded
    /// lazily and parsed on the first diagram — and then runs DOMPurify over the
    /// SVG **string** it gets back, because a string from a general-purpose
    /// engine can contain anything (`MermaidBlock-O_45bwHQ.js`, 1.4.164).
    ///
    /// This window makes that filter unnecessary instead of running it:
    /// `render_mermaid` answers with placed marks, and each mark becomes an
    /// element whose label enters through `textContent`. So the gate is on the
    /// shape that holds the property:
    ///
    ///   1. **No markup on the path.** Not one `innerHTML` between the marks
    ///      arriving and the diagram being on screen — otherwise the argument
    ///      above becomes a claim rather than a fact.
    ///   2. **Labels go in as text.** `Mark::Text` reaches `textContent`.
    ///   3. **The geometry stays in Rust.** The window places nothing itself, so
    ///      the layout is testable in the language that owns it.
    ///   4. **Both of Orca's entry points reach it** — a `.mmd` file's rich view
    ///      and a ```mermaid fence inside markdown.
    #[test]
    fn a_diagram_is_placed_in_rust_and_drawn_without_markup() {
        let source = window_source();

        // 1 + 2. Every function between the marks arriving and the picture.
        for opener in [
            "function markNode(mark) {",
            "function diagramNode(drawing) {",
            "async function paintDiagram(into, source) {",
            "function paintMermaid(body, source) {",
            "function paintMarkdownDiagrams(body) {",
        ] {
            let body = block_after(source, opener);
            assert!(
                !body.contains("innerHTML"),
                "`{opener}` builds markup, which puts back the injection Orca \
                 needs DOMPurify for:\n{body}"
            );
        }
        let marks = block_after(source, "function markNode(mark) {");
        assert!(
            marks.contains("node.textContent = mark.text;"),
            "a diagram label no longer enters as text:\n{marks}"
        );
        // `createElementNS`, not `createElement`: an HTML `<rect>` inside an
        // `<svg>` parses fine and lays out as nothing, so the diagram is blank
        // with every attribute correct — the failure this window's gates exist
        // to catch, since attributes are not evidence.
        for built in [
            marks,
            block_after(source, "function diagramNode(drawing) {"),
        ] {
            assert!(
                !built.contains("document.createElement("),
                "a diagram element is built outside the SVG namespace, so it \
                 will not draw:\n{built}"
            );
        }
        // Every kind the core emits is handled here. Named, not counted: a count
        // breaks when a shape is legitimately added and passes when one is
        // silently dropped.
        let core = include_str!("../../../zerocode-core/src/mermaid.rs");
        let (emitted, _) = core.split_once("#[cfg(test)]").unwrap_or((core, ""));
        let vocabulary = emitted
            .split_once("pub enum Mark {")
            .map(|(_, rest)| rest)
            .unwrap_or_default();
        for kind in ["rect", "polygon", "polyline", "text"] {
            let variant = format!("{}{}", kind[..1].to_uppercase(), &kind[1..]);
            assert!(
                vocabulary.contains(&format!("    {variant} {{")),
                "`Mark::{variant}` left the core, so this gate is checking a \
                 shape that no longer exists"
            );
            assert!(
                marks.contains(&format!(r#"mark.mark === "{kind}""#)),
                "the window draws no `{kind}` mark, so that part of every \
                 diagram is missing:\n{marks}"
            );
        }

        // 3. The window asks for the layout; it does not compute one. Named
        // rather than counted: the point is which call places the marks.
        let drawn = block_after(source, "async function paintDiagram(into, source) {");
        assert!(
            drawn.contains(r#"invoke("render_mermaid", { source })"#),
            "the diagram is no longer laid out in Rust:\n{drawn}"
        );
        let shell = shipped_backend();
        let (shipped, _) = shell.split_once("#[cfg(test)]").unwrap_or((shell, ""));
        assert!(
            shipped.contains("fn render_mermaid(source: String)")
                && shipped.contains("zerocode_core::mermaid::render(&source)"),
            "`render_mermaid` no longer answers from the core's layout"
        );
        // A repaint that arrives after the element was thrown away must not
        // paint into a detached node: the call is asynchronous and a file can be
        // closed while it is in flight.
        assert!(
            drawn.contains("into.isConnected"),
            "a late diagram paints into a node that has left the document:\n{drawn}"
        );

        // 4. Both of Orca's doors. The extensions are its own
        // (store-BgJxB0hr.js:39114-39115).
        let kind = block_after(source, "function renderedAs(path) {");
        assert!(
            kind.contains(r#"extension === "mmd""#) && kind.contains(r#"extension === "mermaid""#),
            "a mermaid file no longer opens as a diagram:\n{kind}"
        );
        let viewer = block_after(source, "function paintFileView(tab) {");
        assert!(
            viewer.contains(r#"showing === "mermaid") paintMermaid(body, tab.text)"#),
            "the rich view of a `.mmd` file draws nothing:\n{viewer}"
        );
        assert!(
            viewer.contains("paintMarkdownDiagrams(body)"),
            "a diagram inside a markdown file stays a code fence:\n{viewer}"
        );
        let fences = block_after(source, "function paintMarkdownDiagrams(body) {");
        assert!(
            fences.contains(r#"pre.md-block[data-language="mermaid"]"#),
            "the fence sweep no longer matches what the markdown walker writes:\n{fences}"
        );

        // The two refusals are told apart, because the window says something
        // different for each and a single flag would make it guess.
        let note = block_after(source, "function diagramNote(undrawn) {");
        assert!(
            note.contains(r#"undrawn.why === "too_large""#)
                && note.contains("mermaid.tooLarge")
                && note.contains("mermaid.undrawn"),
            "an undrawn diagram no longer says which of the two reasons it is:\n{note}"
        );
    }

    /// The source control panel's commit graph, on the mermaid pane's
    /// contract: the layout lives in Rust, the window draws elements.
    ///
    /// Measured on Orca **1.4.169**: `buildGitHistoryViewModels` threads each
    /// commit's lanes out of its predecessor's (SourceControl-e46DLHZz.js:2773),
    /// `GitHistoryGraphSvg` turns them into 11×24 swimlanes with 5px curves
    /// and a 3.5px dot (:2886), and the whole conversation with git is five
    /// invocations in a fixed order ending in one `-z` log
    /// (out/main/index.js:106478-106760). All of that is
    /// `zerocode_core::git_graph` plus `read_git_history` here; what this
    /// gate holds is the seam:
    ///
    ///   1. **The geometry stays in Rust.** The window's `historyRow` builds
    ///      SVG elements from `row.paths`/`row.circles` verbatim — no
    ///      `innerHTML`, no HTML-namespace `createElement`, no layout math.
    ///   2. **Ink is spent as tokens.** Orca's eight `--git-graph-*` colours
    ///      (I18nProvider-DPbv01TU.css) sit in tokens.css at their measured
    ///      values, dark and light, and the window turns a colour name into
    ///      `var(--…)` — so a theme turn re-inks the graph without a repaint.
    ///   3. **The git conversation is the measured one** — `symbolic-ref`
    ///      for the branch, `for-each-ref` for the upstream, `merge-base`
    ///      for the seam, and the log in Orca's own record format.
    ///   4. **The seam rows and badges keep their dress**: boundary rows
    ///      mute, two badges then a counted overflow, remote twins folded.
    #[test]
    fn the_commit_graph_is_laid_out_in_rust_and_inked_by_token() {
        let source = window_source();

        // 1. Elements from geometry, nothing invented on the way. The row's
        // own container is HTML and welcome to be; the marks are not — an
        // HTML-namespace `<path>` parses fine and draws nothing, so each of
        // the three SVG parts must enter through `createElementNS`.
        let row = block_after(source, "function historyRow(row) {");
        assert!(
            !row.contains("innerHTML"),
            "`historyRow` builds markup, which is the drawing path this \
             contract exists to forbid:\n{row}"
        );
        for mark in ["\"svg\"", "\"path\"", "\"circle\""] {
            assert!(
                row.contains(&format!("document.createElementNS(GRAPH_NS, {mark})")),
                "a graph {mark} is built outside the SVG namespace, so it \
                 will not draw:\n{row}"
            );
        }
        for handed in [
            r#"stroke.setAttribute("d", path.d);"#,
            r#"circle.setAttribute("cx", held.cx);"#,
            r#"svg.setAttribute("viewBox", `0 0 ${row.width} ${row.height}`);"#,
        ] {
            assert!(
                row.contains(handed),
                "the window no longer draws the geometry it was handed \
                 (missing `{handed}`):\n{row}"
            );
        }
        let asked = block_after(source, "async function refreshHistory() {");
        assert!(
            asked.contains(r#"invoke("git_history", { limit: historyLimit })"#),
            "the graph is no longer laid out in Rust:\n{asked}"
        );
        // The constants the drawing depends on live in the core, named as
        // Orca names them — if they leave, the window above is drawing a
        // layout nobody computes.
        let core = include_str!("../../../zerocode-core/src/git_graph.rs");
        let (core, _) = core.split_once("#[cfg(test)]").unwrap_or((core, ""));
        for held in [
            "pub const SWIMLANE_HEIGHT: f64 = 24.0;",
            "pub const SWIMLANE_WIDTH: f64 = 11.0;",
            "const CURVE_RADIUS: f64 = 5.0;",
            "const CIRCLE_RADIUS: f64 = 3.5;",
        ] {
            assert!(core.contains(held), "the core lost `{held}`");
        }

        // 2. The eight measured colours, in both treatments, spent as vars.
        let tokens = include_str!("../../../../ui/tokens.css");
        for (token, dark) in [
            ("--git-graph-ref", "#3794ff"),
            ("--git-graph-remote-ref", "#b66dff"),
            ("--git-graph-base-ref", "#ea5c00"),
            ("--git-graph-lane-1", "#ffb000"),
            ("--git-graph-lane-2", "#dc267f"),
            ("--git-graph-lane-3", "#ce9178"),
            ("--git-graph-lane-4", "#40b0a6"),
            ("--git-graph-lane-5", "#b66dff"),
        ] {
            assert!(
                tokens.contains(&format!("{token}: {dark};")),
                "the graph token `{token}` left its measured dark value {dark}"
            );
        }
        for light in ["--git-graph-ref: #007acc;", "--git-graph-lane-3: #994f00;"] {
            assert!(
                tokens.contains(light),
                "the light treatment lost its measured override `{light}`"
            );
        }
        let paint = block_after(source, "function graphPaint(color) {");
        assert!(
            paint.contains("return `var(--${color})`;"),
            "a colour identifier is no longer spent as its token:\n{paint}"
        );

        // 3. The measured conversation, in the shipped half.
        let shell = shipped_backend();
        let (shipped, _) = shell.split_once("#[cfg(test)]").unwrap_or((shell, ""));
        for said in [
            "\"symbolic-ref\", \"--quiet\", \"--short\", \"HEAD\"",
            "--format=%(upstream)%00%(upstream:short)",
            "\"merge-base\", &current.revision, &remote.revision",
            "\"--topo-order\"",
            "\"--decorate=full\"",
            "git_graph::COMMIT_FORMAT",
            "git_graph::history_rows(",
        ] {
            assert!(
                shipped.contains(said),
                "`read_git_history` no longer holds the measured git \
                 conversation (missing `{said}`)"
            );
        }

        // 4. The dress: seams mute, badges fold and count.
        let css = include_str!("../../../../ui/shell.css");
        assert!(
            css.contains(".history-row.is-boundary .history-subject"),
            "the Incoming/Outgoing seam rows no longer step back"
        );
        let badges = block_after(source, "function historyRefs(references) {");
        assert!(
            badges.contains("kept.slice(0, 2)")
                && badges.contains("`+${kept.length - 2}`")
                && badges.contains(r#"reference.id.startsWith("refs/remotes/")"#),
            "the badges lost their fold, their cap, or their overflow count:\n{badges}"
        );
        // And the panel actually reaches for the graph when it wakes.
        let panel = block_after(
            source,
            "async function refreshScm({ uncapped = false } = {}) {",
        );
        assert!(
            panel.contains("void refreshHistory();"),
            "opening source control no longer refreshes the graph:\n{panel}"
        );
    }

    /// An unattended pane cannot answer a credential prompt, so Git is told.
    ///
    /// The guard rides the launch token, which is minted for a launched agent
    /// and nothing else — the same line Orca draws ("unattended agents must
    /// fail instead of looping on OS credential prompts; user terminals keep
    /// normal Git behavior", `main/ipc/pty.ts:1783`). A person's own shell
    /// keeps Git's normal behaviour, which is why this pin reads WHERE the
    /// guard sits and not merely that it exists.
    ///
    /// And p10k's wizard is seeded off for every pane: it blocks shell startup,
    /// which blocks the launch command queued behind it.
    #[test]
    fn an_unattended_pane_gets_gits_guard_and_no_first_run_wizard() {
        let backend = include_str!("../../src/hooks.rs");
        let (shipped, _) = backend.split_once("#[cfg(test)]").unwrap_or((backend, ""));
        let building = block_after(shipped, "pub fn pty_env(");
        let guarded = building
            .split_once("if let Some(token) = launch_token {")
            .map(|(_, tail)| tail)
            .unwrap_or_default();
        assert!(
            guarded.contains("zerocode_core::git_prompt::guard_env("),
            "Git's credential guard left the launched-agent branch, so either \
             an unattended pane can hang on a prompt or a person's terminal \
             lost its own:\n{building}"
        );
        assert!(
            building.contains("if std::env::var_os(P10K_WIZARD_OFF).is_none() {"),
            "the p10k wizard is seeded over somebody's own setting, or not at \
             all:\n{building}"
        );
    }

    /// Every `<select>` in this window wears one face, and carries its mark.
    ///
    /// Measured before the rule existed: fifty-four selects wore TEN faces and
    /// seventeen of them drew the platform's own control, because
    /// `appearance: none` lived inside five container rules and every select
    /// outside them kept the OS box. The reset belongs to the control.
    ///
    /// And the mark belongs to the control too. A `<select>` cannot hold a
    /// pseudo-element, so the settings surfaces drew the chevron on the ROW —
    /// which put it 16px outside the box whenever the row was padded, measured
    /// on the usage plan card. It rides the control's own background now, which
    /// is why nothing here may set `background` as a SHORTHAND on a select: one
    /// `background: none` erases the image and takes the mark with it.
    #[test]
    fn one_select_face_carries_its_own_mark() {
        // Read the RULES, not the prose: these blocks carry comments that
        // name the very declarations being forbidden below.
        let rules = strip_comments(include_str!("../../../../ui/shell.css"));
        let base = block_after_css(&rules, "select {");
        for needle in [
            "appearance: none;",
            "background-image: var(--chevron-down);",
            "--select-room:",
            "padding-inline-end: var(--select-room);",
        ] {
            assert!(
                base.contains(needle),
                "the one select face lost `{needle}`:\n{base}"
            );
        }
        // The row's mark is gone, not merely moved: a second drawer would put
        // two chevrons on every settings select.
        assert!(
            !rules.contains(".settings-field:has(select)"),
            "a row still draws a chevron for a select that now carries its own"
        );
        // A shorthand on any select face erases the image the mark rides.
        for face in [
            ".wsclean-filter {",
            ".skills-view textarea {",
            ".scm-compare-base {",
            ".vault-toggle select {",
            ".emulator-pick {",
            ".auto-view .settings-input {",
        ] {
            let block = block_after_css(&rules, face);
            assert!(
                !block.contains("background:"),
                "`{face}` sets `background` as a shorthand, which erases the \
                 chevron the control carries:\n{block}"
            );
        }
        // And the mark's geometry is declared beside the ink it is stroked in,
        // in both themes, because a data URI cannot read a custom property.
        let tokens = include_str!("../../../../ui/tokens.css");
        assert_eq!(
            tokens.matches("--chevron-down:").count(),
            2,
            "the chevron is not declared once per theme, so one theme draws it \
             in the other theme's ink"
        );
    }

    /// A run's page is placed by the ENVELOPE's checkout, not by a lookup.
    ///
    /// The window can only ask which checkout a terminal belongs to if that
    /// terminal already has a tab, and a run can announce itself before one
    /// does — a restored tab, a pane opened in the background. The envelope
    /// has carried the answer since the launch env was written
    /// (`ZEROCODE_WORKTREE_ID` is the worktree's path), so it travels with the
    /// run and the lookup is only the fallback. And the page's SEAT has to
    /// exist in that checkout's stage: groups live in per-checkout trees, so a
    /// group number borrowed from whatever is in front names a pane the home
    /// tree never heard of, and `paneTabs` never lists the page at all.
    #[test]
    fn a_runs_page_is_placed_by_the_envelope_and_seated_where_it_belongs() {
        let shell = shipped_backend();
        let (shipped, _) = shell.split_once("#[cfg(test)]").unwrap_or((shell, ""));
        let payload = block_after(shipped, "struct WorkerOpened {");
        assert!(
            payload.contains("worktree: String,"),
            "the run's page travels without the checkout it ran in:\n{payload}"
        );
        assert!(
            shipped.contains("worktree: envelope.worktree_id.clone(),"),
            "the emit stopped filling the checkout from the hook envelope"
        );

        let window = window_source();
        // 페이지를 세우는 몸통은 이제 `openWorkerPage`에 산다 — 리스너는
        // 박자만 재고, 한 숨 안에 끝난 실행에는 페이지가 서지 않는다
        // (`a_nested_run_that_ends_in_a_breath_takes_no_tab`). 계약은 그대로다.
        let opening = block_after(window, "function openWorkerPage(");
        assert!(
            opening.contains("const home = worktree || parent?.worktree || activeWorktreePath;"),
            "the page no longer prefers the envelope's own answer:\n{opening}"
        );
        assert!(
            opening.contains("const seat = parent?.pane ?? homeStageSeat(home);")
                && opening.contains("pane: seat,"),
            "the page takes whatever group is focused, which its own checkout \
             may not have:\n{opening}"
        );
        let seating = block_after(window, "function homeStageSeat(worktree) {");
        assert!(
            seating.contains("stageTrees.get(worktree)")
                && seating.contains("stageGroups(tree)[0]"),
            "the seat is no longer read from the home checkout's own tree:\n{seating}"
        );
    }

    /// A run with no mirror says so, instead of showing a command and nothing.
    ///
    /// The shim names the mirror by absolute path and falls through to the real
    /// agent when that path goes stale — deliberate, because losing the mirror
    /// must not take the terminal with it. What was missing is the other half
    /// of that sentence: the fall-through is documented as a *reported* outage
    /// and nothing reported it, so a person watching a nested run saw a command
    /// line, an empty page, and no way to tell a quiet run from broken
    /// plumbing ("아무것도 안보임").
    #[test]
    fn a_missing_mirror_is_said_and_not_merely_survived() {
        let backend = include_str!("../../src/hooks.rs");
        let (hooks_shipped, _) = backend.split_once("#[cfg(test)]").unwrap_or((backend, ""));
        // One spelling of the binary's path, so "can shims be written" and "is
        // the binary still there" cannot drift apart.
        let built = block_after(
            hooks_shipped,
            "fn build_mirror_shims() -> Option<(PathBuf, PathBuf)> {",
        );
        assert!(
            built.contains("mirror_bin()?"),
            "the mirror binary's path is spelled twice:\n{built}"
        );
        let ready = block_after(hooks_shipped, "pub fn mirror_ready() -> bool {");
        assert!(
            ready.contains("mirror_shims().is_some()") && ready.contains("is_file()"),
            "readiness stopped asking either whether the shims exist or whether \
             the binary they name still does:\n{ready}"
        );

        let shell = shipped_backend();
        let (shipped, _) = shell.split_once("#[cfg(test)]").unwrap_or((shell, ""));
        assert!(
            block_after(shipped, "fn mirror_ready() -> bool {").contains("hooks::mirror_ready()"),
            "the window's door to readiness answers something else"
        );

        let window = window_source();
        // Asked once for the window's lifetime: this is a file stat behind a
        // wire, and the answer only changes when a build replaces the bundle.
        let asking = block_after(window, "async function askMirrorReady() {");
        assert!(
            asking.contains("if (mirrorReady !== null) return mirrorReady;")
                && asking.contains("mirrorReady = true;"),
            "readiness is re-asked per paint, or an unaskable machine is \
             reported as having no mirror:\n{asking}"
        );
        // And the page says it while the run is still going — after it ends the
        // output itself is the answer.
        let painting = block_after(window, "function paintWorkerView(tab) {");
        assert!(
            painting.contains("worker-no-mirror") && painting.contains("mirrorReady === false"),
            "the page no longer says why it has nothing to show:\n{painting}"
        );
    }

    /// A nested agent launched by an orchestrator must become a ledger worker
    /// in either direction. The mirror is useful for a person's unseated
    /// shell, but it is not a degraded worker when authority is unavailable.
    #[test]
    fn an_orchestrator_cannot_fall_back_to_a_pipe_shaped_agent() {
        let mirror = include_str!("../../src/bin/zerocode-mirror.rs");
        let launch = block_after(mirror, "fn main() {");
        assert!(
            launch.contains("refuses_pipe_worker(probe, orchestration_seat_from_env())")
                && launch.contains("zerocode-orc task-create")
                && launch.contains("zerocode-orc worker-start")
                && launch.contains("do not fall back"),
            "the nested launch no longer points both orchestration directions at the ledger:\n{launch}"
        );
        let seat = block_after(mirror, "fn orchestration_seat_from_env() -> bool {");
        for authority in ["TEAM_ID_VAR", "TEAM_PANE_VAR", "TEAM_TOKEN_VAR"] {
            assert!(
                seat.contains(authority),
                "the pipe guard stands without {authority}:\n{seat}"
            );
        }
        let refusal = block_after(
            mirror,
            "const fn refuses_pipe_worker(probe: bool, orchestration_seat: bool) -> bool {",
        );
        assert!(
            refusal.contains("orchestration_seat && !probe"),
            "the guard blocks probes or permits delegated work:\n{refusal}"
        );
    }

    /// A mirror pane reads only what the mirror directory owns, as `tail`.
    ///
    /// The command is the webview's to call, so the path is held to the
    /// mirror directory the same way a commit id is held to hex — and the
    /// pane is the COMMAND `tail`, not a shell handed a line to type, which
    /// is what keeps the hidden-Enter rule untouched by this feature (1-fm).
    #[test]
    fn a_mirror_pane_reads_only_the_mirror_directory_and_types_nothing() {
        let shell = shipped_backend();
        let (shipped, _) = shell.split_once("#[cfg(test)]").unwrap_or((shell, ""));
        let opening = block_after(shipped, "fn open_mirror_term(");
        for needle in ["!held.starts_with(&mirrors)", "\"tail\"", "\"-F\""] {
            assert!(
                opening.contains(needle),
                "the mirror pane lost `{needle}`:\n{opening}"
            );
        }
        // And the shims ride every terminal's PATH through the one env door.
        let backend = include_str!("../../src/hooks.rs");
        let (hooks_shipped, _) = backend.split_once("#[cfg(test)]").unwrap_or((backend, ""));
        assert!(
            hooks_shipped.contains("ZEROCODE_MIRROR_DIR")
                && hooks_shipped.contains("mirror_shims()"),
            "the terminals no longer wear the mirror shims"
        );
    }

    /// A finished run's page shows a SCREEN, never the bytes spelled out.
    ///
    /// What a nested run hands back is what its program WROTE. Pasted into the
    /// page as characters, a run that painted itself arrived as rubble —
    /// `[2K`, `[1A`, `[?2026h`, reported 2026-08-21 against a finished
    /// `claude --resume` — because the escape that steers is unprintable and
    /// everything steering on it survives as a letter.
    ///
    /// The window owns no reader for those bytes and must not grow one: every
    /// screen it draws is a frame this backend's emulator made. So the finished
    /// page asks that same emulator and is painted from the same delta
    /// [`term_snapshot`] hands a live pane.
    #[test]
    fn a_finished_run_is_drawn_by_the_emulator_and_never_spelled_out() {
        let shell = shipped_backend();
        let (shipped, _) = shell.split_once("#[cfg(test)]").unwrap_or((shell, ""));
        let door = block_after(shipped, "fn worker_screen(");
        assert!(
            door.contains("zerocode_pty::drawn("),
            "the finished page's screen is drawn by something that is not the \
             terminal emulator:\n{door}"
        );

        let window = window_source();
        let asking = block_after(window, "function askWorkerScreen(tab) {");
        assert!(
            asking.contains(r#"invoke("worker_screen", {"#)
                && asking.contains("gridSize() ?? DEFAULT_TERMINAL_GRID"),
            "the window stopped asking the emulator, or stopped asking at the \
             size the run was actually drawn at:\n{asking}"
        );
        assert!(
            block_after(window, r#"listen("worker:done", (event) => {"#)
                .contains("askWorkerScreen(tab);"),
            "nothing asks what a finished run's bytes drew"
        );

        let body = block_after(window, "function workerBodyNode(tab) {");
        assert!(
            body.contains(r#"box.className = "terminal worker-screen";"#),
            "the page no longer stands a terminal for a run that painted \
             itself:\n{body}"
        );
        // And the text road survives for a log that never steered a cursor: a
        // screen `rows` tall would drop every line that scrolled off its top.
        assert!(
            body.contains("if (!run.screen) {") && body.contains(r#""worker-output""#),
            "a plain log lost the text it was:\n{body}"
        );
        assert!(
            block_after(window, "function paintWorkerScreen(pane) {")
                .contains(".apply(held.delta)"),
            "the screen is built and never painted"
        );
        // A view left holding a host nobody can see keeps observing it. The
        // page's host is one per PANE (`docHost`), so the moment its children
        // are replaced is the moment the screen on it has to be given back.
        assert!(
            block_after(window, "function paintWorkerView(tab) {")
                .contains("dropWorkerScreen(tab.pane);"),
            "a repainted page leaves its last screen observing a dead host"
        );
    }

    /// The pop-out reads screens; it never resizes them.
    ///
    /// It runs the same document, so its previews hold real term views — and
    /// its window-resize road once walked them and resized the actual pty to
    /// a preview card's grid, which is what "팝아웃으로 열었다가 들어오면
    /// 깨지는" was: the shell squeezed to a card, and the main window, whose
    /// own size never changed, with no reason to resize it back.
    #[test]
    fn the_popout_never_resizes_a_terminal_it_only_reads() {
        let window = window_source();
        let sizing = block_after(window, "function resizeTermTab(term) {");
        assert!(
            sizing.contains("if (isPopout) return;"),
            "the pop-out can resize the real pty to a preview's grid \
             again:\n{sizing}"
        );
    }

    /// A child this window will never read again walks the reaping door.
    ///
    /// Five zombies were found under one live session — every one a system
    /// opener spawned and dropped, standing in the process table for the
    /// window's whole life (1-fj). The main wiring has exactly three bare
    /// children — `run_text_generation`, waited, and the `zerocode-pick`
    /// helper (t-2982), spawned with `kill_on_drop` and waited or killed on
    /// every arm of its road, and the watchdog's bounded native sampler
    /// (t-3232), reaped on completion or killed and waited on timeout. The
    /// fourth is the desktop operator's `run` (`desktop_run`): both streams
    /// read to the end on their own threads, waited to its budget and
    /// killed and waited past it. The sixth is a wire session's child
    /// (`wire_runtime`): its stdout is read to the end on the session's
    /// reader thread, and the session kills and waits it when it is stopped
    /// or dropped.
    /// Emulator children moved behind the shared
    /// `SessionControl`: every adapter installs its child there and the one
    /// stop path kills and waits it. Everything truly fire-and-forget goes
    /// through `zerocode_core::reap::spawn_forgotten`.
    #[test]
    fn a_child_nobody_reads_is_still_collected() {
        let shell = shipped_backend();
        let (shipped, _) = shell.split_once("#[cfg(test)]").unwrap_or((shell, ""));
        assert_eq!(
            shipped.matches(".spawn()").count(),
            6,
            "a new bare child appeared in main.rs"
        );
        let wire = include_str!("../../src/wire_runtime.rs");
        let (wire, _) = wire.split_once("#[cfg(test)]").unwrap_or((wire, ""));
        assert!(
            wire.contains("fn kill(&self) {")
                && wire.contains("let _ = child.kill();")
                && wire.contains("let _ = child.wait();")
                && wire.contains("impl Drop for WireSession {"),
            "a wire session's child is no longer killed and waited when the \
             session goes:\n{wire}"
        );
        let files = include_str!("../../src/sftp_runtime.rs");
        assert!(
            files.contains(".kill_on_drop(true)") && files.contains("ProcessSftp::open(process)"),
            "the SFTP subsystem must be owned and killed with its session"
        );
        let sampling = block_after(shipped, "pub(crate) fn sample_main_thread()");
        for held in [
            "child.try_wait()",
            "child.kill()",
            "child.wait()",
            "Limits::SAMPLE_TIMEOUT_MS",
        ] {
            assert!(sampling.contains(held), "the bounded sampler lost {held}");
        }
        let picking = block_after(shipped, "async fn run_pick_helper(");
        assert!(
            picking.contains(".kill_on_drop(true)")
                && picking.matches("child.kill().await").count() >= 3
                && picking.matches("child.wait().await").count() >= 3,
            "the pick helper is a child nobody collects:\n{picking}"
        );
        let desktop = block_after(shipped, "fn desktop_run(");
        for held in [
            "child.try_wait()",
            "child.kill()",
            "child.wait()",
            "desktop_run_ms(",
        ] {
            assert!(
                desktop.contains(held),
                "the desktop runner lost its bounded child owner: {held}"
            );
        }
        let android = include_str!("../../src/emulator/android.rs");
        for pump in ["fn pump_android_frames(", "fn pump_android_video("] {
            assert!(
                block_after(android, pump).contains("control.install_child"),
                "{pump} no longer hands its child to the shared owner"
            );
        }
        let ios = include_str!("../../src/emulator/ios.rs");
        // The iOS pump's spawning road is the still picture — its window road
        // starts no child at all.
        assert!(
            block_after(ios, "fn screenshot_picture(").contains("control.install_child"),
            "the iOS capture child no longer reaches the shared owner"
        );
        let sessions = include_str!("../../src/emulator/session.rs");
        let stopping = block_after(sessions, "pub fn kill_child(");
        for held in ["child.kill()", "child.wait()"] {
            assert!(
                stopping.contains(held),
                "the emulator owner no longer performs {held}:\n{stopping}"
            );
        }
        // And the one that remains genuinely waits: deadline, kill, wait.
        let generating = block_after(shipped, "fn run_text_generation(");
        for held in ["child.kill()", "child.wait("] {
            assert!(
                generating.contains(held),
                "the one permitted bare spawn no longer {held}s:\n{generating}"
            );
        }
        // The eight openers each say the door's name (the three newest are the
        // download row's 열기/표시 hands and the Obsidian vault opener).
        assert_eq!(
            shipped
                .matches("zerocode_core::reap::spawn_forgotten(opener)")
                .count(),
            8,
            "an opener stopped walking the reaping door"
        );
    }

    /// An agent launched as a COMMAND — `codex exec …` under a Bash tool — is
    /// drawn as a worker through the helper roster's own door (1-fh).
    ///
    /// No `SubagentStart` will ever announce it, so the command line is the
    /// only witness; what this gate pins is that the witness is the core's
    /// one classifier and that the row travels the roster's one emit — a
    /// second pipeline's symptom is always the same, one surface nobody was
    /// watching that does not follow.
    #[test]
    fn an_agent_run_as_a_command_walks_the_helper_roster() {
        let shell = shipped_backend();
        let (shipped, _) = shell.split_once("#[cfg(test)]").unwrap_or((shell, ""));
        for needle in [
            // The classifier is the core's, fed the Bash command alone.
            ".and_then(zerocode_core::hook::nested_agent_of)",
            // The row is named by the CALL, for finding again when that call
            // ends — never by the vendor alone, which gave two parallel runs
            // one id and let the first finish retire the wrong row.
            "let id_of = |call: &str| format!(\"run:{}:{}\", kind.slug(), call);",
            // Pushed, never replaced: two parallel runs of one vendor are two
            // rows…
            "running.push(hooks::SubagentRow {",
            // …and each finish retires exactly its own — or, for a payload
            // that names no call, the oldest running one of that vendor.
            "own.as_deref().is_none_or(|own| one.id == own)",
        ] {
            assert!(
                shipped.contains(needle),
                "the nested-agent road lost `{needle}`"
            );
        }
        // Same door as a real helper. Three sites may name this event — the
        // roster road, this one, and the departed-agent sweep — counted by
        // the event name itself so no reformatting can hide a fourth.
        assert_eq!(
            shipped.matches("\"hook:subagent\"").count(),
            3,
            "the helper roster's event grew or lost an emit site — a new one \
             is a second pipeline in waiting"
        );
    }

    /// A commit row opens into its files, and everything a row hands back to
    /// git goes through one narrow door (1-fg).
    ///
    /// Three invariants, each of which failed silently somewhere else once:
    /// the id check at the channel (a webview channel that lets any string
    /// onto a git command line is an argv anybody can reach), `-z` under the
    /// file list (a path may carry the tabs and newlines the default format
    /// delimits with), and a `version` that is never minted for committed
    /// blobs (its absence IS the diff tab's read-only signal — minting one
    /// would put a save button on history).
    #[test]
    fn a_commit_opens_only_through_the_hash_it_was_minted_with() {
        let shell = shipped_backend();
        let (shipped, _) = shell.split_once("#[cfg(test)]").unwrap_or((shell, ""));

        // Every command that takes an id from the webview checks it first.
        for door in [
            "async fn commit_files(",
            "async fn commit_file_diff(",
            "async fn open_commit_remote(",
        ] {
            let body = block_after(shipped, door);
            assert!(
                body.contains("history_hash(&id)?"),
                "`{door}` puts an unchecked webview string onto a git \
                 command line:\n{body}"
            );
        }
        let files = block_after(shipped, "async fn commit_files(");
        for flag in ["\"-z\"", "\"--name-status\"", "\"--root\"", "\"-M\""] {
            assert!(
                files.contains(flag),
                "the file list lost {flag} — hostile paths, root commits or \
                 renames stop reading correctly:\n{files}"
            );
        }
        let both = block_after(shipped, "fn commit_documents(");
        assert!(
            both.contains("version: None"),
            "a committed blob was handed a save stamp, which is a save \
             button on history:\n{both}"
        );

        // The window side: the panel refills from the cache on a repaint, and
        // the reopen road answers AT the commit rather than the working tree.
        let source = window_source();
        let rebuilt = block_after(source, "async function refreshHistory() {");
        assert!(
            rebuilt.contains("historyExpanded.has(row.item.id)"),
            "a repaint folds every open commit:\n{rebuilt}"
        );
        let reopened = block_after(source, "function reopenClosedTab() {");
        assert!(
            reopened.contains("openCommitFileDiff(tab.commit, tab.path,"),
            "a reopened commit diff answers with the working tree — the \
             right file, the wrong moment:\n{reopened}"
        );
    }

    #[test]
    fn an_orchestration_worker_belongs_to_its_worktree_not_the_leaders_split() {
        let backend = shipped_backend();
        let window = window_source();
        let seating = block_after(backend, "impl agent_teams::Host for TeamWindow {");
        assert!(
            seating.contains("let worker_host = agent_teams::take_worker_host_ask(token);")
                && seating.contains("let worker_surface = worker_host.is_some();")
                && seating.contains("if worker_surface {")
                && seating.contains("\"term:worker\"")
                && seating.contains("worktree: root.to_string_lossy().into_owned()")
                && seating.contains("} else {")
                && seating.contains("\"term:split\""),
            "the protocol worker and Agent Teams compatibility split no longer have distinct surfaces:\n{seating}"
        );
        let mounting = block_after(window, "listen(\"term:worker\", (event) => {");
        let mounting = mounting
            .split_once("/* An agent started another agent")
            .map_or(mounting, |(worker, _)| worker);
        let seating_term = block_after(window, "function seatLedgerManagedTerm(");
        // The move itself lives in `reseatTerm`, shared with t-3612's pane
        // following its process; the ledger's seating only names its extras.
        let reseating = block_after(window, "function reseatTerm(term, extra) {");
        let persistence = block_after(window, "function persistPaneLayouts(worktree) {");
        assert!(
            mounting.contains("await refreshWorktrees();")
                && mounting.contains("seatLedgerManagedTerm(term, worktree, agent);")
                && mounting.contains("paintWorktreeAgents();")
                && seating_term.contains("ledgerManaged: true")
                && seating_term.contains("return reseatTerm(term, {")
                && reseating.contains("Object.assign(held, extra);")
                && reseating.contains("{ focus: false, placement: \"tab\" }")
                && persistence.contains("!tab.ledgerManaged")
                && !mounting.contains("tileTermPane(")
                && mounting.contains("void roomForWorker("),
            "a worker reshapes or focuses the coordinator tab instead of mounting under its checkout:\n{mounting}"
        );
        // The one road that may move it afterwards is the placement seat's,
        // and only on an answer from a seat that acts (2026-09-20).
        let reseating_by_answer = block_after(window, "function reseatWorkerByAnswer(");
        let asking = block_after(window, "async function roomForWorker(");
        assert!(
            reseating_by_answer.contains("tileTermPane(")
                && reseating_by_answer.contains("detachedAgents.set(term, worktree);")
                && asking.contains("judged?.applied")
                && asking.contains("return \"tab\";"),
            "the placement seat's answer no longer moves the pane only when the seat acts:\n{asking}\n{reseating_by_answer}"
        );
        assert!(
            mounting.find("seatLedgerManagedTerm(term, worktree, agent);")
                < mounting.find("await refreshWorktrees();"),
            "the worker is painted before its term has a worktree owner:\n{mounting}"
        );
    }

    /// The placement seat's label reads the person's moves through one door
    /// (t-5806): the roads a person takes to move a pane report it, the
    /// roads the window takes to move one for its own reasons do not, and
    /// the window remembers a placed worker only while its answer waits.
    #[test]
    fn a_placed_workers_move_is_reported_by_the_person_roads_and_no_other() {
        let window = window_source();
        let backend = shipped_backend();
        // The book entry is made where the answer arrives, keyed by the term.
        let asking = block_after(window, "async function roomForWorker(");
        assert!(
            asking.contains("judged?.placed")
                && asking.contains(
                    "placedWorkers.set(term, { worker: seat.worker, seenAfterMs: judged.seenAfterMs,"
                ),
            "the surface no longer remembers which placed worker a term is, or the dwell the door named:\n{asking}"
        );
        // One door, and it forgets the worker on the first report.
        let door = block_after(window, "function noteWorkerRoomChange(term, room) {");
        assert!(
            door.contains("forgetPlacedWorker(term);")
                && door.contains(
                    "invoke(\"note_worker_room_change\", { worker: placed.worker, room })"
                ),
            "the move door reports twice, or names the wrong worker:\n{door}"
        );
        // The person's roads: a tab dragged (both drops), a tiled pane
        // closed, a parked worker revealed.
        let dragged = block_after(window, "function endTabDrag() {");
        assert_eq!(
            dragged
                .matches("noteWorkerRoomChange(draggedTerm, \"tab\")")
                .count(),
            2,
            "a drop no longer reports the placed worker's move:\n{dragged}"
        );
        let closed = block_after(window, "function closePaneLeaf(tab, going) {");
        assert!(
            closed.contains("noteWorkerRoomChange(going, \"background\")"),
            "closing a tiled worker no longer reports the move:\n{closed}"
        );
        let revealed = block_after(window, "async function focusAgentPane(");
        assert!(
            revealed.contains("noteWorkerRoomChange(term, \"tab\")"),
            "revealing a parked worker no longer reports the move:\n{revealed}"
        );
        // The window's own moves are not the person's.
        for road in [
            "function reseatWorkerByAnswer(",
            "function revealListedWorker(",
            "function parkTeamWorkers(",
            "function reseatTerm(term, extra) {",
        ] {
            assert!(
                !block_after(window, road).contains("noteWorkerRoomChange("),
                "a road the window takes on its own reports a person's move: {road}"
            );
        }
        // And a pane that ended is forgotten, so its worker id cannot be
        // reported for a pane that no longer exists — through the one helper
        // that also stops the pane's sight clock.
        assert_eq!(
            window.matches("placedWorkers.delete(term);").count(),
            1,
            "the placed book is emptied in one place"
        );
        assert_eq!(
            window.matches("forgetPlacedWorker(term);").count(),
            2,
            "the placed book is emptied on the report and on the pane's end, nowhere else"
        );
        // The door itself, and the beat that grades the quiet case.
        let room = block_after(backend, "pub(crate) async fn note_worker_room_change(");
        assert!(
            room.contains("room_changed(")
                && room.contains("&Wire::of_this_machine(),")
                && room.contains("rooms(),")
                && room.contains("crate::now_epoch_ms(),"),
            "the move door no longer grades through the one book:\n{room}"
        );
        let graded = block_after(backend, "pub(crate) fn room_changed(");
        assert!(
            graded.contains("Placement::of(room)")
                && graded.contains("PLACEMENT_LABEL_WINDOW_MS")
                && graded.contains("worker_placement::stood_in(placed.chosen, placed.applied)")
                && graded.contains("crate::systemone::record_rows(&PLACEMENT,"),
            "a move is graded outside the table's rooms, the seat's window or the seat's ledger road:\n{graded}"
        );
        let mark = block_after(backend, "fn label_row(");
        assert!(
            mark.contains("worker_placement::mark(placed.chosen, ended_in, seen)")
                && mark.contains("NOT_COMPARED.canonical")
                && mark.contains("LABEL.canonical: worker,"),
            "the placement label spells its mark or its name itself:\n{mark}"
        );
    }

    /// A pane nobody moved is graded only if a person was in front of it
    /// (t-6342): the surface reports a placed worker's pane once it has stood
